  local ConfigHttp = cloneref(game:GetService("HttpService"))
  -- The optional Gemini request is kept isolated from the redeem pipeline.
  pcall(function()
      if not (isfile and readfile) then return end
      local raw
      for _, fileName in ipairs({ CONFIG_FILE, LEGACY_CONFIG_FILE }) do
          if isfile(fileName) then
              raw = readfile(fileName)
              break
          end
      end
      if not raw then return end
      local saved = ConfigHttp:JSONDecode(raw)
      for key, kind in pairs(PERSISTED) do
          if type(saved[key]) == kind then settings[key] = saved[key] end
      end
      settings.submitAfter = math.clamp(math.floor(settings.submitAfter), 1, 5)
      local key = type(saved.toggleKey) == "string" and Enum.KeyCode[saved.toggleKey]
      if key then settings.toggleKey = key end
      if type(saved.triggers) == "table" then
          local list, has = {}, {}
          for _, word in ipairs(saved.triggers) do
              if type(word) == "string" and word ~= "" then
                  list[#list + 1] = word
                  has[word] = true
              end
          end
          settings.triggers = list
          local savedTriggerVersion = tonumber(saved.triggerDefaultsVersion) or 0
          if savedTriggerVersion < TRIGGER_DEFAULT_VERSION then
              -- Old builds accumulated noisy aliases. Start from the small,
              -- tested core instead.
              settings.triggers = table.clone(DEFAULT_TRIGGERS)
              settings.triggerDefaultsVersion = TRIGGER_DEFAULT_VERSION
          end
          if #settings.triggers == 0 then
              -- An empty saved list makes the redeemer look dead: it can hear
              -- announcements but has no phrase with which to start a code.
              settings.triggers = table.clone(DEFAULT_TRIGGERS)
              settings.triggerDefaultsVersion = TRIGGER_DEFAULT_VERSION
          end
      end
      settings.remoteFallback = saved.remoteFallback == true
      settings.dryRun = saved.dryRun == true
      settings.feedSilenceTimeout = math.clamp(math.floor(tonumber(saved.feedSilenceTimeout) or 60), 10, 600)
      settings.riddleApiKey = tostring(settings.riddleApiKey or ""):sub(1, 256)
      settings.riddleApiUrl = tostring(settings.riddleApiUrl or ""):sub(1, 256)
      settings.riddleApiModel = tostring(settings.riddleApiModel or ""):sub(1, 96)
      local legacyRiddleKey = tostring(saved.idleKey or "")
      if tostring(settings.riddleKey or "") == "" and legacyRiddleKey ~= "" then settings.riddleKey = legacyRiddleKey end
      for _, bindName in ipairs({ "scanKey", "riddleKey" }) do
          local bindValue = tostring(settings[bindName] or "")
          settings[bindName] = Enum.KeyCode[bindValue] and bindValue or ""
      end
      settings.idleKey = settings.riddleKey
      local validAdminKeys = {}
      for action, defaultKey in pairs(DEFAULT_ADMIN_KEYS) do
          local savedKey = type(settings.adminKeys) == "table" and tostring(settings.adminKeys[action] or "") or defaultKey
          validAdminKeys[action] = savedKey == "" and "" or (Enum.KeyCode[savedKey] and savedKey or defaultKey)
      end
      settings.adminKeys = validAdminKeys
      if settings.theme == "winter" then settings.theme = "christmas" end
      if settings.language ~= "fr" then settings.language = "en" end
      if settings.riddleApiModel == "" or settings.riddleApiModel == "gemini-2.0-flash" then
          settings.riddleApiModel = "gemini-3.8-flash"
      end
      if not settings.riddleApiUrl:lower():find("generativelanguage.googleapis.com", 1, true) then
          settings.riddleApiUrl = "https://generativelanguage.googleapis.com/v1beta/models"
          settings.riddleApiModel = "gemini-3.8-flash"
      end
      local validOverrides = {}
      if type(saved.riddleOverrides) == "table" then
          for key, value in pairs(saved.riddleOverrides) do
              if type(key) == "string" and type(value) == "string" then
                  local normalizedKey = key:lower():gsub("%s+", " "):match("^%s*(.-)%s*$") or ""
                  local normalizedValue = value:match("^%s*(.-)%s*$") or ""
                  if normalizedKey ~= "" and normalizedValue ~= "" then
                      validOverrides[normalizedKey] = normalizedValue
                  end
              end
          end
      end
      settings.riddleOverrides = validOverrides
  end)

  local function looseText(text)
      local out, map = {}, {}
      local gap = false
      for i = 1, #text do
          local ch = text:sub(i, i)
          if ch:match("%w") or ch == ":" then
              if gap and ch ~= ":" and #out > 0 then
                  out[#out + 1] = " "
                  map[#out] = i
              end
              gap = false
              out[#out + 1] = ch:lower()
              map[#out] = i
          else
              gap = true
          end
      end
      return table.concat(out), map
  end

  local sortedTriggers = {}
  local function rebuildTriggerCache()
      sortedTriggers = {}
      for _, t in ipairs(settings.triggers) do
          local loose = looseText(t)
          if loose ~= "" then sortedTriggers[#sortedTriggers + 1] = loose end
      end
      table.sort(sortedTriggers, function(a, b) return #a > #b end)
  end
  rebuildTriggerCache()

  local savePending = false
  local function writeConfig()
      if not writefile then return end
      pcall(function()
          local out = { version = 6, toggleKey = settings.toggleKey.Name, triggers = settings.triggers, riddleDefaultsMerged = true }
          for key in pairs(PERSISTED) do out[key] = settings[key] end
          local encoded = ConfigHttp:JSONEncode(out)
          writefile(CONFIG_FILE, encoded)
          -- Keep the old filename readable by older copies of the script.
          writefile(LEGACY_CONFIG_FILE, encoded)
      end)
  end
  local function saveSettings()
      if not writefile or savePending then return end
      savePending = true
      task.delay(1, function()
          savePending = false
          writeConfig()
      end)
  end

