  local hoverBindings = {}
  local function hoverColor(target, rest, hover)
      local binding = { target = target, baseRest = rest, baseHover = hover, rest = rest, hover = hover }
      hoverBindings[#hoverBindings + 1] = binding
      on(target.MouseEnter, function() tween(target, 0.15, { BackgroundColor3 = binding.hover }) end)
      on(target.MouseLeave, function() tween(target, 0.2, { BackgroundColor3 = binding.rest }) end)
  end
