  local snowFlakes = {}
  local snowMotionRunning = false
  local snowMotionThread
  for index = 1, 22 do
      local flake = box({ Name = "Snowflake" .. index,
          Position = UDim2.fromOffset((index * 79) % 860, -((index * 31) % 520)),
          Size = UDim2.fromOffset(2 + (index % 3), 2 + (index % 3)),
          BackgroundColor3 = C.White, BackgroundTransparency = 0.22 + (index % 3) * 0.12,
          Visible = false, ZIndex = 0, Parent = snowLayer }, { corner(5) })
      snowFlakes[#snowFlakes + 1] = {
          object = flake,
          x = (index * 79) % 860,
          y = -((index * 31) % 520),
          speed = 0.35 + (index % 4) * 0.16,
          phase = index * 0.7,
      }
  end
  local function setSnowMotion(enabled)
      snowMotionRunning = enabled == true
      snowLayer.Visible = snowMotionRunning
      if not snowMotionRunning then
          if snowMotionThread then pcall(task.cancel, snowMotionThread); snowMotionThread = nil end
          return
      end
      if snowMotionThread then return end
      snowMotionThread = task.spawn(function()
          while snowMotionRunning and gui.Parent do
              local camera = workspace.CurrentCamera
              local viewport = camera and camera.ViewportSize or Vector2.new(800, 600)
              local width, height = viewport.X, viewport.Y
              local clock = os.clock()
              for _, flake in ipairs(snowFlakes) do
                  flake.y += flake.speed
                  flake.x += math.sin(clock * 0.45 + flake.phase) * 0.16
                  if flake.y > height + 8 then
                      flake.y = -8
                      flake.x = (flake.x + 173) % math.max(width, 320)
                  end
                  flake.object.Position = UDim2.fromOffset(math.floor(flake.x), math.floor(flake.y))
              end
              task.wait(0.08)
          end
          snowMotionThread = nil
      end)
  end

