  local KIND_COLOR = { info = C.Text, sys = C.Sub, good = C.Green, bad = C.Red, code = C.Text, ai = C.Text }
  local entries, order, total = {}, 0, 0
  local logRecords = {}
  local recentLogKeys = {}
  local toast
  local function shouldShowLog(recordKind, message)
      -- The live log is for actions the player can act on. Configuration
      -- chatter and internal measurement noise stays out of the beginner view.
      if recordKind ~= "sys" then return true end
      local lower = tostring(message or ""):lower()
      local hidden = {
          "optimizer:",
          "flag measure",
          "candidate queued behind",
          "final submit queued behind",
          "direct redeem route ready",
          "submit route:",
          "submitting ",
          "announcement feed ready",
          "listening for announcements",
          "code ui cached",
          "code segment detected:",
          " hotkey ",
          "submit after ",
          " set to ",
      }
      for _, fragment in ipairs(hidden) do
          if lower:find(fragment, 1, true) then return false end
      end
      return true
  end
  local function updateCount()
      countText.Text = total == 1 and "1 event" or (total .. " events")
  end

  local function log(message, kind, rich)
      task.defer(function()
          local plain = tostring(message):gsub("<[^>]->", "")
          local recordKind = kind or "info"
          if not shouldShowLog(recordKind, plain) then return end
          local signature = recordKind .. ":" .. plain
          local now = os.clock()
          if recentLogKeys[signature] and now - recentLogKeys[signature] < 0.18 then return end
          recentLogKeys[signature] = now
          local record = { at = os.date("%H:%M:%S"), text = plain, kind = recordKind }
          logRecords[#logRecords + 1] = record
          while #logRecords > 100 do table.remove(logRecords, 1) end
          print("[AZERTOX REDEEMER] [" .. record.at .. "] " .. plain)
          order += 1
          total += 1
          local entry = box({ LayoutOrder = order, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
              BackgroundColor3 = C.Raise, Parent = console })
          entry:SetAttribute("LogText", plain)
          entry:SetAttribute("LogKind", recordKind)
          local stamp = text({ Text = os.date("%H:%M"), FontFace = F.Mono, TextSize = 10, TextColor3 = C.Faint,
              TextTransparency = 1, Size = UDim2.fromOffset(42, 16), Parent = entry })
          local body = text({ Text = rich and message or esc(message), RichText = true, TextWrapped = true,
              FontFace = F.Book, TextSize = 12, TextColor3 = KIND_COLOR[recordKind] or C.Text, TextTransparency = 1,
              TextYAlignment = Enum.TextYAlignment.Top, Position = UDim2.fromOffset(48, 0),
              Size = UDim2.new(1, -48, 0, 16), AutomaticSize = Enum.AutomaticSize.Y, Parent = entry })
          tween(stamp, 0.35, { TextTransparency = 0 })
          tween(body, 0.35, { TextTransparency = 0 })
          entries[#entries + 1] = entry
          if #entries > 28 then
              local oldest = entries[1]
              table.move(entries, 2, #entries, 1)
              entries[#entries] = nil
              oldest:Destroy()
          end
          emptyText.Visible = false
          updateCount()
          if applyConsoleFilter then applyConsoleFilter() end
      end)
  end

  applyConsoleFilter = function()
      local needle = tostring(consoleFilter.Text or ""):lower():match("^%s*(.-)%s*$") or ""
      local visible = 0
      for _, entry in ipairs(entries) do
          local textValue = tostring(entry:GetAttribute("LogText") or ""):lower()
          local kindValue = tostring(entry:GetAttribute("LogKind") or ""):lower()
          entry.Visible = needle == "" or textValue:find(needle, 1, true) ~= nil or kindValue:find(needle, 1, true) ~= nil
          if entry.Visible then visible += 1 end
      end
      emptyText.Text = needle ~= "" and "No matching activity" or "No activity yet"
      emptyText.Visible = visible == 0
  end

  local function logCode(code, prefix, kind)
      local chip = '<font face="RobotoMono">' .. esc(code) .. "</font>"
      log((prefix and (esc(prefix) .. "  ") or "") .. chip, kind or "code", true)
  end

  on(clearBtn.Activated, function()
      for _, e in ipairs(entries) do e:Destroy() end
      entries, logRecords, total = {}, {}, 0
      table.clear(recentLogKeys)
      emptyText.Visible = true
      updateCount()
  end)
  on(copyLogsBtn.Activated, function()
      local lines = {}
      for _, record in ipairs(logRecords) do
          lines[#lines + 1] = string.format("[%s] [%s] %s", record.at, record.kind, record.text)
      end
      local copy = setclipboard or toclipboard or (syn and syn.write_clipboard)
      if type(copy) == "function" and pcall(copy, table.concat(lines, "\n")) then
          toast("Console", "Copied", false, "good")
      else
          toast("Console", "Clipboard unavailable", false, "warn")
      end
  end)


