  UI._bindingCapture = nil
  on(UserInputService.InputBegan, function(input)
      local capture = UI._bindingCapture
      if capture then
          if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
          local adminCapture = tostring(capture):match("^admin:(.+)$")
          if adminCapture then
              local value = input.KeyCode == Enum.KeyCode.Escape and ""
                  or input.KeyCode ~= Enum.KeyCode.Unknown and input.KeyCode.Name or nil
              if value and type(UI._applyAdminKeyBinding) == "function" then
                  UI._applyAdminKeyBinding(adminCapture, value)
              elseif input.KeyCode == Enum.KeyCode.Escape and type(UI._applyAdminKeyBinding) == "function" then
                  UI._applyAdminKeyBinding(adminCapture, "")
              end
              return
          end
          local target = capture == "scanKey" and scanKeyButton or riddleKeyButton
          if input.KeyCode == Enum.KeyCode.Escape then
              settings[capture] = ""
          elseif input.KeyCode ~= Enum.KeyCode.Unknown then
              settings[capture] = input.KeyCode.Name
          end
          if capture == "riddleKey" then settings.idleKey = settings.riddleKey end
          UI._bindingCapture = nil
          if target and target.Parent then
              target.Text = keyLabel(settings[capture])
              target.TextColor3 = C.Sub
          end
          saveSettings()
          log(capture .. " set to " .. (settings[capture] ~= "" and keyName(Enum.KeyCode[settings[capture]]) or "none"), "sys")
          return
      end
      if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
      if settings.scanKey ~= "" and input.KeyCode == Enum.KeyCode[settings.scanKey] then
          if UI._armManualScan then UI._armManualScan() end
      elseif settings.riddleKey ~= "" and input.KeyCode == Enum.KeyCode[settings.riddleKey] then
          if UI._toggleRiddleScan then UI._toggleRiddleScan() end
      end
  end)
