  local function anchorCharacter(state)
      local char = player.Character
      if not char then return end
      for _, part in ipairs(char:GetDescendants()) do
          if part:IsA("BasePart") then
              pcall(function() part.Anchored = state end)
          end
      end
          setAdminStatus(state and "Anchor active · F to disable" or "Anchor disabled", state and C.Gold or C.Faint)
  end
  on(player.CharacterAdded, function(char)
      if not settings.anchor then return end
      char:WaitForChild("HumanoidRootPart", 5)
      task.wait(0.1)
      if settings.anchor then anchorCharacter(true) end
  end)

  local BUY_RANGE, BUY_INTERVAL = 15, 0.10
  local INSTANT_RANGE = 20
  local HOLD_INPUTS = { Enum.UserInputType.Keyboard, Enum.UserInputType.MouseButton1, Enum.UserInputType.Touch }
  local prompts, promptConn, buyThread = {}, nil, nil
  local instantPromptConn
  local promptLastFired = {}
  local promptDefaults = setmetatable({}, { __mode = "k" })

  local function promptPosition(p)
      local parent = p and p.Parent
      if not parent then return nil end
      if parent:IsA("Attachment") then
          local ok, position = pcall(function() return parent.WorldPosition end)
          if ok and position then return position end
      elseif parent:IsA("BasePart") then
          return parent.Position
      elseif parent:IsA("Model") and parent.PrimaryPart then
          return parent.PrimaryPart.Position
      end
      return nil
  end

  local function usablePrompt(p)
      return p and p:IsA("ProximityPrompt") and p.Parent and p.Enabled
  end

  local function rememberPrompt(p)
      if not promptDefaults[p] then
          promptDefaults[p] = { HoldDuration = p.HoldDuration, MaxActivationDistance = p.MaxActivationDistance }
      end
  end

  local function applyInstantPrompt(p, enabled)
      if not (p and p:IsA("ProximityPrompt")) then return end
      if enabled then
          rememberPrompt(p)
          pcall(function()
              p.HoldDuration = 0
              p.MaxActivationDistance = math.max(p.MaxActivationDistance, INSTANT_RANGE)
          end)
      else
          local defaults = promptDefaults[p]
          if defaults then
              pcall(function()
                  p.HoldDuration = defaults.HoldDuration
                  p.MaxActivationDistance = defaults.MaxActivationDistance
              end)
              promptDefaults[p] = nil
          end
      end
  end

  local function releasePrompt(p)
      for _, input in ipairs(HOLD_INPUTS) do
          pcall(function() p:InputHoldEnd(input) end)
      end
  end

  local function activatePrompt(p, maxRange, ignoreCooldown)
      if not usablePrompt(p) then return false end
      local pos = promptPosition(p)
      local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
      if not pos or not root or (root.Position - pos).Magnitude > (maxRange or BUY_RANGE) then return false end
      local now = os.clock()
      if not ignoreCooldown and now - (promptLastFired[p] or 0) < 0.5 then return false end
      promptLastFired[p] = now
      local firePrompt = rawget(env, "fireproximityprompt") or rawget(_G, "fireproximityprompt")
          or (type(fireproximityprompt) == "function" and fireproximityprompt)
      local fired = false
      if type(firePrompt) == "function" then
          local ok = pcall(firePrompt, p)
          fired = ok
      end
      if not fired then
          for _, input in ipairs(HOLD_INPUTS) do pcall(function() p:InputHoldBegin(input) end) end
          task.delay(0.06, function()
              if p and p.Parent then releasePrompt(p) end
          end)
      end
      return true
  end

  local function trackPrompt(p)
      if not p:IsA("ProximityPrompt") then return end
      prompts[p] = true
      if settings.instantBuy then applyInstantPrompt(p, true) end
  end

  local function autobuyTick()
      local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
      if not root then return end
      for p in pairs(prompts) do
          if not usablePrompt(p) then
              prompts[p] = nil
          elseif not activatePrompt(p, BUY_RANGE, false) then
              if not p.Parent then prompts[p] = nil end
          end
      end
  end

  local function stopAutobuy()
      if promptConn then promptConn:Disconnect() promptConn = nil end
      if buyThread then pcall(task.cancel, buyThread) buyThread = nil end
      for p in pairs(prompts) do releasePrompt(p) end
      prompts = {}
      promptLastFired = {}
  end

  local function startAutobuy()
      stopAutobuy()
      for _, obj in ipairs(workspace:GetDescendants()) do trackPrompt(obj) end
      promptConn = workspace.DescendantAdded:Connect(trackPrompt)
      buyThread = task.spawn(function()
          while gui.Parent and settings.autobuy do
              task.wait(BUY_INTERVAL)
              pcall(autobuyTick)
          end
      end)
  end

  local function stopInstantWatch()
      if instantPromptConn then instantPromptConn:Disconnect() instantPromptConn = nil end
      for p, defaults in pairs(promptDefaults) do
          if p and p.Parent and defaults then
              pcall(function()
                  p.HoldDuration = defaults.HoldDuration
                  p.MaxActivationDistance = defaults.MaxActivationDistance
              end)
          end
          promptDefaults[p] = nil
      end
  end

  local function setInstantBuy(state)
      if state then
          for _, obj in ipairs(workspace:GetDescendants()) do
              if obj:IsA("ProximityPrompt") then applyInstantPrompt(obj, true) end
          end
          if not instantPromptConn then
              instantPromptConn = workspace.DescendantAdded:Connect(function(obj)
                  if settings.instantBuy and obj:IsA("ProximityPrompt") then applyInstantPrompt(obj, true) end
              end)
          end
          setAdminStatus("Instant-buy active · prompts at 0 s", C.Green)
      else
          stopInstantWatch()
          setAdminStatus("Instant-buy disabled", C.Faint)
      end
  end

  local function adminRow(index, label, description, icon, key, apply, hotkey)
      local r = button({
          Name = label,
          Position = UDim2.fromOffset(PX, ADMIN_TOP + (index - 1) * (ADMIN_ROW_H + 8)),
          Size = UDim2.fromOffset(CW - PX * 2, ADMIN_ROW_H),
          BackgroundColor3 = C.Panel,
          Parent = adminPage,
      }, { corner(5), stroke(C.Line) })
      hoverColor(r, C.Panel, C.Hover)
      local iconFrames = pixelArt(r, icon, 2, { ["#"] = C.Faint }, Vector2.new(14, (ADMIN_ROW_H - 14) / 2), 2)
      text({ Text = label, FontFace = F.Bold, TextSize = 13, Position = UDim2.fromOffset(42, 5),
          Size = UDim2.new(1, -164, 0, 22), Parent = r })
      text({ Text = description, FontFace = F.Book, TextSize = 10, TextColor3 = C.Faint,
          Position = UDim2.fromOffset(42, 28), Size = UDim2.new(1, -164, 0, 16), Parent = r })
      if hotkey or settings.adminKeys[key] ~= nil then
          local badge = button({ Text = adminKeyText(key), FontFace = F.Mono, TextSize = 10, TextColor3 = C.Gold,
              TextXAlignment = Enum.TextXAlignment.Center, Position = UDim2.new(1, -112, 0, 18), Size = UDim2.fromOffset(42, 20),
              BackgroundColor3 = C.Raise, Parent = r }, { corner(5) })
          hoverColor(badge, C.Raise, C.Edge)
          adminKeyButtons[key] = badge
          on(badge.Activated, function()
              UI._bindingCapture = "admin:" .. key
              badge.Text = "press"
              badge.TextColor3 = C.Cyan
              toast("Admin key", "Press a keyboard key or Escape to clear", false, "sys")
          end)
      end
      adminSetters[key] = switch(r, UDim2.new(1, -14 - SW_W, 0, (ADMIN_ROW_H - CTRL_H) / 2), settings[key], function(v)
          changed(key, v)
          log(label .. " " .. onOff(v), "sys")
          apply(v)
      end, r, function(state, animate)
          paint(iconFrames, state and C.Text or C.Faint, animate and 0.3 or 0)
      end)
  end

  UI._applyAdminKeyBinding = function(action, keyValue)
      if not settings.adminKeys[action] then return end
      if keyValue ~= "" and not Enum.KeyCode[keyValue] then return end
      settings.adminKeys[action] = keyValue
      if keyValue == "" then
          ADMIN_KEYS[action] = nil
      else
          ADMIN_KEYS[action] = Enum.KeyCode[keyValue]
      end
      local badge = adminKeyButtons[action]
      if badge and badge.Parent then
          badge.Text = adminKeyText(action)
          badge.TextColor3 = C.Gold
      end
      UI._bindingCapture = nil
      saveSettings()
      refreshAdminStatus()
      log("Admin key " .. action .. " set to " .. (keyValue ~= "" and keyValue or "none"), "sys")
  end

  cleanups[#cleanups + 1] = function()
      stopAutobuy()
      stopInstantWatch()
      if settings.anchor then anchorCharacter(false) end
  end

