        apiStatus.Text = value and "DB first · AI only if not found." or "AI off · DB only."
        apiStatus.TextColor3 = value and C.Green or C.Faint
    end
    local setRiddleSolverVisual = switch(apiCard, UDim2.new(1, -54, 0, 34), settings.riddleSolver, setRiddleSolver, apiToggleHit)
    local function toggleRiddleSolver()
        local value = not settings.riddleSolver
        setRiddleSolver(value)
        setRiddleSolverVisual(value)
    end
    on(apiToggleHit.Activated, toggleRiddleSolver)
    local apiSwitchHit = button({ Name = "RiddleSolverSwitchHit",
        Position = UDim2.new(1, -64, 0, 28), Size = UDim2.fromOffset(60, 36), Parent = apiCard })
    on(apiSwitchHit.Activated, toggleRiddleSolver)
    local API_MASK = string.rep("•", 16)
    local apiKeyBox = new("TextBox", { Name = "RiddleApiKey", Position = UDim2.fromOffset(14, 64),
        Size = UDim2.new(1, -28, 0, 30), BackgroundColor3 = C.Raise, BorderSizePixel = 0,
        ClearTextOnFocus = false, Text = "", PlaceholderText = "Gemini API key (hidden)",
        PlaceholderColor3 = C.Faint, TextColor3 = C.Text, FontFace = F.Mono, TextSize = 10,
        Parent = apiCard }, { corner(6), stroke(C.Line), pad(0, 9, 0, 9) })
    apiStatus = text({ Text = settings.riddleSolver and "DB first · AI only if not found." or "AI off · DB only.",
        FontFace = F.Book, TextSize = 10, TextWrapped = true, TextColor3 = settings.riddleSolver and C.Green or C.Faint,
        Position = UDim2.fromOffset(14, 103), Size = UDim2.new(1, -28, 0, 18), Parent = apiCard })
    local dbText = text({ Text = "Loading local answers...", FontFace = F.Mono, TextSize = 9, TextColor3 = C.Cyan,
        Position = UDim2.fromOffset(14, 128), Size = UDim2.new(1, -28, 0, 12), Parent = apiCard })
    local function renderApiKeyMask()
        local savedKey = tostring(settings.riddleApiKey or ""):match("^%s*(.-)%s*$") or ""
        local hasKey = savedKey ~= ""
        apiKeyBox.Text = hasKey and API_MASK or ""
        apiKeyBox.PlaceholderText = hasKey and "Saved locally · paste a new key to replace it" or "Gemini API key (hidden)"
    end
    local function saveRiddleApi()
        local entered = (tostring(apiKeyBox.Text or ""):match("^%s*(.-)%s*$") or "")
        if entered ~= "" and entered ~= API_MASK then
            settings.riddleApiKey = entered:sub(1, 256)
        end
        renderApiKeyMask()
        settings.riddleApiUrl = "https://generativelanguage.googleapis.com/v1beta/models"
        settings.riddleApiModel = "gemini-3.8-flash"
        pcall(writeConfig)
        saveSettings()
        apiStatus.Text = settings.riddleSolver and "Key saved locally · DB remains first." or "Key saved locally · solver is off."
        apiStatus.TextColor3 = C.Sub
    end
    on(apiKeyBox.Focused, function()
        apiKeyBox.Text = ""
        apiKeyBox.PlaceholderText = "Paste a new Gemini key · hidden"
    end)
    on(apiKeyBox.FocusLost, saveRiddleApi)
    renderApiKeyMask()

    local manualCard = box({ Position = UDim2.fromOffset(0, 166), Size = UDim2.new(1, 0, 0, 154),
        BackgroundColor3 = C.Panel, Parent = scroll }, { corner(10), stroke(C.Line) })
    text({ Text = "TEST A RIDDLE", FontFace = F.Bold, TextSize = 12, TextColor3 = C.Text,
        Position = UDim2.fromOffset(14, 10), Size = UDim2.fromOffset(160, 16), Parent = manualCard })
    local manualBox = new("TextBox", { Name = "ManualRiddle", Position = UDim2.fromOffset(14, 34),
        Size = UDim2.new(1, -28, 0, 30), BackgroundColor3 = C.Raise, BorderSizePixel = 0,
        ClearTextOnFocus = false, Text = "", PlaceholderText = "Paste or type a riddle...",
        PlaceholderColor3 = C.Faint, TextColor3 = C.Text, FontFace = F.Medium, TextSize = 11,
        Parent = manualCard }, { corner(6), stroke(C.Line), pad(0, 9, 0, 9) })
    local localAnswerButton = button({ Text = "Solve locally", FontFace = F.Bold, TextSize = 10,
        TextColor3 = C.Text, Position = UDim2.fromOffset(14, 72), Size = UDim2.new(0.5, -20, 0, 30),
        BackgroundColor3 = C.Raise, Parent = manualCard }, { corner(7) })
    local geminiAnswerButton = button({ Text = "Solve with AI", FontFace = F.Bold, TextSize = 10,
        TextColor3 = C.Bg, Position = UDim2.new(0.5, 6, 0, 72), Size = UDim2.new(0.5, -20, 0, 30),
        BackgroundColor3 = C.Cyan, Parent = manualCard }, { corner(7) })
    hoverColor(localAnswerButton, C.Raise, C.Hover)
    hoverColor(geminiAnswerButton, C.Cyan, C.Edge)
    local resultFrame = box({ Position = UDim2.fromOffset(14, 112), Size = UDim2.new(1, -28, 0, 30),
        BackgroundColor3 = C.Raise, Parent = manualCard }, { corner(6), stroke(C.Line) })
    local manualResult = text({ Text = "Type a riddle above, then choose Local or AI.", FontFace = F.Mono,
        TextSize = 9, TextWrapped = true, TextColor3 = C.Faint,
        Position = UDim2.fromOffset(9, 0), Size = UDim2.new(1, -18, 1, 0), Parent = resultFrame })
    local manualSolveToken = 0
    local function manualQuestion()
        return tostring(manualBox.Text or ""):match("^%s*(.-)%s*$") or ""
    end
    local function submitManualAnswer(answer, source, preserveComposite)
        if not preserveComposite and type(UI._riddleNormalize) == "function" then
            answer = UI._riddleNormalize(answer, manualQuestion())
        end
        if type(answer) ~= "string" or answer == "" then
            manualResult.Text, manualResult.TextColor3 = "No answer found.", C.Red
            return false
        end
        local ok, message = UI._riddleRedeem(answer)
        if ok then
            manualResult.Text, manualResult.TextColor3 = tostring(source) .. " · " .. answer, C.Green
        else
            manualResult.Text, manualResult.TextColor3 = tostring(message or "Submit failed"), C.Red
        end
        return ok
    end
    on(localAnswerButton.Activated, function()
        local raw = manualQuestion()
        if raw == "" then manualResult.Text, manualResult.TextColor3 = "Enter a riddle first.", C.Gold; return end
        manualSolveToken += 1
        if type(UI._riddleResolve) ~= "function" or type(UI._riddleRedeem) ~= "function" then
            manualResult.Text, manualResult.TextColor3 = "Riddle engine is still loading.", C.Red
            return
        end
        local answer, key, attempts, isComposite = UI._riddleResolve(raw)
        if answer then
            submitManualAnswer(answer, "Local", isComposite)
        else
            manualResult.Text, manualResult.TextColor3 = "Unknown riddle · " .. tostring(key) .. " (" .. tostring(attempts) .. ")", C.Red
        end
    end)
    on(geminiAnswerButton.Activated, function()
        local raw = manualQuestion()
        if raw == "" then manualResult.Text, manualResult.TextColor3 = "Enter a riddle first.", C.Gold; return end
        if type(UI._riddleApiSolve) ~= "function" or type(UI._riddleRedeem) ~= "function" then
            manualResult.Text, manualResult.TextColor3 = "Riddle engine is still loading.", C.Red
            return
        end
        saveRiddleApi()
        manualSolveToken += 1
        local token = manualSolveToken
        local preserveComposite = type(UI._riddleIsComposite) == "function" and UI._riddleIsComposite(raw) or false
        manualResult.Text, manualResult.TextColor3 = "Gemini is thinking...", C.Cyan
        task.spawn(function()
            local answer, message = UI._riddleApiSolve(raw, true)
            if token ~= manualSolveToken then return end
            if answer then
                submitManualAnswer(answer, "Gemini", preserveComposite)
            else
                manualResult.Text, manualResult.TextColor3 = tostring(message or "Gemini did not answer"), C.Red
            end
        end)
    end)

    local function refreshRiddleStatus()
        local total = 0
        if type(UI._riddleStats) == "function" then total = UI._riddleStats() end
        dbText.Text = string.format("%d local answers · Gemini optional", total)
    end
    UI._riddlePageRefresh = refreshRiddleStatus
    refreshRiddleStatus()
end

  local optimizer = {}
  do

  local function runOptimizer()
      if _G.Rose20MLoaderStop then _G.Rose20MLoaderStop() end

      local Workspace = game:GetService("Workspace")
      local Players = game:GetService("Players")
      local LocalPlayer = Players.LocalPlayer or Players.PlayerAdded:Wait()
      local RunService = game:GetService("RunService")
      local ReplicatedStorage = game:GetService("ReplicatedStorage")
      local Lighting = game:GetService("Lighting")
      local SoundService = game:GetService("SoundService")
      local CollectionService = game:GetService("CollectionService")
      local THRESHOLD = 20_000_000
      local SCAN_TIMEOUT = 90

      local running, connections = true, {}
      local retained = {}
      local floorNames = {
          Ground = true, Ground_Left = true, Ground_Right = true,
          Carpet = true, Floor = true, Baseplate = true,
      }
      local gameplayRoots = {
          Interacts = true, ToolsAdds = true, __PROJECTILES = true,
          Events = true, Debris = true,
      }
      local function isBrainrotVisual(object)
          return CollectionService:HasTag(object, "ClientRenderBrainrot")
              or CollectionService:HasTag(object, "RenderedMovingAnimal")
              or CollectionService:HasTag(object, "Animal")
      end
      local function delete(object)
          if not (object and object.Parent) then return end
          if isBrainrotVisual(object) then return end
          if object:IsA("Sound") then
              pcall(function() object.Parent = SoundService end)
              return
          end
          for _, descendant in ipairs(object:GetDescendants()) do
              if isBrainrotVisual(descendant) and not object:IsDescendantOf(Workspace:FindFirstChild("Plots") or object) then
                  pcall(function() descendant.Parent = Workspace end)
              elseif descendant:IsA("Sound") then
                  pcall(function() descendant.Parent = SoundService end)
              end
          end
          pcall(function() object:Destroy() end)
      end
      local function cleanMapChild(child)
          if floorNames[child.Name] or gameplayRoots[child.Name]
              or child.Name == "RenderedMovingAnimals"
              or child:IsA("Sound") or isBrainrotVisual(child) then return end
          if child:IsA("Model") and
              (child.Name:match("_Clone$") or child:FindFirstChildOfClass("Humanoid")) then return end
          delete(child)
      end
      local function smoothVisiblePart(object)
          if not object:IsA("BasePart") then return end
          pcall(function()
              object.TopSurface = Enum.SurfaceType.Smooth
              object.BottomSurface = Enum.SurfaceType.Smooth
              object.LeftSurface = Enum.SurfaceType.Smooth
              object.RightSurface = Enum.SurfaceType.Smooth
              object.FrontSurface = Enum.SurfaceType.Smooth
              object.BackSurface = Enum.SurfaceType.Smooth
              object.Material = Enum.Material.SmoothPlastic
              object.MaterialVariant = ""
          end)
      end
      local function smoothFloorQuick(root)
          smoothVisiblePart(root)
          for _, object in ipairs(root:GetDescendants()) do smoothVisiblePart(object) end
      end
      local watchedMaps = setmetatable({}, {__mode = "k"})
      local function watchMap(map)
          if watchedMaps[map] then return end
          watchedMaps[map] = true
          for _, child in ipairs(map:GetChildren()) do
              if floorNames[child.Name] then task.defer(smoothFloorQuick, child)
              else cleanMapChild(child) end
          end
          connections[#connections + 1] = map.ChildAdded:Connect(function(child)
              if running then
                  if floorNames[child.Name] then task.defer(smoothFloorQuick, child)
                  else cleanMapChild(child) end
              end
          end)
      end
      local function keepRoot(object)
          if object.Name == "Plots" or object.Name == "Map" or gameplayRoots[object.Name]
              or object:IsA("Camera")
              or object.Name == "RenderedMovingAnimals"
              or object:IsA("Terrain") or object:IsA("Sound")
              or isBrainrotVisual(object)
              or floorNames[object.Name] then return true end
          for _, p in ipairs(Players:GetPlayers()) do
              if p.Character == object then return true end
          end
          if object:IsA("Model") and
              (object.Name:match("_Clone$") or object:FindFirstChildOfClass("Humanoid")) then
              return true
          end
          return false
      end
      for _, object in ipairs(Workspace:GetChildren()) do
          if object.Name == "Map" then watchMap(object)
          elseif floorNames[object.Name] then task.defer(smoothFloorQuick, object)
          elseif not keepRoot(object) then delete(object) end
      end
      connections[#connections + 1] = Workspace.ChildAdded:Connect(function(object)
          if not running then return end
          task.defer(function()
              if not running or not object.Parent then return end
              if object.Name == "Map" then watchMap(object)
              elseif floorNames[object.Name] then task.defer(smoothFloorQuick, object)
              elseif not keepRoot(object) then delete(object) end
          end)
      end)
      local plots = Workspace:WaitForChild("Plots", 90)
      if not plots then return end
      task.defer(function()
          for _, plot in ipairs(plots:GetChildren()) do
              local podiums = plot:FindFirstChild("AnimalPodiums")
              for i, part in ipairs(plot:GetDescendants()) do
                  if not (podiums and part:IsDescendantOf(podiums)) then
                      smoothVisiblePart(part)
                  end
                  if i % 400 == 0 then task.wait() end
              end
          end
      end)
      local datas = ReplicatedStorage:WaitForChild("Datas", 90)
      if not datas then return end
      local okAnimals, animalsData = pcall(require, datas:WaitForChild("Animals", 90))
      local okMutations, mutations = pcall(require, datas:WaitForChild("Mutations", 90))
      local okTraits, traitsData = pcall(require, datas:WaitForChild("Traits", 90))
      local okGame, gameData = pcall(require, datas:WaitForChild("Game", 90))
      if not (okAnimals and type(animalsData) == "table" and okMutations and okTraits and okGame) then
          return
      end
      local function generation(index, mutation, traits)
          local animal = animalsData[index]
          if not animal then return nil end
          local base = animal.Generation
          if not base then
              local modifier = gameData.Game and gameData.Game.AnimalGanerationModifier
              if type(modifier) ~= "number" then return nil end
              base = (animal.Price or 0) * modifier
          end
          local mult = 1
          local mutationData = mutation and mutations[mutation]
          if mutationData then mult = mult + (mutationData.Modifier or 0) end
          local sleepy = false
          for _, trait in pairs(traits or {}) do
              if trait == "Sleepy" then sleepy = true
              else
                  local traitData = traitsData[trait]
                  if traitData then mult = mult + (traitData.MultiplierModifier or 0) end
              end
          end
          local result = base * mult
          if sleepy then result = result * 0.5 end
          return math.round(result)
      end
      local packages = ReplicatedStorage:WaitForChild("Packages", 90)
      local syncFolder = packages and packages:WaitForChild("Synchronizer", 90)
      local requestData = syncFolder and syncFolder:WaitForChild("RequestData", 90)
      if not (requestData and requestData:IsA("RemoteFunction")) then
          return
      end
      local function findMyPlot()
          for _, plot in ipairs(plots:GetChildren()) do
              local sign = plot:FindFirstChild("PlotSign")
              if sign then
                  local marker = sign:FindFirstChild("YourBase")
                  if marker and marker:IsA("BillboardGui") and marker.Enabled then
                      return plot
                  end
              end
          end
          return nil
      end
      _G.Rose20MLoaderStop = function()
          running = false
          for _, connection in ipairs(connections) do connection:Disconnect() end
      end
      local function readPlot(plot)
          local instanceCache
          if type(_G.JAF_InstanceChans) == "function" then
              local ok, channels = pcall(_G.JAF_InstanceChans)
              local channel = ok and type(channels) == "table" and channels[plot.Name]
              if channel then instanceCache = rawget(channel, "CacheTable") end
          end
          local ok, result = pcall(function() return requestData:InvokeServer(plot.Name) end)
          local cache = ok and type(result) == "table" and result or instanceCache
          if type(cache) ~= "table" then return nil end
          local animals = cache.AnimalList or cache.Animals
          if type(animals) ~= "table" then
              if cache.Owner == nil and next(cache) ~= nil then animals = {} else return nil end
          end
          local keepSlots = {}
          local function checkAnimals(list)
              if type(list) ~= "table" then return true end
              for slot, animal in pairs(list) do
                  if type(animal) == "table" and animal.Index then
                      local amount = generation(animal.Index, animal.Mutation, animal.Traits)
                      if type(amount) ~= "number" then return false end
                      if amount > THRESHOLD then keepSlots[tostring(slot)] = true end
                  end
              end
              return true
          end
          if not checkAnimals(animals) or not checkAnimals(type(instanceCache) == "table"
              and (instanceCache.AnimalList or instanceCache.Animals)) then return nil end
          return keepSlots, cache.Owner or (instanceCache and instanceCache.Owner)
      end
      local deadline = os.clock() + SCAN_TIMEOUT
      local snapshot, previousSignature, myPlotName = nil, nil, nil
      repeat
          local current, complete = {}, true
          myPlotName = (findMyPlot() or {}).Name
          local list = plots:GetChildren()
          if #list == 0 then complete = false end
          local remaining = #list
          for _, plot in ipairs(list) do
              task.spawn(function()
                  local slots, owner = readPlot(plot)
                  if not slots then
                      complete = false
                  else
                      current[plot.Name] = slots
                      if not myPlotName and owner ~= nil then
                          if owner == LocalPlayer or owner == LocalPlayer.Name
                              or owner == LocalPlayer.UserId
                              or type(owner) == "table" and
                                  (owner.UserId == LocalPlayer.UserId or owner.Name == LocalPlayer.Name) then
                              myPlotName = plot.Name
                          end
                      end
                  end
                  remaining -= 1
              end)
          end
          while remaining > 0 and running and os.clock() < deadline do task.wait(0.03) end
          if remaining > 0 then complete = false end
          if complete and myPlotName then
              local signatureParts = {}
              for plotName, slots in pairs(current) do
                  local names = {}
                  for slot in pairs(slots) do names[#names + 1] = slot end
                  table.sort(names)
                  signatureParts[#signatureParts + 1] = plotName .. ":" .. table.concat(names, ",")
              end
              table.sort(signatureParts)
              local signature = table.concat(signatureParts, "|")
              if signature == previousSignature then
                  snapshot = current; break
              end
              previousSignature = signature
          else
              previousSignature = nil
          end
          if previousSignature then task.wait(0.06) else task.wait(0.2) end
      until not running or os.clock() > deadline
      if not snapshot or not running then
          return
      end
      retained = snapshot
      log("Optimizer: scan complete, cleaning plots", "sys")
      local keptCount, removedCount = 0, 0
      for _, plot in ipairs(plots:GetChildren()) do
          if not running then return end
          if plot.Name == myPlotName or next(retained[plot.Name] or {}) then
              keptCount += 1
          else
              delete(plot)
              removedCount += 1
          end
      end
      local function smooth(object)
          if object:IsA("BasePart") then
              smoothVisiblePart(object)
              pcall(function()
                  if object:IsA("MeshPart") then object.TextureID = "" end
              end)
          elseif object:IsA("Decal") or object:IsA("Texture") or object:IsA("SurfaceAppearance") then
              delete(object)
          elseif object:IsA("SpecialMesh") then
              pcall(function() object.TextureId = "" end)
          end
      end
      local function smoothTree(root, plot)
          if not root then return end
          local podiums = plot and plot:FindFirstChild("AnimalPodiums")
          smooth(root)
          for i, object in ipairs(root:GetDescendants()) do
              local visual = object
              local protectedVisual = false
              while visual and visual ~= plot and visual ~= root do
                  if isBrainrotVisual(visual) then protectedVisual = true; break end
                  visual = visual.Parent
              end
              if not protectedVisual and not (podiums and object:IsDescendantOf(podiums)) then
                  smooth(object)
              end
              if i % 350 == 0 then RunService.Heartbeat:Wait() end
          end
      end
      local map = Workspace:FindFirstChild("Map")
      if map then
          for _, child in ipairs(map:GetChildren()) do
              if floorNames[child.Name] then smoothTree(child) end
          end
      end
      for _, child in ipairs(Workspace:GetChildren()) do
          if floorNames[child.Name] then smoothTree(child) end
      end
      for _, plot in ipairs(plots:GetChildren()) do smoothTree(plot, plot) end
      connections[#connections + 1] = Workspace.DescendantAdded:Connect(function(object)
          if not running then return end
          local plotAncestor = object
          while plotAncestor and plotAncestor.Parent ~= plots do
              plotAncestor = plotAncestor.Parent
          end
          local isPlotBase = plotAncestor and plotAncestor.Parent == plots
              and not object:FindFirstAncestor("AnimalPodiums")
          local insideFloor = false
          local ancestor = object
          while ancestor and ancestor ~= Workspace do
              if floorNames[ancestor.Name] then insideFloor = true; break end
              ancestor = ancestor.Parent
          end
          if isPlotBase or insideFloor then smooth(object) end
      end)
      for _, effect in ipairs(Lighting:GetChildren()) do
          if effect:IsA("PostEffect") or effect:IsA("Atmosphere") or effect:IsA("Sky")
              or effect:IsA("Clouds") then delete(effect) end
      end
      pcall(function()
          Lighting.GlobalShadows = false
          Lighting.FogEnd = 1e9
          Lighting.EnvironmentDiffuseScale = 0
          Lighting.EnvironmentSpecularScale = 0
          robloxSettings().Rendering.QualityLevel = Enum.QualityLevel.Level01
      end)
      log(("Optimizer: done · kept %d plots, removed %d"):format(keptCount, removedCount), "sys")
  end

  function optimizer.freeze() end
  function optimizer.unfreeze() end

  function optimizer.start()
      task.spawn(runOptimizer)
  end

  function optimizer.stop()
      if _G.Rose20MLoaderStop then pcall(_G.Rose20MLoaderStop) end
      _G.Rose20MLoaderStop = nil
  end
  end

  adminRow(1, "Anchor", "Freeze your character in place", ICONS.anchor, "anchor", anchorCharacter, ADMIN_KEYS.anchor)
  adminRow(2, "Instant buy", "Set nearby prompts to zero hold time", ICONS.bolt, "instantBuy", setInstantBuy, ADMIN_KEYS.instantBuy)
  adminRow(3, "Autobuy", "Trigger nearby prompts with a per-prompt cooldown", ICONS.cart, "autobuy", function(v)
      if v then startAutobuy() else stopAutobuy() end
  end, ADMIN_KEYS.autobuy)
  adminRow(4, "Optimizer", "Reduce client-side scene cost", ICONS.optimizer, "optimizer", function(v)
      if v then optimizer.start() else optimizer.stop() end
  end, ADMIN_KEYS.optimizer)
  if settings.anchor then anchorCharacter(true) end
  if settings.instantBuy then setInstantBuy(true) end
  if settings.autobuy then startAutobuy() end
  if settings.optimizer then optimizer.start() end

  do
  local antiRagdollConn, ragdollCooldown = nil, 0
  local function forceGetUp()
      local char = player.Character
      if not char then return end
      local hum = char:FindFirstChildOfClass("Humanoid")
      local root = char:FindFirstChild("HumanoidRootPart")
      if not hum or not root or hum.Health <= 0 then return end
      pcall(function()
          hum:ChangeState(Enum.HumanoidStateType.GettingUp)
          root.AssemblyLinearVelocity = Vector3.zero
          root.AssemblyAngularVelocity = Vector3.zero
          for _, obj in ipairs(char:GetDescendants()) do
              if obj:IsA("Motor6D") or obj:IsA("Constraint") then obj.Enabled = true end
          end
          workspace.CurrentCamera.CameraSubject = hum
          local pm = player.PlayerScripts:FindFirstChild("PlayerModule")
          local cm = pm and pm:FindFirstChild("ControlModule")
          if cm then require(cm):Enable() end
          hum.AutoRotate = true
          hum.PlatformStand = false
          hum.Sit = false
      end)
  end
  local function setAntiRagdoll(v)
      pcall(function()
          local hum = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
          if hum then
              hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, not v)
              hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, not v)
          end
      end)
      if v and not antiRagdollConn then
          antiRagdollConn = on(RunService.Heartbeat, function()
              local hum = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
              if not hum or hum.Health <= 0 then return end
              local st = hum:GetState()
              if st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.Ragdoll or st == Enum.HumanoidStateType.FallingDown then
                  if os.clock() - ragdollCooldown > 0.15 then
                      ragdollCooldown = os.clock()
                      forceGetUp()
                  end
              end
          end)
      elseif not v and antiRagdollConn then
          antiRagdollConn:Disconnect()
          antiRagdollConn = nil
      end
  end
  adminRow(5, "Anti ragdoll", "Recover from ragdoll and falling states", ICONS.anchor, "antiRagdoll", setAntiRagdoll, ADMIN_KEYS.antiRagdoll)
  if settings.antiRagdoll then setAntiRagdoll(true) end
  on(player.CharacterAdded, function()
      if settings.antiRagdoll then task.wait(0.5) setAntiRagdoll(true) end
  end)
  on(UserInputService.InputBegan, function(input, processed)
      if processed or UI._bindingCapture or input.UserInputType ~= Enum.UserInputType.Keyboard then return end
      for key, hotkey in pairs(ADMIN_KEYS) do
          if input.KeyCode == hotkey and adminSetters[key] then
              adminSetters[key](not settings[key])
              log(key .. " hotkey " .. onOff(settings[key]), "sys")
              return
          end
      end
  end)
  -- ============================================================
  -- AZERTOX REDEEMER 4.0 — changelog
  -- Riddle keeps the local string-only RIDDLER_DB from riddler_v29.txt with manual
  -- overrides and an optional API-first resolver. Fixed probe cleanup, single-shot submit, UI caching,
  -- notifier restoration, optimizer settings lookup, trigger matching, grid overlap,
  -- and per-prompt autobuy debounce. Added manual Scan/Send, flag health, stats bar,
  -- independent code history, session export, CMDR diagnostics, profiles, themes,
  -- panic/cancel hotkeys, anti-AFK, reconnect handling, and unload-safe loops.
  -- ============================================================
  do
      local core = {}
      UI._installStatsHealth = function()
      local Stats = cloneref(game:GetService("Stats"))
      local TeleportService = cloneref(game:GetService("TeleportService"))
      local TextService = cloneref(game:GetService("TextService"))
      local sessionStarted = os.clock()
      local statsRunning, statsLoop, statsRenderConn = false, nil, nil
      local fpsFrames, fpsSince, fpsEma = 0, os.clock(), 0
      local redeemCount = 0
      local session = { seen = 0, good = 0, bad = 0, timeout = 0, manual = 0, trigger = 0 }
      local history = {}
      local flag = {
          attempts = 0, warmup = 2, samples = {}, invalid = 0, timeouts = 0,
          verdict = "WARMING UP", suspendUntil = 0, nextAllowed = 0,
      }
      local panicActive, panicWasShown = false, true
      local spawnCount, spawnWindow = 0, 0
      local profileStore = {}
      local profileFile = "azertox_profiles.json"
      local refreshHealth
      core.panicActive, core.panicWasShown = false, true

      local function safeCall(fn, ...)
          if type(fn) ~= "function" then return false end
          return pcall(fn, ...)
      end
      local function hex(color)
          local ok, value = pcall(function() return color:ToHex() end)
          return ok and value or "FFFFFF"
      end
      local function nowMs()
          local ok, value = pcall(function() return DateTime.now().UnixTimestampMillis end)
          return ok and value or math.floor(os.clock() * 1000)
      end
      local function currentBackoff()
          if flag.verdict == "FLAG" then
              if flag.suspendUntil > os.clock() then
                  return "SUSPEND " .. math.ceil(flag.suspendUntil - os.clock()) .. "s"
              end
              return "1 / 10s"
          end
          if flag.verdict == "MID FLAG" then return "THROTTLE 400ms" end
          return "NORMAL"
      end
      local function healthAverage()
          local total = 0
          for _, value in ipairs(flag.samples) do total += value end
          return #flag.samples > 0 and total / #flag.samples or 0
      end
      local function healthVerdict()
          if not settings.flagCheck or #flag.samples < 3 then return "WARMING UP" end
          local average = healthAverage()
          if average < 1000 then return "CLEAN" end
          if average <= 1500 then return "MID FLAG" end
          return "FLAG"
      end
      local function verdictColor(value)
          if value == "CLEAN" then return C.Green end
          if value == "MID FLAG" then return C.Gold or C.Sub end
          if value == "FLAG" then return C.Red end
          return C.Faint
      end

      local statsGlow = stroke(C.Edge)
      local statsBar = box({
          Name = "ModernUtilityBar", AnchorPoint = Vector2.new(0.5, 0),
          Position = UDim2.new(0.5, 0, 0, -48), Size = UDim2.fromOffset(410, 40),
          BackgroundColor3 = C.Panel, BackgroundTransparency = 0.04, ZIndex = 100,
          Parent = gui,
      }, { corner(12), statsGlow, new("UIGradient", {
          Rotation = 90, Color = ColorSequence.new(C.Panel, C.Raise), Transparency = NumberSequence.new(0.04),
      }) })
      local statsLogo = pixelArt(statsBar, ICONS.sniper, 2, { ["#"] = C.Cyan }, Vector2.new(12, 9), 102)
      text({ Text = "AZERTOX SNIPER", FontFace = F.Bold, TextSize = 11, TextColor3 = C.Text,
          Position = UDim2.fromOffset(36, 0), Size = UDim2.fromOffset(122, 39),
          TextYAlignment = Enum.TextYAlignment.Center, ZIndex = 102, Parent = statsBar })
      box({ Position = UDim2.fromOffset(166, 16), Size = UDim2.fromOffset(8, 8),
          BackgroundColor3 = C.Green, ZIndex = 102, Parent = statsBar }, { corner(4) })
      text({ Text = "LIVE", FontFace = F.Bold, TextSize = 10, TextColor3 = C.Faint,
          Position = UDim2.fromOffset(180, 0), Size = UDim2.fromOffset(36, 39),
          TextYAlignment = Enum.TextYAlignment.Center, ZIndex = 102, Parent = statsBar })
      local statsDivider = box({ Position = UDim2.fromOffset(14, 36), Size = UDim2.new(1, -28, 0, 1),
          BackgroundColor3 = C.Cyan, BackgroundTransparency = 0.25, ZIndex = 101, Parent = statsBar })
      local statsText = text({
          Name = "StatsText", Size = UDim2.new(1, -226, 1, -4), Position = UDim2.fromOffset(220, 0),
          FontFace = F.Mono, TextSize = 13, TextColor3 = C.Sub, RichText = true, ZIndex = 102,
          TextXAlignment = Enum.TextXAlignment.Right, Parent = statsBar,
      })
      local function fitStatsBar()
          local camera = workspace.CurrentCamera
          local width = camera and math.clamp(camera.ViewportSize.X - 24, 320, 410) or 410
          statsBar.Size = UDim2.fromOffset(width, 40)
      end
      fitStatsBar()
      on(workspace:GetPropertyChangedSignal("CurrentCamera"), fitStatsBar)

      local function updateStatsText()
          local fps, ping = "--", "--"
          local pingNumber = 999
          pcall(function() fps = tostring(math.max(0, math.floor(fpsEma + 0.5))) end)
          pcall(function()
              pingNumber = tonumber(Stats.Network.ServerStatsItem["Data Ping"]:GetValue()) or 999
              ping = tostring(math.floor(pingNumber + 0.5))
          end)
          statsText.Text = string.format(
               '<font color="#%s">FPS %s</font>  ·  <font color="#%s">PING %s</font>',
              hex(fpsEma > 50 and C.Green or fpsEma >= 30 and C.Sub or C.Red), fps,
               hex(pingNumber < 80 and C.Green or pingNumber <= 150 and C.Sub or C.Red), ping
          )
      end
      local function playSuccessSound()
          pcall(function()
              local soundService = game:GetService("SoundService")
              local sound = Instance.new("Sound")
              sound.Name = "AzertoxSuccess"
              sound.SoundId = "rbxasset://sounds/electronicpingshort.wav"
              sound.Volume = math.clamp(tonumber(settings.successVolume) or 0.45, 0, 1)
              sound.PlaybackSpeed = 1.05
              sound.Parent = soundService
              pcall(function() soundService:PlayLocalSound(sound) end)
              pcall(function() sound:Play() end)
              task.delay(2, function() if sound.Parent then sound:Destroy() end end)
          end)
      end
      local function stopStats()
          settings.statsBar = false
          statsRunning = false
          if statsLoop then pcall(task.cancel, statsLoop) statsLoop = nil end
          if statsRenderConn then statsRenderConn:Disconnect() statsRenderConn = nil end
          statsBar.Visible = false
          statsBar.Position = UDim2.new(0.5, 0, 0, -48)
      end
      local function startStats()
          if statsRunning or not settings.statsBar then return end
          statsRunning = true
          statsBar.Visible = true
          statsBar.Position = UDim2.new(0.5, 0, 0, -48)
          statsGlow.Transparency = 0.15
          tween(statsBar, 0.45, { Position = UDim2.new(0.5, 0, 0, 4) }, Enum.EasingStyle.Quint)
          tween(statsGlow, 0.65, { Transparency = 0.58 }, Enum.EasingStyle.Quint)
          fpsFrames, fpsSince = 0, os.clock()
          statsRenderConn = RunService.RenderStepped:Connect(function()
              fpsFrames += 1
              local current = os.clock()
              if current - fpsSince >= 1 then
                  local instant = fpsFrames / math.max(current - fpsSince, 0.01)
                  fpsEma = fpsEma == 0 and instant or fpsEma * 0.8 + instant * 0.2
                  fpsFrames, fpsSince = 0, current
              end
          end)
          statsLoop = task.spawn(function()
              while gui.Parent and settings.statsBar do
                  updateStatsText()
                  if refreshHealth then pcall(refreshHealth) end
                  task.wait(0.5)
              end
              statsRunning = false
              if statsRenderConn then statsRenderConn:Disconnect() statsRenderConn = nil end
          end)
      end
      cleanups[#cleanups + 1] = function()
          if statsLoop then pcall(task.cancel, statsLoop) end
          if statsRenderConn then statsRenderConn:Disconnect() end
      end
      if settings.statsBar then startStats() else stopStats() end

      -- Account Health was removed from the visible GUI. The internal flag
      -- guard remains available to the redeem pipeline, but it has no panel,
      -- meter or reset button competing with the useful controls.
      refreshHealth = function() end

      UI._redeemThrottle = function(meta)
          if settings.flagCheck and flag.verdict == "MID FLAG" then return 0.4 end
          return BUFFER_THROTTLE
      end
      UI._redeemGuard = function(meta)
          if core.panicActive then return false end
          meta = type(meta) == "table" and meta or {}
          if meta.manual then
              if flag.verdict == "FLAG" then log("Manual redeem bypassed flag backoff", "sys") end
              return true
          end
          if settings.flagCheck and flag.verdict == "FLAG" then
              local current = os.clock()
              if current < flag.suspendUntil then return false end
              if current < flag.nextAllowed then return false end
              flag.nextAllowed = current + 10
          end
          return true
      end
      UI._redeemOutcome = function(code, ok, message, meta, latency)
          meta = type(meta) == "table" and meta or {}
          if not meta.final and not meta.manual then return end
          redeemCount += 1
          local source = meta.manual and "manual" or "trigger"
          session.seen += 1
          session[source] = (session[source] or 0) + 1
          local lower = tostring(message or ""):lower()
          local issue = ok and "good" or lower:find("timeout", 1, true) and "timeout" or "bad"
          if issue == "good" then session.good += 1 elseif issue == "timeout" then session.timeout += 1 else session.bad += 1 end
          local verdict = flag.verdict
          history[#history + 1] = { at = os.date("%H:%M:%S"), code = code, issue = issue, source = source, latency = latency, verdict = verdict }
          while #history > 300 do table.remove(history, 1) end
          if UI._renderHistory then task.defer(UI._renderHistory) end
          if settings.flagCheck then
              flag.attempts += 1
              if flag.attempts > flag.warmup then
                  if issue == "good" then
                      flag.samples[#flag.samples + 1] = latency
                      while #flag.samples > 10 do table.remove(flag.samples, 1) end
                  elseif issue == "timeout" then flag.timeouts += 1 else flag.invalid += 1 end
                  local nextVerdict = healthVerdict()
                  if nextVerdict ~= flag.verdict then
                      flag.verdict = nextVerdict
                  end
                  if flag.verdict == "FLAG" and flag.suspendUntil <= os.clock() then
                      flag.suspendUntil = os.clock() + 20
                      flag.nextAllowed = flag.suspendUntil
                  elseif flag.verdict ~= "FLAG" then
                      flag.suspendUntil, flag.nextAllowed = 0, 0
                  end
                  log(string.format("Flag measure · %s · %s · %dms · %s", code, issue, latency, flag.verdict), "sys")
              end
          end
          refreshHealth(); updateStatsText()
          if issue == "good" and settings.successSound then
              playSuccessSound()
          end
      end
      refreshHealth()

      core.Stats = Stats
      core.TeleportService = TeleportService
      core.TextService = TextService
      core.sessionStarted = sessionStarted
      core.session = session
      core.history = history
      core.flag = flag
      core.profileStore = profileStore
      core.profileFile = profileFile
      core.refreshHealth = refreshHealth
      core.updateStatsText = updateStatsText
      core.startStats = startStats
      core.stopStats = stopStats
      core.healthAverage = healthAverage
      core.healthVerdict = healthVerdict
      core.currentBackoff = currentBackoff
      core.verdictColor = verdictColor
      core.statsBar = statsBar
      core.statsText = statsText
      core.statsDivider = statsDivider
      core.statsBrand = statsBar:FindFirstChildWhichIsA("TextLabel")
      core.statsLogo = statsLogo
      core.playSuccessSound = playSuccessSound
      end
      UI._installStatsHealth()
      UI._installStatsHealth = nil
      UI._installManualAndHistory = function()
      local sessionStarted = core.sessionStarted
      local session = core.session
      local history = core.history
      local flag = core.flag
      local refreshHealth = core.refreshHealth
      local updateStatsText = core.updateStatsText
      local startStats = core.startStats
      local stopStats = core.stopStats

      local function armScan()
          if collecting or retypeListening then UI.cancelTracking() end
          manualScanArmed, scanDeadline = not manualScanArmed, 0
          if manualScanArmed then
              scanDeadline = os.clock() + 15
              toast("Scan armed", "Listening for 15 seconds", false, "good")
              task.delay(15, function()
                  if manualScanArmed and os.clock() >= scanDeadline then
                      manualScanArmed, scanDeadline = false, 0
                      toast("Scan expired", "No announcement captured", false, "warn")
                  end
              end)
          else
              toast("Scan", "Disarmed", false, "sys")
          end
      end
      UI._armManualScan = armScan
      local function toggleRiddleScan()
          riddleScanArmed = not riddleScanArmed
          if riddleScanArmed then
              if UI.setArmed and not settings.armed then UI.setArmed(true, true) end
              log("Riddle scan armed · waiting for the next question", "good")
              toast("Scan riddle", "Waiting for the next question", false, "good")
          else
              log("Riddle scan cancelled", "sys")
              toast("Scan riddle", "Cancelled", false, "sys")
          end
      end
      UI._toggleRiddleScan = toggleRiddleScan
      cleanups[#cleanups + 1] = function()
          if UI._armManualScan == armScan then UI._armManualScan = nil end
          if UI._toggleRiddleScan == toggleRiddleScan then UI._toggleRiddleScan = nil end
      end
      local historyPanel = box({ Name = "CodeHistory", Position = UDim2.fromOffset(PX, HISTORY_Y),
          Size = UDim2.new(1, -PX * 2, 0, HISTORY_H), BackgroundColor3 = C.Panel, Parent = logsScroll }, { corner(8), stroke(C.Line) })
      text({ Text = "REDEEM HISTORY", FontFace = F.Bold, TextSize = 11, Position = UDim2.fromOffset(10, 8), Size = UDim2.fromOffset(160, 16), Parent = historyPanel })
      local historyCopy = smallButton(historyPanel, "Copy history", C.Sub)
      local historyClear = smallButton(historyPanel, "Clear history", C.Sub)
      historyClear.Position = UDim2.new(1, -80, 0, 8)
      historyCopy.Position = UDim2.new(1, -154, 0, 8)
      local historyScroll = new("ScrollingFrame", { Position = UDim2.fromOffset(10, 30), Size = UDim2.new(1, -20, 1, -38),
          BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = TOUCH_DEVICE and 5 or 2, ScrollBarImageColor3 = C.Faint,
          AutomaticCanvasSize = Enum.AutomaticSize.Y, CanvasSize = UDim2.new(), Parent = historyPanel })
      new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2), Parent = historyScroll })
      local summaryText = text({ Text = "Session 0 seen · 0 good · 0 bad", FontFace = F.Mono, TextSize = 9, TextColor3 = C.Sub,
          Position = UDim2.fromOffset(10, HISTORY_Y + HISTORY_H + 8), Size = UDim2.new(1, -120, 0, 16), Parent = logsScroll })
      local exportSession = smallButton(logsScroll, "Export", C.Sub)
      exportSession.Position = UDim2.new(1, -PX, 0, HISTORY_Y + HISTORY_H + 4)
      local historyRowConns = {}
      cleanups[#cleanups + 1] = function()
          for _, connection in ipairs(historyRowConns) do pcall(function() connection:Disconnect() end) end
          table.clear(historyRowConns)
      end
      local function copyHistoryItem(item)
          local line = string.format("%s\t%s\t%s\t%s\t%s\t%s", item.at, item.code, item.issue, item.source, item.latency or "--", item.verdict)
          local copy = setclipboard or toclipboard or (syn and syn.write_clipboard)
          if type(copy) == "function" and pcall(copy, line) then toast("History", "Line copied", false, "good") else toast("History", "Clipboard unavailable", false, "warn") end
      end
      local function renderHistory()
          for _, connection in ipairs(historyRowConns) do pcall(function() connection:Disconnect() end) end
          table.clear(historyRowConns)
          for _, child in ipairs(historyScroll:GetChildren()) do if child:IsA("TextLabel") or child:IsA("TextButton") then child:Destroy() end end
          local function outcomeLabel(value)
              return value == "good" and "SUCCESS" or value == "timeout" and "TIMEOUT" or "FAILED"
          end
          local function sourceLabel(value)
              return value == "manual" and "MANUAL" or "TRIGGER"
          end
          local function verdictLabel(value)
              return value == "WARMING UP" and "WARMING" or tostring(value or "--")
          end
          for i, item in ipairs(history) do
              local color = item.issue == "good" and C.Green or item.issue == "timeout" and C.Sub or C.Red
              local row = button({
                  LayoutOrder = i,
                  Text = string.format("%s  %-14s %-8s %-7s %4sms  %s", item.at, item.code, outcomeLabel(item.issue), sourceLabel(item.source), tostring(item.latency or "--"), verdictLabel(item.verdict)),
                  FontFace = F.Mono, TextSize = 9, TextColor3 = color, TextXAlignment = Enum.TextXAlignment.Left,
                  TextTruncate = Enum.TextTruncate.AtEnd, Size = UDim2.new(1, -4, 0, 16),
                  BackgroundColor3 = C.Panel, BackgroundTransparency = 0.18, Parent = historyScroll,
              }, { corner(3), pad(0, 6, 0, 6) })
              hoverColor(row, C.Panel, C.Hover)
              historyRowConns[#historyRowConns + 1] = row.Activated:Connect(function() copyHistoryItem(item) end)
          end
          local latencyTotal = 0
          local latencyCount = 0
          for _, value in ipairs(history) do
              if type(value.latency) == "number" and value.latency > 0 then latencyTotal += value.latency; latencyCount += 1 end
          end
          local averageLatency = latencyCount > 0 and math.floor(latencyTotal / latencyCount + 0.5) or 0
          summaryText.Text = string.format("%ds · Seen %d · Success %d · Failed %d · Timeout %d · %.0f%% · Avg %d ms",
              math.floor(os.clock() - sessionStarted), session.seen, session.good, session.bad, session.timeout,
              session.seen > 0 and session.good / session.seen * 100 or 0, averageLatency)
      end
      local function historyText()
          local out = { "AZERTOX SESSION", "duration=" .. math.floor(os.clock() - sessionStarted) .. "s", summaryText.Text, "" }
          for _, item in ipairs(history) do out[#out + 1] = string.format("%s\t%s\t%s\t%s\t%s\t%s", item.at, item.code, item.issue, item.source, item.latency or "--", item.verdict) end
          return table.concat(out, "\n")
      end
      on(historyClear.Activated, function() table.clear(history); renderHistory(); log("Code history cleared", "sys") end)
      on(historyCopy.Activated, function()
          local body = historyText(); local copy = setclipboard or toclipboard or (syn and syn.write_clipboard)
          if type(copy) == "function" and pcall(copy, body) then toast("History", "Copied", false, "good") else toast("History", "Clipboard unavailable", false, "warn") end
      end)
      on(exportSession.Activated, function()
          local body = historyText(); local wrote = false
          if type(writefile) == "function" then wrote = pcall(writefile, "azertox_session.txt", body) end
          if wrote then toast("Session", "Exported azertox_session.txt", true, "good") else
              local copy = setclipboard or toclipboard or (syn and syn.write_clipboard)
              if type(copy) == "function" and pcall(copy, body) then toast("Session", "File API unavailable; copied instead", false, "sys") else toast("Session", "Export unavailable", false, "warn") end
          end
      end)
      UI._renderHistory = renderHistory

      end
      UI._installManualAndHistory()
      UI._installManualAndHistory = nil
      -- ---------------------------------------------------------------------
      -- Runtime support layer
      -- ---------------------------------------------------------------------
      -- Keep this layer in its own function scope. The surrounding Admin page
      -- has many UI locals; Luau's 200-register limit must not include them
      -- while compiling runtimeDecode and the diagnostics helpers.
      UI._installRuntime = function()
      local sessionStarted = core.sessionStarted
      local session = core.session
      local history = core.history
      local flag = core.flag
      local profileStore = core.profileStore
      local profileFile = core.profileFile
      local refreshHealth = core.refreshHealth
      local updateStatsText = core.updateStatsText
      local healthAverage = core.healthAverage
      local currentBackoff = core.currentBackoff
      local startStats = core.startStats
      local stopStats = core.stopStats
      local TeleportService = core.TeleportService
      local runtime = {
          diagnostics = {},
          reconnectScheduled = false,
          reconnectToken = 0,
          layoutBounds = { minScale = 0.5, maxScale = 1 },
          historyVersion = 1,
          profileVersion = 1,
      }

      function runtime.record(kind, message, data)
          local record = {
              at = os.date("%H:%M:%S"),
              kind = tostring(kind or "info"),
              message = tostring(message or ""),
              data = type(data) == "table" and data or nil,
          }
          runtime.diagnostics[#runtime.diagnostics + 1] = record
          while #runtime.diagnostics > 200 do table.remove(runtime.diagnostics, 1) end
          return record
      end

      function runtime.copy(value)
          local copy = setclipboard or toclipboard or (syn and syn.write_clipboard)
          if type(copy) ~= "function" then return false, "clipboard unavailable" end
          local ok, err = pcall(copy, tostring(value or ""))
          return ok, ok and "copied" or tostring(err)
      end

      function runtime.write(path, value)
          if type(writefile) ~= "function" then return false, "writefile unavailable" end
          local ok, err = pcall(writefile, path, tostring(value or ""))
          return ok, ok and "written" or tostring(err)
      end

      local function runtimeRead(path)
          if type(isfile) ~= "function" or type(readfile) ~= "function" then return false, "readfile unavailable" end
          local exists, present = pcall(isfile, path)
          if not exists or not present then return false, "file not found" end
          local ok, value = pcall(readfile, path)
          return ok, ok and value or tostring(value)
      end

      local function runtimeEncode(value)
          local ok, encoded = pcall(ConfigHttp.JSONEncode, ConfigHttp, value)
          return ok, ok and encoded or tostring(encoded)
      end

      local function runtimeDecode(value)
          local ok, decoded = pcall(ConfigHttp.JSONDecode, ConfigHttp, value)
          return ok, ok and decoded or tostring(decoded)
      end

      local function safeNumber(value, fallback, low, high)
          local number = tonumber(value)
          if not number or number ~= number or number == math.huge or number == -math.huge then return fallback end
          if low and number < low then return fallback end
          if high and number > high then return fallback end
          return number
      end

      local function safeBoolean(value, fallback)
          return type(value) == "boolean" and value or fallback
      end

      local function safeString(value, fallback, limit)
          if type(value) ~= "string" then return fallback end
          value = value:gsub("[%c]", ""):sub(1, limit or 120)
          return value ~= "" and value or fallback
      end

      local function normaliseProfileName(value)
          local name = safeString(value, "default", 32):gsub("[^%w_%-]", "")
          return name ~= "" and name or "default"
      end

      local function normaliseTriggerList(value)
          if type(value) ~= "table" then return nil, "trigger list is not a table" end
          local list, seenTriggers = {}, {}
          for _, raw in ipairs(value) do
              if type(raw) ~= "string" then return nil, "trigger is not a string" end
              local trigger = raw:gsub("[%c]", ""):sub(1, 80)
              local key = trigger:lower()
              if trigger ~= "" and not seenTriggers[key] then
                  seenTriggers[key] = true
                  list[#list + 1] = trigger
              end
          end
          if #list == 0 then return nil, "trigger list is empty" end
          return list
      end

      local function runtimeSnapshot()
          local snapshot = {
              version = runtime.profileVersion,
              triggers = table.clone(settings.triggers),
              toggleKey = settings.toggleKey.Name,
          }
          for key in pairs(PERSISTED) do snapshot[key] = settings[key] end
          snapshot.windowScale = safeNumber(snapshot.windowScale, 1, 0.5, 1)
          snapshot.successVolume = safeNumber(snapshot.successVolume, 0.25, 0, 1)
          snapshot.rejoinDelay = safeNumber(snapshot.rejoinDelay, 5, 1, 60)
          return snapshot
      end

      local function applySnapshot(value)
          if type(value) ~= "table" then return false, "profile is not an object" end
          for key, kind in pairs(PERSISTED) do
              if value[key] ~= nil and type(value[key]) ~= kind then return false, "invalid " .. key end
          end
          if value.toggleKey ~= nil and (type(value.toggleKey) ~= "string" or not Enum.KeyCode[value.toggleKey]) then
              return false, "invalid toggleKey"
          end
          if type(value.triggers) == "table" then
              local nextTriggers = {}
              for _, trigger in ipairs(value.triggers) do
                  if type(trigger) == "string" and trigger ~= "" then nextTriggers[#nextTriggers + 1] = trigger:sub(1, 80) end
              end
              if #nextTriggers == 0 then return false, "no triggers" end
              settings.triggers = nextTriggers
          elseif value.triggers ~= nil then
              return false, "invalid triggers"
          end
          for key in pairs(PERSISTED) do
              if value[key] ~= nil then settings[key] = value[key] end
          end
          if value.toggleKey then settings.toggleKey = Enum.KeyCode[value.toggleKey] end
          settings.submitAfter = math.clamp(math.floor(tonumber(settings.submitAfter) or 3), 1, 5)
          settings.successVolume = math.clamp(tonumber(settings.successVolume) or 0.25, 0, 1)
          settings.rejoinDelay = math.clamp(tonumber(settings.rejoinDelay) or 5, 1, 60)
          settings.windowScale = math.clamp(tonumber(settings.windowScale) or 1, 0.5, 1)
          rebuildTriggerCache()
          writeConfig()
          return true
      end

      local function runtimeApplySnapshot(value)
          if type(value) ~= "table" then return false, "profile is not an object" end
          local copy = table.clone(value)
          local valid, reason = applySnapshot(copy)
          if not valid then return false, reason end
          runtime.record("profile", "snapshot applied", { name = safeString(value.name, "default", 32) })
          return true
      end

      local function exportSessionText()
          local rows = {
              "AZERTOX SESSION SUMMARY",
              "version=" .. tostring(runtime.historyVersion),
              "duration=" .. tostring(math.floor(os.clock() - sessionStarted)) .. "s",
              "seen=" .. tostring(session.seen),
              "good=" .. tostring(session.good),
              "bad=" .. tostring(session.bad),
              "timeout=" .. tostring(session.timeout),
              "trigger=" .. tostring(session.trigger),
              "manual=" .. tostring(session.manual),
              "flag=" .. tostring(flag.verdict),
              "samples=" .. tostring(#flag.samples),
              "timeouts=" .. tostring(flag.timeouts),
              "",
              "AT\tCODE\tISSUE\tSOURCE\tLATENCY\tVERDICT",
          }
          for _, item in ipairs(history) do
              rows[#rows + 1] = table.concat({ item.at, item.code, item.issue, item.source, item.latency or "--", item.verdict }, "\t")
          end
          return table.concat(rows, "\n")
      end

      local function exportSessionSafe()
          local body = exportSessionText()
          local path = "azertox_session.txt"
          local wrote, result = runtime.write(path, body)
          if wrote then
              runtime.record("export", "session written", { path = path })
              return true, "Exported " .. path
          end
          local copied, copyResult = runtime.copy(body)
          if copied then
              runtime.record("export", "session copied", { fallback = result })
              return true, "File API unavailable; copied instead"
          end
          runtime.record("export", "session export failed", { write = result, copy = copyResult })
          return false, "Export unavailable"
      end

      local function profileFileValue()
          local ok, raw = runtime.read(profileFile)
          if not ok then return {} end
          local decoded, value = runtimeDecode(raw)
          if not decoded or type(value) ~= "table" then return {} end
          return value
      end

      local function saveRuntimeProfiles(value)
          local ok, encoded = runtimeEncode(value)
          if not ok then return false, encoded end
          return runtime.write(profileFile, encoded)
      end

      local function saveNamedProfile(name)
          name = normaliseProfileName(name)
          local profiles = profileFileValue()
          profiles[name] = runtimeSnapshot()
          profileStore[name] = profiles[name]
          local ok, result = saveRuntimeProfiles(profiles)
          runtime.record("profile", ok and "profile saved" or "profile save failed", { name = name, result = result })
          return ok, result
      end

      local function deleteNamedProfile(name)
          name = normaliseProfileName(name)
          local profiles = profileFileValue()
          if not profiles[name] then return false, "profile not found" end
          profiles[name] = nil
          profileStore[name] = nil
          local ok, result = saveRuntimeProfiles(profiles)
          runtime.record("profile", ok and "profile deleted" or "profile delete failed", { name = name, result = result })
          return ok, result
      end

      local function loadNamedProfile(name)
          name = normaliseProfileName(name)
          local value = profileStore[name] or profileFileValue()[name]
          if not value then return false, "profile not found" end
          local ok, result = runtimeApplySnapshot(value)
          runtime.record("profile", ok and "profile loaded" or "profile load failed", { name = name, result = result })
          return ok, result
      end

      local function encodeNamedProfile(name)
          name = normaliseProfileName(name)
          local ok, encoded = runtimeEncode(runtimeSnapshot())
          runtime.record("profile", ok and "profile encoded" or "profile encode failed", { name = name })
          return ok, encoded
      end

      local function decodeNamedProfile(encoded)
          local ok, value = runtimeDecode(encoded)
          if not ok then return false, value end
          return runtimeApplySnapshot(value)
      end

      local function appendDiagnostic(kind, message, data)
          local record = runtime.record(kind, message, data)
          log(string.format("%s: %s", tostring(kind), tostring(message)), kind == "error" and "bad" or "sys")
          return record
      end

      local function classifyResult(ok, message)
          if ok then return "good" end
          local lower = tostring(message or ""):lower()
          if lower:find("timeout", 1, true) then return "timeout" end
          return "bad"
      end

      local function currentHealthSnapshot()
          return {
              enabled = settings.flagCheck,
              verdict = settings.flagCheck and flag.verdict or "OFF",
              average = healthAverage(),
              samples = #flag.samples,
              invalid = flag.invalid,
              timeouts = flag.timeouts,
              suspendUntil = flag.suspendUntil,
              nextAllowed = flag.nextAllowed,
          }
      end

      local function clearHealthStats()
          flag.attempts, flag.samples, flag.invalid, flag.timeouts = 0, {}, 0, 0
          flag.verdict, flag.suspendUntil, flag.nextAllowed = "WARMING UP", 0, 0
          refreshHealth()
          updateStatsText()
          runtime.record("health", "health stats reset")
      end

      local function appendHistoryItem(code, issue, source, latency, verdict)
          if type(code) ~= "string" or code == "" then return false end
          history[#history + 1] = {
              at = os.date("%H:%M:%S"),
              code = code,
              issue = issue == "good" or issue == "timeout" and "timeout" or "bad",
              source = source == "manual" and "manual" or "trigger",
              latency = tonumber(latency) or 0,
              verdict = verdict or flag.verdict,
          }
          while #history > 300 do table.remove(history, 1) end
          if UI._renderHistory then task.defer(UI._renderHistory) end
          return true
      end

      local function historyForSource(source)
          local rows = {}
          for _, item in ipairs(history) do
              if not source or item.source == source then rows[#rows + 1] = item end
          end
          return rows
      end

      local function historyForIssue(issue)
          local rows = {}
          for _, item in ipairs(history) do
              if not issue or item.issue == issue then rows[#rows + 1] = item end
          end
          return rows
      end

      local function countHistory(issue, source)
          local count = 0
          for _, item in ipairs(history) do
              if (not issue or item.issue == issue) and (not source or item.source == source) then count += 1 end
          end
          return count
      end

      local function historyAverage()
          local totalLatency, count = 0, 0
          for _, item in ipairs(history) do
              if type(item.latency) == "number" and item.latency > 0 then totalLatency += item.latency; count += 1 end
          end
          return count > 0 and totalLatency / count or 0
      end

      local function sessionSnapshot()
          return {
              duration = math.floor(os.clock() - sessionStarted),
              seen = session.seen,
              good = session.good,
              bad = session.bad,
              timeout = session.timeout,
              trigger = session.trigger,
              manual = session.manual,
              successRate = session.seen > 0 and session.good / session.seen or 0,
              latency = historyAverage(),
              health = currentHealthSnapshot(),
          }
      end

      local function validateHistoryRow(item)
          return type(item) == "table"
              and type(item.code) == "string"
              and (item.issue == "good" or item.issue == "bad" or item.issue == "timeout")
              and (item.source == "trigger" or item.source == "manual")
      end

      local function copyHistoryRows(rows)
          local lines = {}
          for _, item in ipairs(rows or {}) do
              if validateHistoryRow(item) then
                  lines[#lines + 1] = table.concat({ item.at or "--", item.code, item.issue, item.source, item.latency or "--", item.verdict or "--" }, "\t")
              end
          end
          return runtime.copy(table.concat(lines, "\n"))
      end

      local function copyFilteredHistory(issue, source)
          local ok, result = copyHistoryRows(historyForSource(source))
          if issue and ok then
              local rows = historyForIssue(issue)
              ok, result = copyHistoryRows(rows)
          end
          return ok, result
      end

      local function resetSessionHistory()
          table.clear(history)
          session.seen, session.good, session.bad, session.timeout = 0, 0, 0, 0
          session.manual, session.trigger = 0, 0
          if UI._renderHistory then UI._renderHistory() end
          runtime.record("history", "session history reset")
      end

      local function statusLine()
          local health = currentHealthSnapshot()
          return string.format("seen=%d good=%d bad=%d timeout=%d flag=%s avg=%dms backoff=%s",
              session.seen, session.good, session.bad, session.timeout, health.verdict,
              math.floor(health.average + 0.5), currentBackoff())
      end

      local function exportDiagnostics()
          local lines = { "AZERTOX DIAGNOSTICS", statusLine(), "" }
          for _, record in ipairs(runtime.diagnostics) do
              lines[#lines + 1] = string.format("[%s] [%s] %s", record.at, record.kind, record.message)
          end
          return runtime.copy(table.concat(lines, "\n"))
      end

      local function boundedLayout()
          local camera = workspace.CurrentCamera
          local viewport = camera and camera.ViewportSize
          local scale = math.clamp(tonumber(settings.windowScale) or 1, runtime.layoutBounds.minScale, runtime.layoutBounds.maxScale)
          if viewport then
              local width, height = W * scale, H * scale
              local x = math.clamp(tonumber(settings.windowX) or viewport.X - width - 24, 8, math.max(8, viewport.X - width - 8))
              local y = math.clamp(tonumber(settings.windowY) or 24, 8, math.max(8, viewport.Y - height - 8))
              settings.windowX, settings.windowY = math.floor(x), math.floor(y)
              holder.Position = UDim2.fromOffset(settings.windowX, settings.windowY)
          end
          settings.windowScale = scale
          return scale
      end

      local function resetBoundedLayout()
          settings.windowX, settings.windowY, settings.windowScale = nil, nil, 1
          holder.Position = UDim2.new(0.5, -W / 2, 0.5, -H / 2)
          holder.AnchorPoint = Vector2.new(0, 0)
          uiScale.Scale = 1
          toastScale.Scale = 1
          saveSettings()
          runtime.record("layout", "layout reset")
      end

      local function scheduleReconnect(reason)
          if runtime.reconnectScheduled or destroyed then return end
          runtime.reconnectScheduled = true
          runtime.reconnectToken += 1
          local token = runtime.reconnectToken
          local delaySeconds = math.clamp(tonumber(settings.rejoinDelay) or 5, 1, 60)
          log("Reconnect scheduled: " .. tostring(reason or "connection lost"), "sys")
          task.delay(delaySeconds, function()
              if token ~= runtime.reconnectToken or destroyed then return end
              runtime.reconnectScheduled = false
              local ok, err = pcall(function() TeleportService:Teleport(game.PlaceId, player) end)
              log(ok and "Reconnect requested" or ("Reconnect failed: " .. tostring(err)), ok and "sys" or "bad")
          end)
      end

      local function cancelReconnect()
          runtime.reconnectToken += 1
          runtime.reconnectScheduled = false
      end

      local function installReconnectMonitor()
          on(player.AncestryChanged, function(_, parent)
              if not parent and not destroyed then scheduleReconnect("player removed") end
          end)
          on(game:GetPropertyChangedSignal("PlaceId"), function() cancelReconnect() end)
          cleanups[#cleanups + 1] = cancelReconnect
      end

      local function runMatcherDiagnostics()
          local cases = {
              { "the code is ALPHA", true },
              { "The Code Is beta", true },
              { "ordinary chat without a trigger", false },
              { "use code: GAMMA", true },
          }
          local passed = 0
          for _, item in ipairs(cases) do
              local lowered = item[1]:lower()
              local matched = false
              for _, trigger in ipairs(settings.triggers) do
                  if lowered:find(tostring(trigger):lower(), 1, true) then matched = true break end
              end
              if matched == item[2] then passed += 1 end
          end
              runtime.record("diagnostic", "matcher checked", { passed = passed, total = #cases })
          return passed, #cases
      end

      local function runPipelineDiagnostics()
          local cases = {
              { name = "configured collection", parts = { "ALPHA", "BETA", "GAMMA" } },
              { name = "single line", parts = { "ONE", "TWO", "THREE" } },
              { name = "duplicate case", parts = { "RED", "red", "BLUE" } },
              { name = "five part cap", parts = { "A", "B", "C", "D", "E" } },
          }
          for _, item in ipairs(cases) do
              local unique, seenCase = {}, {}
              for _, part in ipairs(item.parts) do
                  local key = tostring(part):upper()
                  if not seenCase[key] then seenCase[key] = true; unique[#unique + 1] = part end
              end
              runtime.record("diagnostic", item.name, { input = #item.parts, unique = #unique })
          end
          return true
      end

      local function runProfileDiagnostics()
          local snapshot = runtimeSnapshot()
          local encodedOk, encoded = runtimeEncode(snapshot)
          if not encodedOk then return false, "encode failed" end
          local decodedOk, decoded = runtimeDecode(encoded)
          if not decodedOk or type(decoded) ~= "table" then return false, "decode failed" end
          local valid = decoded.submitAfter == snapshot.submitAfter and decoded.hudName == snapshot.hudName
          runtime.record("diagnostic", "profile round trip", { valid = valid })
          return valid, valid and "ok" or "round trip mismatch"
      end

      local function runDiagnostics()
          local matcherPassed, matcherTotal = runMatcherDiagnostics()
          local pipelineOk = runPipelineDiagnostics()
          local profileOk = runProfileDiagnostics()
          local result = matcherPassed == matcherTotal and pipelineOk and profileOk
          log("Diagnostics " .. (result and "passed" or "reported failures"), result and "good" or "bad")
          return result
      end

      local function installRuntimeApi()
          UI.runtime = {
              copy = runtime.copy,
              read = runtimeRead,
              write = runtime.write,
              encode = runtimeEncode,
              decode = runtimeDecode,
              snapshot = runtimeSnapshot,
              apply = runtimeApplySnapshot,
              saveProfile = saveNamedProfile,
              loadProfile = loadNamedProfile,
              deleteProfile = deleteNamedProfile,
              exportProfile = encodeNamedProfile,
              importProfile = decodeNamedProfile,
              exportSession = exportSessionSafe,
              exportDiagnostics = exportDiagnostics,
              history = historyForSource,
              historyCount = countHistory,
              session = sessionSnapshot,
              health = currentHealthSnapshot,
              resetHealth = clearHealthStats,
              resetHistory = resetSessionHistory,
              layout = boundedLayout,
              resetLayout = resetBoundedLayout,
              diagnostics = runDiagnostics,
              status = statusLine,
          }
          runtime.record("runtime", "support layer ready")
      end

      installReconnectMonitor()
      installRuntimeApi()
      boundedLayout()
      cleanups[#cleanups + 1] = function()
          runtime.reconnectToken += 1
          runtime.reconnectScheduled = false
          UI.runtime = nil
      end

      end
      UI._installRuntime()
      UI._installThemeAndLifecycle = function()
      local statsBar = core.statsBar
      local statsText = core.statsText
      local statsDivider = core.statsDivider
      local statsBrand = core.statsBrand
      local statsLogo = core.statsLogo
      local refreshHealth = core.refreshHealth
      local startStats = core.startStats
      local stopStats = core.stopStats
      local TeleportService = core.TeleportService
      local themeButtons = {}
      local currentThemeAccent, currentThemeRaise = C.Cyan, C.Raise

      local function repaintTheme()
          local theme = tostring(settings.theme or "blue")
          local background, panel, hover, raise, line, edge, accent
          if theme == "christmas" or theme == "winter" then
              background, panel, hover, raise, line, edge, accent = C.ChristmasBg, C.ChristmasPanel, C.ChristmasHover, C.ChristmasRaise, C.ChristmasLine, C.ChristmasEdge, C.ChristmasAccent
          elseif theme == "violet" then
              background, panel, hover, raise, line, edge, accent = C.VioletBg, C.VioletPanel, C.VioletHover, C.VioletRaise, C.VioletLine, C.VioletEdge, C.VioletAccent
          elseif theme == "rose" then
              background, panel, hover, raise, line, edge, accent = C.RoseBg, C.RosePanel, C.RoseHover, C.RoseRaise, C.RoseLine, C.RoseEdge, C.RoseAccent
          else
              background, panel, hover, raise, line, edge, accent = C.Bg, C.Panel, C.Hover, C.Raise, C.Line, C.Edge, C.Cyan
          end
          currentThemeAccent, currentThemeRaise = accent, raise
          UI._themePanel, UI._themeHover = panel, hover
          UI._themeRaise, UI._themeLine = raise, line
          UI._themeEdge, UI._themeAccent = edge, accent
          local function same(a, b)
              return colorHex(a) == colorHex(b)
          end
          local function sameAny(value, colors)
              for _, color in ipairs(colors) do if same(value, color) then return true end end
              return false
          end
          local backgrounds = { C.Bg, C.WinterBg, C.ChristmasBg, C.VioletBg, C.RoseBg }
          local panels = { C.Panel, C.WinterPanel, C.ChristmasPanel, C.VioletPanel, C.RosePanel }
          local hovers = { C.Hover, C.WinterHover, C.ChristmasHover, C.VioletHover, C.RoseHover }
          local raises = { C.Raise, C.WinterRaise, C.ChristmasRaise, C.VioletRaise, C.RoseRaise }
          local lines = { C.Line, C.WinterLine, C.ChristmasLine, C.VioletLine, C.RoseLine }
          local edges = { C.Edge, C.WinterEdge, C.ChristmasEdge, C.VioletEdge, C.RoseEdge }
          local accents = { C.Cyan, C.WinterAccent, C.ChristmasAccent, C.VioletAccent, C.RoseAccent }
          local function themedColor(value)
              if sameAny(value, backgrounds) then return background end
              if sameAny(value, panels) then return panel end
              if sameAny(value, hovers) then return hover end
              if sameAny(value, raises) then return raise end
              if sameAny(value, lines) then return line end
              if sameAny(value, edges) then return edge end
              if sameAny(value, accents) then return accent end
              return value
          end
          for _, binding in ipairs(hoverBindings) do
              binding.rest = themedColor(binding.baseRest)
              binding.hover = themedColor(binding.baseHover)
          end
          for _, obj in ipairs(gui:GetDescendants()) do
              pcall(function()
                  if obj:IsA("Frame") or obj:IsA("GuiButton") or obj:IsA("TextBox") then
                      local n = obj.Name:lower()
                      local current = obj.BackgroundColor3
                      if n:find("rail", 1, true) then
                          obj.BackgroundColor3 = panel
                      elseif sameAny(current, backgrounds) then
                          obj.BackgroundColor3 = background
                      elseif sameAny(current, panels) then
                          obj.BackgroundColor3 = panel
                      elseif sameAny(current, hovers) then
                          obj.BackgroundColor3 = hover
                      elseif sameAny(current, raises) then
                          obj.BackgroundColor3 = raise
                      elseif sameAny(current, lines) then
                          obj.BackgroundColor3 = line
                      elseif sameAny(current, edges) then
                          obj.BackgroundColor3 = edge
                      elseif sameAny(current, accents) then
                          obj.BackgroundColor3 = accent
                      end
                  end
                  if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
                      if sameAny(obj.TextColor3, accents) then obj.TextColor3 = accent end
                  elseif obj:IsA("UIStroke") then
                      if sameAny(obj.Color, lines) then obj.Color = line
                      elseif sameAny(obj.Color, edges) then obj.Color = edge
                      elseif sameAny(obj.Color, accents) then obj.Color = accent end
                  elseif obj:IsA("UIGradient") then
                      obj.Color = ColorSequence.new(edge, raise)
                  end
              end)
          end
          win.BackgroundColor3, rail.BackgroundColor3 = background, panel
          railFill.BackgroundColor3, indicator.BackgroundColor3 = accent, accent
          statsBar.BackgroundColor3, statsText.TextColor3 = panel, (theme == "christmas" or theme == "winter") and C.Cream or C.Sub
          if statsBrand then statsBrand.TextColor3 = (theme == "christmas" or theme == "winter") and C.Cream or C.Text end
          if statsLogo then paint(statsLogo, accent, 0.1) end
          if statsDivider then statsDivider.BackgroundColor3 = accent end
          local christmasVisible = theme == "christmas" or theme == "winter"
          for _, hatPart in ipairs(santaHatParts) do hatPart.Visible = christmasVisible end
          setSnowMotion(christmasVisible)
          for value, themeButtonObject in pairs(themeButtons) do
              local active = value == theme
              tween(themeButtonObject, 0.15, {
                  BackgroundColor3 = active and accent or raise,
                  TextColor3 = active and background or C.Sub,
              })
          end
      end
      local themeRow = settingRow(1, "Theme")
      local function themeButton(label, value, x, width)
          local themeColors = { blue = C.Cyan, violet = C.VioletAccent, rose = C.RoseAccent, christmas = C.ChristmasAccent, winter = C.ChristmasAccent }
          local b = button({ Text = label, TextSize = 10, FontFace = F.Medium, TextColor3 = C.Sub, Position = UDim2.fromOffset(x, 8), Size = UDim2.fromOffset(width, 26), BackgroundColor3 = C.Raise, Parent = themeRow }, { corner(6), stroke(themeColors[value] or C.Edge) })
          hoverColor(b, C.Raise, themeColors[value] or C.Edge)
          on(b.Activated, function() settings.theme = value; saveSettings(); repaintTheme() end)
          themeButtons[value] = b
          return b
      end
