                  toast("Panic", "Restored", false, "good")
              end
          elseif input.KeyCode == Enum.KeyCode.RightShift then UI.cancelTracking() end
      end)
      cleanups[#cleanups + 1] = function() core.panicActive = true; stopStats() end

      local afkThread
      local function stopAfk() if afkThread then pcall(task.cancel, afkThread); afkThread = nil end end
      local function startAfk()
          stopAfk(); if not settings.antiAfk then return end
          afkThread = task.spawn(function()
              while gui.Parent and settings.antiAfk do
                  task.wait(45)
                  pcall(function()
                      local camera = workspace.CurrentCamera
                      if camera then local original = camera.CFrame; camera.CFrame = original * CFrame.Angles(0, math.rad(1), 0); task.wait(0.05); camera.CFrame = original end
                  end)
              end
          end)
      end
