      local englishButton, frenchButton
      local function refreshLanguageButtons()
          if not englishButton or not frenchButton then return end
          local english = settings.language ~= "fr"
          englishButton.BackgroundColor3 = english and currentThemeAccent or currentThemeRaise
          englishButton.TextColor3 = english and C.Bg or C.Sub
          frenchButton.BackgroundColor3 = english and currentThemeRaise or currentThemeAccent
          frenchButton.TextColor3 = english and C.Sub or C.Bg
      end
      local function applyLanguage()
          local french = settings.language == "fr"
          for _, obj in ipairs(gui:GetDescendants()) do
              if obj:IsA("TextLabel") or obj:IsA("TextButton") then
                  local english = obj:GetAttribute("EnglishText")
                  if type(english) ~= "string" then
                      english = obj.Text
                      obj:SetAttribute("EnglishText", english)
                  end
                  if french then obj.Text = languageMap[english] or english else obj.Text = english end
              end
          end
          refreshLanguageButtons()
      end
      local languageRow = settingRow(4, "Language")
      local languageGroup = box({ Position = UDim2.fromOffset(184, 5), Size = UDim2.fromOffset(136, 32),
          BackgroundColor3 = C.Raise, Parent = languageRow }, { corner(8), stroke(C.Line) })
      englishButton = button({ Text = "English", TextSize = 10, TextColor3 = C.Sub,
          Position = UDim2.fromOffset(3, 4), Size = UDim2.fromOffset(64, 24), BackgroundColor3 = C.Raise, Parent = languageGroup }, { corner(6) })
      frenchButton = button({ Text = "Français", TextSize = 10, TextColor3 = C.Sub,
          Position = UDim2.fromOffset(69, 4), Size = UDim2.fromOffset(64, 24), BackgroundColor3 = C.Raise, Parent = languageGroup }, { corner(6) })
      hoverColor(englishButton, C.Raise, C.Hover)
      hoverColor(frenchButton, C.Raise, C.Hover)
      on(englishButton.MouseLeave, refreshLanguageButtons)
      on(frenchButton.MouseLeave, refreshLanguageButtons)
      on(englishButton.Activated, function()
          settings.language = "en"; saveSettings(); applyLanguage()
          if UI._repaintTheme then UI._repaintTheme() end
          toast("Language", "English selected", false, "good")
      end)
      on(frenchButton.Activated, function()
          settings.language = "fr"; saveSettings(); applyLanguage()
          if UI._repaintTheme then UI._repaintTheme() end
          toast("Language", "Français sélectionné", false, "good")
      end)

      on(player.OnTeleport, function(state)
          if state == Enum.TeleportState.Failed or state == Enum.TeleportState.Cancelled then
              log("Reconnect: teleport failed, retrying", "bad")
              task.delay(math.clamp(settings.rejoinDelay, 1, 60), function() pcall(function() TeleportService:Teleport(game.PlaceId, player) end) end)
          elseif state == Enum.TeleportState.Started and type(queue_on_teleport) == "function" then
              pcall(queue_on_teleport, "if getgenv then getgenv().AZERTOX_REINJECT = true end")
              log("Reconnect: reinjection flag queued", "sys")
          end
      end)
      repaintTheme()
      applyLanguage()
      UI._applyLanguage = applyLanguage
      UI._repaintTheme = repaintTheme
      if UI._renderHistory then UI._renderHistory() end
  end



