  local renderTriggers
  local function removeTrigger(word)
      for i, w in ipairs(settings.triggers) do
          if w == word then table.remove(settings.triggers, i) break end
      end
      rebuildTriggerCache()
      saveSettings()
      renderTriggers()
  end
  renderTriggers = function()
      for _, child in ipairs(triggerList:GetChildren()) do
          if child:IsA("Frame") then child:Destroy() end
      end
      if #settings.triggers == 0 then
          local empty = box({ Size = UDim2.new(1, 0, 0, 32), Parent = triggerList })
          text({ Text = "No triggers, sniping is off", FontFace = F.Book, TextSize = 13, TextColor3 = C.Faint,
              Size = UDim2.fromScale(1, 1), Parent = empty })
          return
      end
      for i, word in ipairs(settings.triggers) do
          local row = box({ LayoutOrder = i, Size = UDim2.new(1, -4, 0, 36), BackgroundColor3 = C.Panel, Parent = triggerList }, { corner(8), stroke(C.Line) })
          row:SetAttribute("TriggerWord", word)
          row:SetAttribute("Brainrot", word)
          text({ Text = word, FontFace = F.Mono, TextSize = 11, TextTruncate = Enum.TextTruncate.AtEnd,
              Position = UDim2.fromOffset(14, 0), Size = UDim2.new(1, -58, 1, 0), Parent = row })
          local remove = button({
              Text = "×", FontFace = F.Bold, TextSize = 16, TextColor3 = C.Faint,
              TextXAlignment = Enum.TextXAlignment.Center,
              AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -10, 0.5, 0), Size = UDim2.fromOffset(26, 26),
              BackgroundColor3 = C.Raise, Parent = row,
          }, { corner(7) })
          hoverColor(remove, C.Raise, C.Red)
          remove.Activated:Connect(function() removeTrigger(word) end)
      end
  end

  UI._triggerFilter = new("TextBox", {
      Name = "TriggerFilter", Position = UDim2.fromOffset(PX, HELP_TOP + INPUT_H + 8),
      Size = UDim2.fromOffset(CW - PX * 2, 28), BackgroundColor3 = C.Panel,
      BorderSizePixel = 0, ClearTextOnFocus = false, Text = "",
      PlaceholderText = "Filter triggers...", PlaceholderColor3 = C.Faint,
      TextColor3 = C.Text, FontFace = F.Mono, TextSize = 11, Visible = false,
      Parent = triggersPage,
  }, { corner(4), pad(0, 8, 0, 8) })
  UI._baseRenderTriggers = renderTriggers
  renderTriggers = function()
      UI._baseRenderTriggers()
      UI._triggerFilter.Visible = #settings.triggers > 20
      triggerList.Position = UDim2.fromOffset(PX, HELP_TOP + INPUT_H + 8 + (UI._triggerFilter.Visible and 36 or 0))
      triggerList.Size = UDim2.fromOffset(CW - PX * 2, PAGE_H - HELP_TOP - INPUT_H - 8 - 20 - (UI._triggerFilter.Visible and 36 or 0))
      if not UI._triggerFilter.Visible then return end
      local filter = UI._triggerFilter.Text:lower()
      for _, row in ipairs(triggerList:GetChildren()) do
          if row:IsA("Frame") then
              local word = tostring(row:GetAttribute("TriggerWord") or "")
              local brainrot = tostring(row:GetAttribute("Brainrot") or "")
              row.Visible = filter == "" or word:lower():find(filter, 1, true) ~= nil
                  or brainrot:lower():find(filter, 1, true) ~= nil
          end
      end
  end
  on(UI._triggerFilter:GetPropertyChangedSignal("Text"), renderTriggers)

  local function addTrigger()
      local word = (triggerInput.Text:lower():gsub("[%c]", ""):gsub("%s+", " "):match("^%s*(.-)%s*$") or ""):sub(1, 80)
      triggerInput.Text = ""
      if word == "" then return end
      local looseWord = looseText(word)
      for _, w in ipairs(settings.triggers) do
          if looseText(w) == looseWord then return end
      end
      table.insert(settings.triggers, word)
      rebuildTriggerCache()
      saveSettings()
      renderTriggers()
      log("Trigger added: " .. word, "sys")
  end
  on(addBtn.Activated, addTrigger)
  on(triggerInput.FocusLost, function(enter) if enter then addTrigger() end end)
  renderTriggers()


  end
