  local function selectPage(name, animate)
      if currentPage == name then return end
      currentPage = name
      title.Text = name
      local themePanel = UI._themePanel or C.Panel
      local themeRaise = UI._themeRaise or C.Raise
      for n, nav in pairs(navs) do
          local active = n == name
          tween(nav.button, animate and 0.2 or 0, { BackgroundColor3 = active and themeRaise or themePanel, TextColor3 = active and C.Text or C.Faint })
          paint(nav.frames, active and C.Text or C.Faint, animate and 0.2 or 0)
      end
      tween(indicator, animate and 0.35 or 0, { Position = UDim2.fromOffset(navs[name].x, TOP - 4) })
      for n, p in pairs(pages) do p.Visible = n == name end
      if name == "Log" and logsScroll then logsScroll.CanvasPosition = Vector2.new(0, 0) end
      if animate then
          pages[name].Position = UDim2.fromOffset(0, 10)
          tween(pages[name], 0.35, { Position = UDim2.fromOffset(0, 0) })
      end
  end

  for i, def in ipairs({
      { "Main", ICONS.sniper },
      { "Riddle", ICONS.riddle },
      { "Admin abuse helper", ICONS.admin, "Admin" },
      { "Triggers", ICONS.triggers },
      { "Log", ICONS.activity },
      { "Settings", ICONS.settings },
  }) do
      local x = 12 + (i - 1) * 60
      local b, frames = iconButton(x, 55, def[2], def[3] or def[1])
      navs[def[1]] = { button = b, frames = frames, x = x }
      on(b.MouseEnter, function()
          if currentPage ~= def[1] then tween(b, 0.15, { BackgroundColor3 = UI._themeHover or C.Hover, TextColor3 = C.Sub }); paint(frames, C.Sub, 0.15) end
      end)
      on(b.MouseLeave, function()
          if currentPage ~= def[1] then tween(b, 0.2, { BackgroundColor3 = UI._themePanel or C.Panel, TextColor3 = C.Faint }); paint(frames, C.Faint) end
      end)
