  local collapseBtn, collapseFrames = iconButton(W - 42, 55, ICONS.collapse)
  local expandFrames = pixelArt(collapseBtn, ICONS.expand, 2, { ["#"] = C.Faint }, Vector2.new(14, 11), 2)
  for _, f in ipairs(expandFrames) do f.Visible = false end
  hoverColor(collapseBtn, C.Panel, C.Hover)
  local collapsed = false
  on(collapseBtn.Activated, function()
      collapsed = not collapsed
      tween(holder, 0.45, { Size = UDim2.fromOffset(W, collapsed and TOP or H) })
      tween(railFill, 0.2, { BackgroundTransparency = collapsed and 0.35 or 0 })
      pageArea.Visible = not collapsed
      for _, f in ipairs(collapseFrames) do f.Visible = not collapsed end
      for _, f in ipairs(expandFrames) do f.Visible = collapsed end
  end)

  local baseScale, shown = math.clamp(tonumber(settings.windowScale) or 1, 0.5, 1), true
  local showTween
  do
      local dragInput, dragStart, startPos
      local resizeInput, resizeStart, resizeScale
      local function rememberPosition()
          settings.windowX = holder.Position.X.Offset
          settings.windowY = holder.Position.Y.Offset
          saveSettings()
      end
      local function begin(input)
          local kind = input.UserInputType
          if kind ~= Enum.UserInputType.MouseButton1 and kind ~= Enum.UserInputType.Touch then return end
          dragInput, dragStart, startPos = input, input.Position, holder.Position
      end
      on(logoDrag.InputBegan, begin)
      on(topDrag.InputBegan, begin)
      on(UserInputService.InputChanged, function(input)
          if not dragInput then return end
          local tracked = input == dragInput
              or (dragInput.UserInputType == Enum.UserInputType.MouseButton1
                  and input.UserInputType == Enum.UserInputType.MouseMovement)
          if not tracked then return end
          local delta = input.Position - dragStart
          tween(holder, 0.08, {
              Position = UDim2.new(startPos.X.Scale, math.floor(startPos.X.Offset + delta.X), startPos.Y.Scale, math.floor(startPos.Y.Offset + delta.Y)),
          }, Enum.EasingStyle.Sine)
          settings.windowX = holder.Position.X.Offset
          settings.windowY = holder.Position.Y.Offset
      end)
      on(resizeGrip.InputBegan, function(input)
          local kind = input.UserInputType
          if kind ~= Enum.UserInputType.MouseButton1 and kind ~= Enum.UserInputType.Touch then return end
          resizeInput, resizeStart, resizeScale = input, input.Position, baseScale
      end)
      on(UserInputService.InputChanged, function(input)
          if not resizeInput then return end
          local tracked = input == resizeInput
              or (resizeInput.UserInputType == Enum.UserInputType.MouseButton1
                  and input.UserInputType == Enum.UserInputType.MouseMovement)
          if not tracked then return end
          local delta = input.Position - resizeStart
          local nextScale = math.clamp(resizeScale + (delta.X + delta.Y) / 520, 0.5, 1)
          baseScale = nextScale
          settings.windowScale = nextScale
          uiScale.Scale = nextScale
          toastScale.Scale = nextScale
      end)
      on(UserInputService.InputEnded, function(input)
          if dragInput and (input == dragInput or input.UserInputType == Enum.UserInputType.MouseButton1) then
              dragInput = nil
              rememberPosition()
          end
          if resizeInput and (input == resizeInput or input.UserInputType == Enum.UserInputType.MouseButton1) then
              resizeInput = nil
              settings.windowScale = baseScale
              rememberPosition()
          end
      end)
  end

  local function fit()
      local camera = workspace.CurrentCamera
      if not camera then return end
      local viewport = camera.ViewportSize
      local compactTouch = TOUCH_DEVICE and (viewport.X < 720 or viewport.Y < 620)
      local margin = TOUCH_DEVICE and 14 or 8
      local s = math.min(1, (viewport.Y - margin * 2) / H, (viewport.X - margin * 2) / W)
      -- Phones get a compact scale; tablets keep the larger desktop-sized GUI
      -- when there is enough room, even if a hardware keyboard is connected.
      if compactTouch then s = math.min(s, 0.82) end
      local preferred = math.clamp(tonumber(settings.windowScale) or 1, 0.5, 1)
      baseScale = math.max(0.5, math.min(preferred, s))
      toastScale.Scale = baseScale
      if shown then uiScale.Scale = baseScale end
      local width, height = W * baseScale, H * baseScale
      local x = holder.Position.X.Scale * viewport.X + holder.Position.X.Offset
      local y = holder.Position.Y.Scale * viewport.Y + holder.Position.Y.Offset
      local maxX, maxY = math.max(margin, viewport.X - width - margin), math.max(margin, viewport.Y - height - margin)
      holder.Position = UDim2.fromOffset(math.clamp(x, margin, maxX), math.clamp(y, margin, maxY))
  end
  fitWindow = fit
  UI._fitWindow = fit
  local viewportConn
  local function watchCamera()
      if viewportConn then viewportConn:Disconnect() end
      local camera = workspace.CurrentCamera
      if camera then viewportConn = on(camera:GetPropertyChangedSignal("ViewportSize"), fit) end
      fit()
  end
  on(workspace:GetPropertyChangedSignal("CurrentCamera"), watchCamera)
  watchCamera()

  local function setShown(value)
      shown = value
      UI._shown = value
      assistant.onMenu(value)
      if showTween then pcall(function() showTween:Cancel() end) end
      if value then
          holder.Visible = true
          uiScale.Scale = baseScale * 0.92
          showTween = tween(uiScale, 0.24, { Scale = baseScale }, Enum.EasingStyle.Back)
      else
          showTween = tween(uiScale, 0.18, { Scale = baseScale * 0.92 }, Enum.EasingStyle.Quint, Enum.EasingDirection.In)
          task.delay(0.18, function()
              if not shown and holder.Parent then holder.Visible = false end
          end)
      end
  end
  UI._setShown = setShown


