  local RIDDLE_COMPACT_DB
  local RIDDLE_CURRENT_DB
  local RIDDLE_KEYWORD_DB


  local function stripRich(s)
      local plain = tostring(s or "")
      plain = plain:gsub("<%s*[Bb][Rr]%s*/?>", " "):gsub("</%s*[Bb][Rr]%s*>", " ")
      plain = plain:gsub("<[^>]->", "")
      return plain:gsub("&nbsp;", " "):gsub("&quot;", '"'):gsub("&apos;", "'")
          :gsub("&#39;", "'"):gsub("&lt;", "<"):gsub("&gt;", ">")
          :gsub("&amp;", "&")
  end
  local function trim(s)
      return s:match("^%s*(.-)%s*$") or ""
  end
  cleanCode = function(s)
      s = tostring(s or "")
      if #s <= 50 and s:match("^%w+$") then return s end
      return (s:gsub("[^%w]", "")):sub(1, 50)
  end

