  do
  local RIDDLE_NORMALIZE_CACHE = {}
  local RIDDLE_NORMALIZE_CACHE_ORDER = {}
  local RIDDLE_NORMALIZE_CACHE_LIMIT = 1024
  local function rememberRiddleCache(cache, order, limit, key, value)
      if cache[key] ~= nil then
          cache[key] = value
          return
      end
      if #order >= limit then
          local oldest = table.remove(order, 1)
          if oldest ~= nil then cache[oldest] = nil end
      end
      order[#order + 1] = key
      cache[key] = value
  end

  normalizeRiddleQuestion = function(value)
      local raw = tostring(value or "")
      local cached = RIDDLE_NORMALIZE_CACHE[raw]
      if cached ~= nil then return cached end
      local normalized = trim(stripRich(raw)):lower():gsub("%s+", " ")
      normalized = normalized:gsub("'", "")
      normalized = normalized:gsub("[,;]+", " "):gsub("%s+", " ")
      normalized = normalized:gsub("[%s%.%!%?]+$", "")
      normalized = normalized:match("^%s*(.-)%s*$") or ""
      rememberRiddleCache(RIDDLE_NORMALIZE_CACHE, RIDDLE_NORMALIZE_CACHE_ORDER,
          RIDDLE_NORMALIZE_CACHE_LIMIT, raw, normalized)
      return normalized
  end

  sanitizeRiddleAnswer = function(value)
      local original = tostring(value or "")
      local answer = trim(original):gsub("%s+", " "):upper()
      answer = answer:gsub("[%.%!%? ]+$", "")
      if answer == "" then return nil end
      if #answer > 50 then
          log("answer truncated: " .. original, "bad")
          answer = answer:sub(1, 50)
      end
      return answer ~= "" and answer or nil
  end

  local function validRiddleOverrides(value)
      local result = {}
      if type(value) ~= "table" then return result end
      for key, answer in pairs(value) do
          if type(key) == "string" and type(answer) == "string" then
              local normalizedKey = normalizeRiddleQuestion(key)
              local cleanAnswer = sanitizeRiddleAnswer(answer)
              if normalizedKey ~= "" and cleanAnswer then result[normalizedKey] = cleanAnswer end
          end
      end
      return result
  end

  local function buildRiddleDatabase()
      local database = {}
      for _, entry in ipairs(RIDDLE_SOURCE) do
          local key, value = entry[1], entry[2]
          if type(value) == "string" then
              local normalizedKey = normalizeRiddleQuestion(key)
              if normalizedKey ~= "" and database[normalizedKey] == nil then database[normalizedKey] = value end
          end
      end
       for key, value in pairs(RIDDLE_CURRENT_DB or {}) do
           local normalizedKey = normalizeRiddleQuestion(key)
           if normalizedKey ~= "" and type(value) == "string" then database[normalizedKey] = value end
       end
       for key, value in pairs(RIDDLE_KEYWORD_DB or {}) do
           local normalizedKey = normalizeRiddleQuestion(key)
           if normalizedKey ~= "" and type(value) == "string" then database[normalizedKey] = value end
       end
      settings.riddleOverrides = validRiddleOverrides(settings.riddleOverrides)
      for key, value in pairs(settings.riddleOverrides) do database[key] = value end
      return database
  end

  _G.RIDDLER_DB = buildRiddleDatabase()
  RIDDLE_COMPACT_DB = {}
  for _, entry in ipairs(RIDDLE_SOURCE) do
      local question, answer = entry[1], entry[2]
      if type(answer) == "string" then
          local key = normalizeRiddleQuestion(question)
          local compact = key:gsub("[^%w]", "")
          if compact ~= "" and RIDDLE_COMPACT_DB[compact] == nil then
              RIDDLE_COMPACT_DB[compact] = _G.RIDDLER_DB[key] or answer
          end
      end
  end
   for question, answer in pairs(RIDDLE_CURRENT_DB or {}) do
       local key = normalizeRiddleQuestion(question)
       local compact = key:gsub("[^%w]", "")
       if compact ~= "" and type(answer) == "string" then RIDDLE_COMPACT_DB[compact] = answer end
   end
   for question, answer in pairs(RIDDLE_KEYWORD_DB or {}) do
       local key = normalizeRiddleQuestion(question)
       local compact = key:gsub("[^%w]", "")
       if compact ~= "" and type(answer) == "string" then RIDDLE_COMPACT_DB[compact] = answer end
   end
  for key, answer in pairs(settings.riddleOverrides) do
      local compact = key:gsub("[^%w]", "")
      if compact ~= "" then RIDDLE_COMPACT_DB[compact] = answer end
  end
  table.clear(RIDDLE_NORMALIZE_CACHE)
  table.clear(RIDDLE_NORMALIZE_CACHE_ORDER)
  local RIDDLE_FILLER = {
      a = true, an = true, ["and"] = true, about = true, are = true, be = true,
      can = true, could = true, did = true, ["do"] = true, does = true, ["for"] = true,
      how = true, i = true, ["in"] = true, is = true, it = true, many = true,
      me = true, my = true, of = true, on = true, ["or"] = true, please = true,
      tell = true, the = true, to = true, was = true, were = true, what = true,
      whats = true, when = true, where = true, who = true, why = true,
      would = true, should = true,
  }

  local function riddleToken(value)
      local token = tostring(value or ""):lower()
      if #token > 6 and token:sub(-3) == "ing" then
          token = token:sub(1, -4)
      elseif #token > 4 and token:sub(-2) == "ed" then
          token = token:sub(1, -3)
      elseif #token > 5 and token:sub(-1) == "s" then
          token = token:sub(1, -2)
      end
      if #token > 6 and token:sub(-1) == "e" then token = token:sub(1, -2) end
      return token
  end

  local RIDDLE_TOKEN_CACHE = {}
  local RIDDLE_TOKEN_CACHE_ORDER = {}
  local RIDDLE_TOKEN_CACHE_LIMIT = 512
  local function riddleTokens(value)
      local key = normalizeRiddleQuestion(value)
      local cached = RIDDLE_TOKEN_CACHE[key]
      if cached ~= nil then return cached end
      local result = {}
      for token in key:gmatch("[%w]+") do
          result[#result + 1] = riddleToken(token)
      end
      rememberRiddleCache(RIDDLE_TOKEN_CACHE, RIDDLE_TOKEN_CACHE_ORDER,
          RIDDLE_TOKEN_CACHE_LIMIT, key, result)
      return result
  end

  local function meaningfulRiddleTokens(tokens)
      local result = {}
      for _, token in ipairs(tokens) do
          if token ~= "" and not RIDDLE_FILLER[token] then result[#result + 1] = token end
      end
      return result
  end

  local RIDDLE_WEEKDAYS = { "SUNDAY", "MONDAY", "TUESDAY", "WEDNESDAY", "THURSDAY", "FRIDAY", "SATURDAY" }
  local RIDDLE_MONTHS = { "JANUARY", "FEBRUARY", "MARCH", "APRIL", "MAY", "JUNE", "JULY", "AUGUST", "SEPTEMBER", "OCTOBER", "NOVEMBER", "DECEMBER" }
  local function dynamicRiddleAnswer(key)
      local now
      local ok = pcall(function() now = os.date("*t") end)
      if not ok or type(now) ~= "table" then return nil end
      local lower = normalizeRiddleQuestion(key)
      local month = RIDDLE_MONTHS[tonumber(now.month) or 0] or ""
      local weekday = RIDDLE_WEEKDAYS[tonumber(now.wday) or 0] or ""
      local day = tonumber(now.day) or 0
      local year = tonumber(now.year) or 0
      if lower:find("time", 1, true) then
          return string.format("%02d%02d", tonumber(now.hour) or 0, tonumber(now.min) or 0)
      end
      if lower:find("day of the month", 1, true) or lower:find("day of month", 1, true) then
          return tostring(day)
      end
      if lower:find("date", 1, true) or lower == "what is today" then
          return month .. tostring(day) .. tostring(year)
      end
      if lower:find("day of the week", 1, true)
          or lower:find("what day is it", 1, true)
          or lower:find("what day is today", 1, true)
          or lower:find("what is the day today", 1, true)
          or lower:find("what is the current day", 1, true)
          or lower:find("current day of the week", 1, true) then
          return weekday
      end
      if lower:find("month", 1, true) then return month end
      if lower:find("year", 1, true) then return tostring(year) end
      if lower:find("season", 1, true) then
          local monthNumber = tonumber(now.month) or 1
          if monthNumber == 12 or monthNumber <= 2 then return "WINTER" end
          if monthNumber <= 5 then return "SPRING" end
          if monthNumber <= 8 then return "SUMMER" end
          return "AUTUMN"
      end
      return nil
  end

  local function materializeRiddleAnswer(answer, key)
      if answer == "DYNAMIC" then return dynamicRiddleAnswer(key) or answer end
      return answer
  end

   local function dynamicCurrentFactAnswer(key)
       local lower = normalizeRiddleQuestion(key)
       -- Do not collapse a multi-part riddle into one current fact.
       if lower:find(" and ", 1, true) then return nil end
       local recent = lower:find("newest", 1, true)
           or lower:find("latest", 1, true)
           or lower:find("most recent", 1, true)
           or lower:find("current", 1, true)
           or lower:find("last", 1, true)
       if not recent then return nil end
       if lower:find("mutation", 1, true) then return "HACKER" end
       if lower:find("update", 1, true) then return "SEVENTYSEVEN" end
       if lower:find("machine", 1, true) then return "BROSMACHINE" end
       if lower:find("event", 1, true) then return "CHRISTMAS" end
       return nil
   end

  local function normalizeRiddleAnswerForQuestion(answer, question)
      local clean = sanitizeRiddleAnswer(answer)
      if not clean then return nil end
      local lower = normalizeRiddleQuestion(question)
      local asksMonth = lower:find("month", 1, true) ~= nil
      local asksYear = lower:find("year", 1, true) ~= nil
      local asksDate = lower:find("date", 1, true) ~= nil
      local asksDay = lower:find("day", 1, true) ~= nil
      if asksMonth and not asksYear and not asksDate and not asksDay then
          for _, month in ipairs(RIDDLE_MONTHS) do
              if clean:find(month, 1, true) then return month end
          end
      end
      if asksMonth and asksYear then
          local month = clean:match("JANUARY") or clean:match("FEBRUARY") or clean:match("MARCH")
              or clean:match("APRIL") or clean:match("MAY") or clean:match("JUNE")
              or clean:match("JULY") or clean:match("AUGUST") or clean:match("SEPTEMBER")
              or clean:match("OCTOBER") or clean:match("NOVEMBER") or clean:match("DECEMBER")
          local year = clean:match("20%d%d") or clean:match("19%d%d")
          if month and year then return month .. year end
      end
      if asksDate then return (clean:gsub("[^%w]", "")) end
      if asksYear and not asksMonth and not asksDate then
          local year = clean:match("20%d%d") or clean:match("19%d%d")
          if year then return year end
      end
      if lower:find("day of the week", 1, true) then
          for _, weekday in ipairs(RIDDLE_WEEKDAYS) do
              if clean:find(weekday, 1, true) then return weekday end
          end
      end
      return clean
  end

   local function keywordLookup(candidate, question, includeLegacy)
       candidate = normalizeRiddleQuestion(candidate)
       local answer = RIDDLE_KEYWORD_DB[candidate]
       if not answer and includeLegacy then answer = _G.RIDDLER_DB[candidate] end
       if type(answer) ~= "string" then return nil end
       answer = materializeRiddleAnswer(answer, candidate)
       return normalizeRiddleAnswerForQuestion(answer, question), candidate
   end

   local function resolveKeywordRiddleAnswer(question)
       local key = normalizeRiddleQuestion(question)
       local directAnswer, directKey = keywordLookup(key, key, false)
       if directAnswer then return directAnswer, directKey end
        local kind, subject = key:match("^(exist)%s+(.+)$")
        if not kind then kind, subject = key:match("^(exists)%s+(.+)$") end
       if not kind then kind, subject = key:match("^(rarity)%s+(.+)$") end
       if not kind then kind, subject = key:match("^(income)%s+(.+)$") end
       if not kind then kind, subject = key:match("^(recipe)%s+(.+)$") end
       if kind and subject then
           subject = subject:gsub("^the%s+", "")
           local candidates
           if kind == "exist" then
               candidates = {
                   "how many " .. subject .. " exist",
                   "how many " .. subject .. " exists",
                   "how many exists does " .. subject .. " have",
               }
           elseif kind == "rarity" then
               candidates = {
                   "what rarity is " .. subject,
                   "what is " .. subject .. " rarity",
               }
           elseif kind == "income" then
               candidates = {
                   "what is " .. subject .. " income",
                   "how much does " .. subject .. " make",
                   "what is the income of " .. subject,
               }
           else
               candidates = { "recipe " .. subject, "what recipe does " .. subject .. " use" }
           end
           for _, candidate in ipairs(candidates) do
               local answer, matchedKey = keywordLookup(candidate, key, true)
               if answer then return answer, matchedKey end
           end
       end
       return nil, nil
   end

  local RIDDLE_COMPONENTS = {}
  for key, answer in pairs(_G.RIDDLER_DB) do
      if type(answer) == "string" and answer ~= "" then
          local tokens = riddleTokens(key)
          if #tokens > 0 then
              RIDDLE_COMPONENTS[#RIDDLE_COMPONENTS + 1] = {
                  key = key,
                  answer = answer,
                  tokens = tokens,
                  meaningful = meaningfulRiddleTokens(tokens),
              }
          end
      end
  end
  local function riddleComponentSort(a, b)
      if #a.tokens ~= #b.tokens then return #a.tokens > #b.tokens end
      return a.key < b.key
  end
  table.sort(RIDDLE_COMPONENTS, riddleComponentSort)

  -- Hot-path indexes. The old resolver walked every DB component for every
  -- token. These buckets keep exact matching on the first token and loose /
  -- fuzzy matching on meaningful tokens only.
  local RIDDLE_COMPONENT_BY_KEY = {}
  local RIDDLE_EXACT_INDEX = {}
  local RIDDLE_TOKEN_INDEX = {}
  local function addRiddleIndex(index, token, entry)
      if type(token) ~= "string" or token == "" then return end
      local bucket = index[token]
      if not bucket then bucket = {}; index[token] = bucket end
      bucket[#bucket + 1] = entry
  end
  for _, entry in ipairs(RIDDLE_COMPONENTS) do
      RIDDLE_COMPONENT_BY_KEY[entry.key] = entry
      addRiddleIndex(RIDDLE_EXACT_INDEX, entry.tokens[1], entry)
      local seenTokens = {}
      for _, token in ipairs(entry.meaningful) do
          if not seenTokens[token] then
              seenTokens[token] = true
              addRiddleIndex(RIDDLE_TOKEN_INDEX, token, entry)
          end
      end
  end
  -- The build phase touches many DB keys. Start the runtime token cache clean
  -- so its small bounded budget is reserved for live announcement questions.
  table.clear(RIDDLE_TOKEN_CACHE)
  table.clear(RIDDLE_TOKEN_CACHE_ORDER)

  local function addOrUpdateRiddleComponent(key, answer)
      key = normalizeRiddleQuestion(key)
      if key == "" or type(answer) ~= "string" or answer == "" then return end
      local existing = RIDDLE_COMPONENT_BY_KEY[key]
      if existing then
          existing.answer = answer
          return
      end
      local tokens = riddleTokens(key)
      if #tokens == 0 then return end
      local entry = {
          key = key,
          answer = answer,
          tokens = tokens,
          meaningful = meaningfulRiddleTokens(tokens),
      }
      RIDDLE_COMPONENTS[#RIDDLE_COMPONENTS + 1] = entry
      RIDDLE_COMPONENT_BY_KEY[key] = entry
      addRiddleIndex(RIDDLE_EXACT_INDEX, tokens[1], entry)
      local seenTokens = {}
      for _, token in ipairs(entry.meaningful) do
          if not seenTokens[token] then
              seenTokens[token] = true
              addRiddleIndex(RIDDLE_TOKEN_INDEX, token, entry)
          end
      end
      table.sort(RIDDLE_EXACT_INDEX[tokens[1]], riddleComponentSort)
      for token in pairs(seenTokens) do table.sort(RIDDLE_TOKEN_INDEX[token], riddleComponentSort) end
  end

  local function componentAt(tokens, index)
      local bucket = RIDDLE_EXACT_INDEX[tokens[index]]
      if not bucket then return nil end
      for _, entry in ipairs(bucket) do
          if index + #entry.tokens - 1 <= #tokens then
              local matches = true
              for offset, token in ipairs(entry.tokens) do
                  if tokens[index + offset - 1] ~= token then matches = false; break end
              end
              if matches then return entry end
          end
      end
      return nil
  end

  local function componentAtLoose(tokens, index)
      -- Natural announcements rarely use the exact wording stored in the DB:
      -- "what month was SAB released" should still resolve the DB entry
      -- "when was SAB released". Match the meaningful words in order, while
      -- allowing filler words such as what, was, my, and the to sit between.
      local best, bestEnd, bestScore = nil, nil, -math.huge
      local windowEnd = math.min(#tokens, index + 11)
      local candidateSet, candidates = {}, {}
      for position = index, windowEnd do
          local bucket = RIDDLE_TOKEN_INDEX[tokens[position]]
          for _, entry in ipairs(bucket or {}) do
              if not candidateSet[entry] then
                  candidateSet[entry] = true
                  candidates[#candidates + 1] = entry
              end
          end
      end
      for _, entry in ipairs(candidates) do
          if #entry.meaningful >= 2 then
              local cursor, firstMatch, lastMatch = index, nil, nil
              local matched = true
              for _, wanted in ipairs(entry.meaningful) do
                  local found
                  for position = cursor, windowEnd do
                      if tokens[position] == wanted then
                          found = position
                          break
                      end
                  end
                  if not found then
                      matched = false
                      break
                  end
                  firstMatch = firstMatch or found
                  lastMatch = found
                  cursor = found + 1
              end
              if matched and firstMatch and lastMatch then
                  local distance = firstMatch - index
                  local span = lastMatch - firstMatch + 1
                  local score = #entry.meaningful * 100 - distance * 8 - span * 0.5
                      + math.min(#entry.tokens, 12) * 0.01
                  if score > bestScore then
                      best, bestEnd, bestScore = entry, lastMatch, score
                  end
              end
          end
      end
      return best, bestEnd
  end

  -- Resolve a sentence as an ordered list of DB phrases. This deliberately
  -- does not use a hard-coded name/age/cat order: the announcement order is
  -- the answer order.
  local function resolveCompositeRiddleAnswer(key)
      local tokens = riddleTokens(key)
      local values, matched, semanticMatched = {}, 0, 0
      local index = 1
      while index <= #tokens do
          local entry = componentAt(tokens, index)
          local entryEnd
          if not entry then
              entry, entryEnd = componentAtLoose(tokens, index)
          else
              entryEnd = index + #entry.tokens - 1
          end
          if entry then
              local componentQuestion = table.concat(tokens, " ", index, entryEnd)
              local componentAnswer = materializeRiddleAnswer(entry.answer, entry.key)
              componentAnswer = normalizeRiddleAnswerForQuestion(componentAnswer, componentQuestion)
              if componentAnswer then values[#values + 1] = componentAnswer end
              matched += 1
              semanticMatched += 1
              index = entryEnd + 1
          elseif tostring(tokens[index]):match("^%d+$") then
              -- Standalone numeric parts are valid riddle components, but are
              -- only allowed to form a composite when another DB component is
              -- present. This keeps arithmetic questions such as 12 + 12 on
              -- their normal exact-answer path.
              values[#values + 1] = tokens[index]
              matched += 1
              index += 1
          else
              index += 1
          end
      end
      if matched >= 2 and semanticMatched >= 1 and #values >= 2 then
          return table.concat(values)
      end
      return nil
  end

  local function riddleLooksComposite(key)
      if type(resolveCompositeRiddleAnswer(key)) == "string" then return true end
      local tokens = riddleTokens(key)
      local matched, hasNumber, hasAnd = 0, false, false
      local index = 1
      while index <= #tokens do
          if tokens[index] == "and" then hasAnd = true end
          local entry = componentAt(tokens, index)
          local entryEnd
          if not entry then
              entry, entryEnd = componentAtLoose(tokens, index)
          else
              entryEnd = index + #entry.tokens - 1
          end
          if entry then
              matched += 1
              index = entryEnd + 1
          else
              hasNumber = hasNumber or tostring(tokens[index]):match("^%d+$") ~= nil
              index += 1
          end
      end
      return matched >= 2 or (matched >= 1 and (hasNumber or hasAnd))
  end

  local function resolveFuzzyRiddleAnswer(key)
      local query = meaningfulRiddleTokens(riddleTokens(key))
      if #query == 0 then return nil end
      local querySet = {}
      for _, token in ipairs(query) do querySet[token] = true end
      local best, bestScore, bestOverlap = nil, -math.huge, 0
      local candidateSet, candidates = {}, {}
      for _, token in ipairs(query) do
          for _, entry in ipairs(RIDDLE_TOKEN_INDEX[token] or {}) do
              if not candidateSet[entry] then
                  candidateSet[entry] = true
                  candidates[#candidates + 1] = entry
              end
          end
      end
      for _, entry in ipairs(candidates) do
          local overlapSet, overlap = {}, 0
          for _, token in ipairs(entry.meaningful) do
              if querySet[token] and not overlapSet[token] then
                  overlapSet[token] = true
                  overlap += 1
              end
          end
          local required = #query > 1 and 2 or 1
          if overlap >= required then
              local coverage = overlap / math.max(1, #entry.meaningful)
              local score = overlap * 100 + coverage * 20 + math.min(#entry.tokens, 12) * 0.01
              if score > bestScore or (score == bestScore and overlap > bestOverlap) then
                  best, bestScore, bestOverlap = entry, score, overlap
              end
          end
      end
      return best and best.answer or nil, best and best.key or nil
  end
  local function riddleCandidates(text)
      local key = normalizeRiddleQuestion(text)
      local candidates, seenCandidates = {}, {}
      local function add(candidate)
          candidate = trim(candidate or "")
          if candidate ~= "" and not seenCandidates[candidate] then
              seenCandidates[candidate] = true
              candidates[#candidates + 1] = candidate
          end
      end
      add(key)
      for _, prefix in ipairs({ "riddle:", "riddle is:", "riddle is", "the riddle is:", "the riddle is", "question:", "question is" }) do
          if key:sub(1, #prefix) == prefix then add(key:sub(#prefix + 1)) end
      end
      return candidates
  end
  local RIDDLE_RESOLVE_CACHE = {}
  local RIDDLE_RESOLVE_CACHE_ORDER = {}
  local RIDDLE_RESOLVE_CACHE_LIMIT = 256
  local function rememberRiddleResult(key, result)
      if key == "" or RIDDLE_RESOLVE_CACHE[key] then
          if key ~= "" then RIDDLE_RESOLVE_CACHE[key] = result end
          return
      end
      if #RIDDLE_RESOLVE_CACHE_ORDER >= RIDDLE_RESOLVE_CACHE_LIMIT then
          local oldest = table.remove(RIDDLE_RESOLVE_CACHE_ORDER, 1)
          if oldest then RIDDLE_RESOLVE_CACHE[oldest] = nil end
      end
      RIDDLE_RESOLVE_CACHE_ORDER[#RIDDLE_RESOLVE_CACHE_ORDER + 1] = key
      RIDDLE_RESOLVE_CACHE[key] = result
  end
  resolveRiddleAnswer = function(text)
      local cacheKey = normalizeRiddleQuestion(text)
      local cached = cacheKey ~= "" and RIDDLE_RESOLVE_CACHE[cacheKey] or nil
      if cached then
          return cached.answer ~= false and cached.answer or nil, cached.key, cached.attempts, cached.composite
      end
      local function finish(answer, key, attempts, composite)
          rememberRiddleResult(cacheKey, {
              answer = answer or false,
              key = key,
              attempts = attempts,
              composite = composite == true,
          })
          return answer, key, attempts, composite
      end
      local candidates = riddleCandidates(text)
      for _, key in ipairs(candidates) do
           local keywordAnswer, keywordKey = resolveKeywordRiddleAnswer(key)
           if keywordAnswer then return finish(keywordAnswer, keywordKey or key, 0, false) end
           local currentAnswer = dynamicCurrentFactAnswer(key)
           if currentAnswer then return finish(currentAnswer, key, 0, false) end
          -- Prefer ordered component assembly over a stored sentence-level
          -- answer. This keeps multi-part riddles DB-driven instead of making
          -- one question depend on one hard-coded composite entry.
          local compositeAnswer = resolveCompositeRiddleAnswer(key)
          if type(compositeAnswer) == "string" then return finish(compositeAnswer, key, 1, true) end
          local firstAnswer = _G.RIDDLER_DB[key]
           if type(firstAnswer) == "string" then return finish(materializeRiddleAnswer(firstAnswer, key), key, 2, false) end
          local compactKey = key:gsub("[^%w]", "")
          local secondAnswer = compactKey ~= "" and RIDDLE_COMPACT_DB[compactKey] or nil
           if type(secondAnswer) == "string" then return finish(materializeRiddleAnswer(secondAnswer, key), key, 3, false) end
           local fuzzyAnswer, fuzzyKey = resolveFuzzyRiddleAnswer(key)
           if type(fuzzyAnswer) == "string" then return finish(materializeRiddleAnswer(fuzzyAnswer, fuzzyKey or key), fuzzyKey or key, 4, false) end
      end
      return finish(nil, candidates[1] or "", #candidates, false)
  end
  local function riddleRequestFunction()
      local direct = (syn and syn.request) or rawget(env, "request") or rawget(env, "http_request")
          or rawget(env, "httprequest") or rawget(env, "fluxus_request") or rawget(env, "krnl_request")
          or rawget(_G, "request") or rawget(_G, "http_request")
      if type(direct) == "function" then return direct end
      local httpGlobal = rawget(env, "http") or rawget(_G, "http")
      if type(httpGlobal) == "table" and type(httpGlobal.request) == "function" then
          return function(options) return httpGlobal.request(options) end
      end
      if HttpService and type(HttpService.RequestAsync) == "function" then
          return function(options)
              return HttpService:RequestAsync(options)
          end
      end
      return nil
  end
  local function riddleApiAnswer(decoded)
      if type(decoded) ~= "table" then return nil end
      local raw = decoded.answer or decoded.response or decoded.text or decoded.content
      if not raw and type(decoded.choices) == "table" and decoded.choices[1] then
          local choice = decoded.choices[1]
          raw = type(choice.message) == "table" and choice.message.content or choice.text
      end
      if not raw and type(decoded.candidates) == "table" and decoded.candidates[1] then
          local parts = decoded.candidates[1].content and decoded.candidates[1].content.parts
          if type(parts) == "table" then
              local pieces = {}
              for _, part in ipairs(parts) do
                  if type(part) == "table" and type(part.text) == "string" and part.thought ~= true then
                      pieces[#pieces + 1] = part.text
                  end
              end
              raw = table.concat(pieces, " ")
          end
      end
      if type(raw) == "table" then raw = raw.text or raw.content or raw.answer end
      if type(raw) ~= "string" then return nil end
      raw = raw:gsub("```json", ""):gsub("```", "")
      local structuredOk, structured = pcall(function() return ConfigHttp:JSONDecode(trim(raw)) end)
      if structuredOk and type(structured) == "table" then
          raw = structured.answer or structured.finalAnswer or structured.result or structured.text or raw
      end
      if type(raw) == "table" then raw = raw.text or raw.answer or raw.content end
      if type(raw) ~= "string" then return nil end
      raw = tostring(raw):gsub("^%s*[Aa]nswer%s*:%s*", "")
      raw = raw:gsub("^%s*[%-%*]%s*", ""):gsub("^%s*[\"'](.-)[\"']%s*$", "%1")
      local answer = sanitizeRiddleAnswer(raw)
      return answer and answer:gsub("%s+", "") or nil
  end

  local function apiErrorDetail(body)
      local raw = tostring(body or "")
      local ok, decoded = pcall(function() return ConfigHttp:JSONDecode(raw) end)
      if ok and type(decoded) == "table" then
          local errorValue = decoded.error
          if type(errorValue) == "table" then
              local message = errorValue.message or errorValue.status or errorValue.code
              if message then return tostring(message):sub(1, 180) end
          elseif type(errorValue) == "string" then
              return errorValue:sub(1, 180)
          end
      end
      raw = raw:gsub("%s+", " "):match("^%s*(.-)%s*$") or ""
      return raw:sub(1, 180)
  end
  solveRiddleWithApi = function(question, force)
      if not settings.riddleSolver and not force then return nil, "disabled" end
      local key = trim(tostring(settings.riddleApiKey or ""))
      local url = trim(tostring(settings.riddleApiUrl or ""))
      local model = trim(tostring(settings.riddleApiModel or ""))
      if key == "" then return nil, "API key missing" end
      if url == "" then return nil, "API endpoint missing" end
       local requestFn = riddleRequestFunction()
       if type(requestFn) ~= "function" then return nil, "HTTP request unavailable" end
       local isGemini = url:lower():find("generativelanguage.googleapis.com", 1, true) ~= nil
       local instruction = "Solve the riddle from the local game database. If the question asks for several facts, resolve each clause separately and concatenate the answers in announcement order. Return only the final answer, with no explanation. Match the requested precision exactly: if the question asks for a month, return only the month name; do not append a year or date."
       local modelCandidates = {}
       local function addModel(candidate)
           candidate = trim(tostring(candidate or "")):gsub("^models/", ""):gsub(":generateContent$", "")
           if candidate == "" then return end
           for _, existing in ipairs(modelCandidates) do
               if existing == candidate then return end
           end
           modelCandidates[#modelCandidates + 1] = candidate
       end
       if isGemini then
           -- Keep the configured model first, then recover automatically when a
           -- stale model name returns 404 or a temporary service error occurs.
           addModel(model)
           addModel("gemini-3.8-flash")
           addModel("gemini-flash-lite-latest")
           addModel("gemini-2.5-flash")
       else
           addModel(model ~= "" and model or "gpt-4o-mini")
       end

       local lastError = nil
       for _, selectedModel in ipairs(modelCandidates) do
           local requestUrl = url
           local requestHeaders = { ["Content-Type"] = "application/json" }
           local payloadTable
           if isGemini then
               if not requestUrl:find(":generateContent", 1, true) then
                   requestUrl = requestUrl:gsub("/+$", "")
                   if requestUrl:match("/models$") then
                       requestUrl = requestUrl .. "/" .. selectedModel
                   elseif not requestUrl:find("/models/", 1, true) then
                       requestUrl = requestUrl .. "/models/" .. selectedModel
                   end
                   requestUrl = requestUrl .. ":generateContent"
               else
                   requestUrl = requestUrl:gsub("/models/[^/]+:generateContent$", "/models/" .. selectedModel .. ":generateContent")
               end
               requestHeaders["x-goog-api-key"] = key
               payloadTable = {
                   systemInstruction = { parts = {{ text = instruction }} },
                   contents = {{ role = "user", parts = {{ text = tostring(question or "") }} }},
                   generationConfig = { temperature = 0, maxOutputTokens = 20 },
               }
           else
               payloadTable = {
                   model = selectedModel,
                   temperature = 0,
                   max_tokens = 20,
                   messages = {
                       { role = "system", content = instruction },
                       { role = "user", content = tostring(question or "") },
                   },
               }
               requestHeaders.Authorization = "Bearer " .. key
           end
           local ok, response = pcall(requestFn, {
               Url = requestUrl,
               Method = "POST",
               Headers = requestHeaders,
               Body = ConfigHttp:JSONEncode(payloadTable),
           })
           if not ok then return nil, "HTTP request failed: " .. tostring(response):sub(1, 140) end
           if type(response) ~= "table" then return nil, "HTTP request returned no response" end
           local status = tonumber(response.StatusCode or response.Status or 200) or 200
           local body = response.Body or response.body
           if status >= 200 and status < 300 then
               local decodedOk, decoded = pcall(function() return ConfigHttp:JSONDecode(tostring(body or "")) end)
               if not decodedOk then return nil, "Gemini returned invalid JSON" end
               local answer = riddleApiAnswer(decoded)
               answer = riddleLooksComposite(question) and answer or normalizeRiddleAnswerForQuestion(answer, question)
               if answer then return answer, "api · " .. selectedModel end
               return nil, "API returned no answer"
           end
           local detail = apiErrorDetail(body)
           lastError = "Gemini HTTP " .. tostring(status) .. (detail ~= "" and (" · " .. detail) or "")
           local retryable = status == 404 or status == 408 or status == 429 or status >= 500
           if not retryable then return nil, lastError end
       end
       return nil, lastError or "Gemini request failed"
  end
  UI._riddleApiSolve = solveRiddleWithApi
  UI._riddleResolve = resolveRiddleAnswer
  UI._riddleIsComposite = riddleLooksComposite
  UI._riddleNormalize = normalizeRiddleAnswerForQuestion
  UI._riddleStats = function()
      local total, overrides = 0, 0
      for _ in pairs(_G.RIDDLER_DB or {}) do total += 1 end
      for _ in pairs(settings.riddleOverrides or {}) do overrides += 1 end
      return total, overrides
  end
  UI._riddleAdd = function(question, answer)
      local key = normalizeRiddleQuestion(question)
      local clean = sanitizeRiddleAnswer(answer)
      if key == "" then return false, "Question required" end
      if not clean then return false, "Answer required" end
      settings.riddleOverrides[key] = clean
      _G.RIDDLER_DB[key] = clean
      addOrUpdateRiddleComponent(key, clean)
      table.clear(RIDDLE_RESOLVE_CACHE)
      table.clear(RIDDLE_RESOLVE_CACHE_ORDER)
      local compact = key:gsub("[^%w]", "")
      if compact ~= "" then RIDDLE_COMPACT_DB[compact] = clean end
      writeConfig()
      saveSettings()
      log("Riddle override saved: " .. key, "good")
      return true, key
  end
  if UI._riddlePageRefresh then UI._riddlePageRefresh() end
  -- Option B: no manual brainrot list was supplied for this pass.
  local manualBrainrots = {}
  _G.RIDDLER_BRAINROTS = manualBrainrots
  if #manualBrainrots == 0 then
      log("RIDDLER_BRAINROTS empty — condition B of the trigger riddle disabled", "sys")
  end
  UI._riddlePrefixes = table.clone(RIDDLE_PREFIXES)
  UI._riddleBrainrots = table.clone(manualBrainrots)
  end

  local SPAM_GAP = 0.02
  do
  local codeUI
  local function controllerSource(fn)
      local source = ""
      if type(fn) ~= "function" then return source end
      pcall(function()
          if type(debug) == "table" and type(debug.info) == "function" then
              source = tostring(debug.info(fn, "s") or "")
          elseif type(getinfo) == "function" then
              local info = getinfo(fn)
              source = tostring(info and (info.short_src or info.source) or "")
          end
      end)
      return source:lower()
  end
  local function getFunctionUpvalues(fn)
      if type(fn) ~= "function" then return nil end
      local getValues = rawget(env, "getupvalues") or rawget(_G, "getupvalues")
      if not getValues and type(debug) == "table" and type(debug.getupvalues) == "function" then
          getValues = debug.getupvalues
      end
      if type(getValues) ~= "function" then return nil end
      local ok, values = pcall(getValues, fn)
      return ok and type(values) == "table" and values or nil
  end
  local function findControllerSubmitFromSignal(signal)
      -- CodesController is wired behind the animated `Confirm.Activated`
      -- signal in the live game. Resolve that exact route first; searching a
      -- nested TextButton alone can find a visual proxy with no submit logic.
      if not signal or type(getconnections) ~= "function" then return nil, nil end
      local ok, connections = pcall(getconnections, signal)
      if not ok or type(connections) ~= "table" then return nil, nil end
      local seenNodes = {}
      local function walk(animated)
          if type(animated) ~= "table" then return nil end
          local node = animated.OnActivated and animated.OnActivated._handlerListHead
          while node do
              if not seenNodes[node] then
                  seenNodes[node] = true
                  local fn = node._fn
                  if type(fn) == "function" and controllerSource(fn):find("codescontroller", 1, true) then
                      return fn, animated
                  end
              end
              node = node._next
          end
          return nil
      end
      for _, connection in ipairs(connections) do
          local fn = connection and connection.Function
          local values = getFunctionUpvalues(fn)
          -- The reference route uses the first captured animated signal.
          local submit, animated = walk(values and values[1])
          if submit then return submit, animated end
          -- A few revisions capture the animated signal deeper in the
          -- closure. Inspect tables without replacing the exact fast path.
          if values then
              for _, value in pairs(values) do
                  if type(value) == "table" then
                      submit, animated = walk(value)
                      if submit then return submit, animated end
                  end
              end
          end
      end
      return nil, nil
  end
  local function findControllerSubmit(btn)
      if not btn or type(getconnections) ~= "function" then return nil end
      local getValues = rawget(env, "getupvalues") or rawget(_G, "getupvalues")
      if not getValues and type(debug) == "table" and type(debug.getupvalues) == "function" then getValues = debug.getupvalues end
      local seenFunctions, seenTables = {}, {}
      local function fromHandler(fn)
          if type(fn) ~= "function" then return nil end
          if seenFunctions[fn] then return nil end
          seenFunctions[fn] = true
          if controllerSource(fn):find("codescontroller", 1, true) then return fn end
          if type(getValues) ~= "function" then return nil end
          local ok, values = pcall(getValues, fn)
          if not ok or type(values) ~= "table" then return nil end
          for _, value in pairs(values) do
              if type(value) == "table" and not seenTables[value] then
                  seenTables[value] = true
                  local animated = value.OnActivated or value
                  local node = type(animated) == "table" and animated._handlerListHead or nil
                  while node do
                      local nested = fromHandler(node._fn)
                      if nested then return nested end
                      node = node._next
                  end
              end
          end
          return nil
      end
      local ok, connections = pcall(getconnections, btn.Activated)
      if not ok then return nil end
      for _, connection in ipairs(connections or {}) do
          local submit = fromHandler(connection.Function)
          if submit then return submit end
      end
      return nil
  end
  local capabilityWarnings = {}
  local function guiLabel(obj)
      local label = tostring(obj and obj.Name or "")
      pcall(function() label = label .. " " .. tostring(obj.Text or "") end)
      return label:lower()
  end
  local function codeBoxScore(box)
      local name = tostring(box.Name or ""):lower()
      local placeholder = ""
      local fullName = ""
      pcall(function() placeholder = tostring(box.PlaceholderText or ""):lower() end)
      pcall(function() fullName = box:GetFullName():lower() end)
      local parentName = box.Parent and tostring(box.Parent.Name or ""):lower() or ""
      local score = 0
      if parentName == "coderedeem" then score += 140 end
      if name == "codebox" or name == "codeinput" or name == "code" then score += 90 end
      if name:find("code", 1, true) or name:find("redeem", 1, true) then score += 45 end
      if name:find("input", 1, true) or name:find("promo", 1, true) then score += 22 end
      if parentName:find("code", 1, true) or parentName:find("redeem", 1, true) then score += 36 end
      if placeholder:find("code", 1, true) or placeholder:find("redeem", 1, true) then score += 45 end
      if fullName:find("codes", 1, true) then score += 35 end
      if box.Visible then score += 4 end
      return score
  end
  local function codeButtonScore(btn, box)
      if not btn or not btn.Parent then return -math.huge end
      local name = tostring(btn.Name or ""):lower()
      local label = guiLabel(btn)
      local score = 0
      if name == "confirm" then score += 160 end
      if name:find("redeem", 1, true) or label:find("redeem", 1, true) then score += 110 end
      if name:find("submit", 1, true) or label:find("submit", 1, true) then score += 105 end
      if name:find("confirm", 1, true) or label:find("confirm", 1, true) then score += 85 end
      if name:find("claim", 1, true) or label:find("claim", 1, true) then score += 35 end
      if name:find("enter", 1, true) or label:find("enter", 1, true) then score += 20 end
      if btn.Parent == box.Parent then score += 70 end
      if btn.Visible then score += 4 end
      return score
  end
  local function warnCapability(key, message)
      if capabilityWarnings[key] then return end
      capabilityWarnings[key] = true
      log(message, "sys")
  end

  local function resolveCodeUI()
      if codeUI and codeUI.box and codeUI.box.Parent and (not codeUI.btn or codeUI.btn.Parent) then
          pcall(function()
              if codeUI.codesGui and codeUI.codesGui:IsA("ScreenGui") and not codeUI.codesGui.Enabled then
                  codeUI.openedStates.codesEnabled = false
                  codeUI.codesGui.Enabled = true
              end
              for _, parent in ipairs(codeUI.ancestors or {}) do
                  if parent:IsA("GuiObject") and not parent.Visible then
                      codeUI.openedStates.ancestors[parent] = false
                      parent.Visible = true
                  end
              end
               if not codeUI.submit then
                   local signal
                   pcall(function() signal = codeUI.confirm and codeUI.confirm.Activated end)
                   codeUI.submit, codeUI.animated = findControllerSubmitFromSignal(signal)
                   if not codeUI.submit and codeUI.btn then
                       codeUI.submit = findControllerSubmit(codeUI.btn)
                   end
              end
          end)
          return codeUI
      end
      codeUI = nil
      pcall(function()
           local containers = {}
           local pg = player:FindFirstChildOfClass("PlayerGui")
           if pg then containers[#containers + 1] = pg end
           pcall(function()
               local uiRoot = type(gethui) == "function" and gethui() or game:GetService("CoreGui")
               if uiRoot and uiRoot ~= pg then containers[#containers + 1] = uiRoot end
           end)
           local codesGui
           for _, container in ipairs(containers) do
               local candidate = container:FindFirstChild("Codes")
               if candidate then
                   codesGui = candidate
                   break
               end
               for _, descendant in ipairs(container:GetDescendants()) do
                   if descendant.Name == "Codes" and (descendant:IsA("ScreenGui") or descendant:IsA("GuiObject")) then
                       codesGui = descendant
                       break
                   end
               end
               if codesGui then break end
           end
           -- A few game revisions mount the same screen under a renamed
           -- container. Use the textbox path as a safe secondary resolver so
           -- a missing top-level `Codes` name does not kill the submit route.
           if not codesGui then
               local fallbackBox
               for _, container in ipairs(containers) do
                   for _, candidate in ipairs(container:GetDescendants()) do
                       if candidate:IsA("TextBox") then
                           local parentName = candidate.Parent and candidate.Parent.Name:lower() or ""
                           local fullName = candidate:GetFullName():lower()
                           local label = (candidate.Name .. " " .. tostring(candidate.PlaceholderText or "")):lower()
                           if parentName == "coderedeem"
                               or (fullName:find("code", 1, true) and (fullName:find("redeem", 1, true) or label:find("code", 1, true))) then
                               fallbackBox = candidate
                               break
                           end
                       end
                   end
                   if fallbackBox then break end
               end
               if fallbackBox then
                   codesGui = fallbackBox:FindFirstAncestorOfClass("ScreenGui") or fallbackBox.Parent
               end
           end
           if not codesGui then return end
          local openedStates = { codesEnabled = nil, ancestors = {} }
          pcall(function()
              if codesGui:IsA("ScreenGui") and not codesGui.Enabled then
                  openedStates.codesEnabled = false
                  codesGui.Enabled = true
              end
          end)
           local root = codesGui:FindFirstChild("Codes") or codesGui
          local ancestors = {}
          local parent = root
          while parent do
              if parent:IsA("GuiObject") then
                  ancestors[#ancestors + 1] = parent
                  pcall(function()
                      if not parent.Visible then
                          openedStates.ancestors[parent] = false
                          parent.Visible = true
                      end
                  end)
              end
              parent = parent.Parent
              if parent == codesGui then break end
          end
           local box, boxScore = nil, -math.huge
            -- Canonical path used by the game and by the reference script.
            -- Prefer it over a similarly named textbox from another panel.
            pcall(function()
                local codeRedeem = root:FindFirstChild("CodeRedeem")
                local canonical = codeRedeem and codeRedeem:FindFirstChild("TextBox")
                if canonical and canonical:IsA("TextBox") then
                    box, boxScore = canonical, 1000
                end
            end)
           for _, candidate in ipairs(root:GetDescendants()) do
               if candidate:IsA("TextBox") then
                   local score = codeBoxScore(candidate)
                   if score > boxScore then box, boxScore = candidate, score end
               end
           end
           if not box then
               for _, container in ipairs(containers) do
                   for _, candidate in ipairs(container:GetDescendants()) do
                       if candidate:IsA("TextBox") then
                           local parentName = candidate.Parent and candidate.Parent.Name:lower() or ""
                           local label = (candidate.Name .. " " .. tostring(candidate.PlaceholderText or "")):lower()
                           if parentName == "coderedeem" or label:find("code", 1, true) or label:find("redeem", 1, true) then
                               box = candidate
                               break
                           end
                       end
                   end
                   if box then break end
               end
           end
          if not box then return end
           local btn, buttonScore = nil, -math.huge
           for _, candidate in ipairs(root:GetDescendants()) do
               if candidate:IsA("GuiButton") then
                   local score = codeButtonScore(candidate, box)
                   if score > buttonScore then btn, buttonScore = candidate, score end
               end
           end
           if buttonScore < 35 then btn = nil end
           local confirm = root:FindFirstChild("Confirm")
           local animatedSubmit, animated
           pcall(function()
               animatedSubmit, animated = findControllerSubmitFromSignal(confirm and confirm.Activated)
           end)
           local notifier
          pcall(function()
              local controllers = ReplicatedStorage:FindFirstChild("Controllers")
              local module = controllers and controllers:FindFirstChild("NotificationController", true)
              if module and module:IsA("ModuleScript") then
                  local ok, value = pcall(require, module)
                  if ok and type(value) == "table" then notifier = value end
              end
          end)
           codeUI = {
                box = box, btn = btn, confirm = confirm,
                submit = animatedSubmit or findControllerSubmit(btn), animated = animated,
                codesGui = codesGui, ancestors = ancestors,
                openedStates = openedStates, notifier = notifier,
           }
      end)
      return codeUI
  end
  resolveUI = resolveCodeUI
  UI._resolveCodeUI = resolveUI

  local function restoreCodeUI()
      if not codeUI then return end
      pcall(function()
          for parent, value in pairs(codeUI.openedStates and codeUI.openedStates.ancestors or {}) do
              if parent and parent.Parent then parent.Visible = value end
          end
          if codeUI.openedStates and codeUI.openedStates.codesEnabled ~= nil
              and codeUI.codesGui and codeUI.codesGui.Parent then
              codeUI.codesGui.Enabled = codeUI.openedStates.codesEnabled
          end
      end)
      codeUI = nil
  end
  cleanups[#cleanups + 1] = restoreCodeUI

  local fireButton
  local submitRouteLock = false
  local function fireFocusLost(box)
      if not box then return false end
      local fired = false
      local ok, list = pcall(getconnections, box.FocusLost)
      if ok then
          for _, c in ipairs(list or {}) do
              pcall(function()
                  local fn = c.Function
                  if type(fn) == "function" and debug then
                      if type(debug.getupvalues) == "function" then
                          for i, value in pairs(debug.getupvalues(fn) or {}) do
                              if type(value) == "boolean" and type(debug.setupvalue) == "function" then debug.setupvalue(fn, i, false) end
                          end
                      elseif type(debug.getupvalue) == "function" then
                          for i = 1, 64 do
                              local name, value = debug.getupvalue(fn, i)
                              if not name then break end
                              if type(value) == "boolean" and type(debug.setupvalue) == "function" then debug.setupvalue(fn, i, false) end
                          end
                      end
                  end
                   if c.Enabled ~= false and type(c.Fire) == "function" then c:Fire(true) fired = true end
              end)
          end
      end
      if not fired and typeof(firesignal) == "function" then
          fired = pcall(firesignal, box.FocusLost, true)
      end
      if not fired then fired = pcall(function() box:ReleaseFocus(true) end) end
      return fired
  end

  submitFast = function(code, alreadyClean)
      if submitRouteLock then return false end
      submitRouteLock = true
      local ui = resolveUI()
      if not ui or not ui.box then submitRouteLock = false; return false end
      code = alreadyClean and tostring(code or "") or cleanCode(code)
      for _ = 1, 8 do
          local ok = pcall(function()
              ui.box.Active = true
              ui.box.Selectable = true
              ui.box:CaptureFocus()
              ui.box.Text = code
          end)
          if ok and ui.box.Text == code then break end
          task.wait(0.03)
      end
      local textOk, currentText = pcall(function() return ui.box.Text end)
      if not textOk or currentText ~= code then submitRouteLock = false; return false end
      if settings.dryRun then
          log("READY TO SUBMIT: " .. code, "sys", true)
          submitRouteLock = false
          return true
      end
      local result = false
      if type(ui.submit) == "function" then
          local controllerOk = pcall(ui.submit)
          result = controllerOk
      end
      if not result then
          local clicked = fireButton(ui.btn)
          pcall(function() result = clicked or fireFocusLost(ui.box) end)
      end
      if result and settings.spamSubmit then
          -- The first route is submit #1. Two short repeats make three total.
          log("Spam submit x3: " .. code, "sys")
          for _ = 1, 2 do
              task.wait(SPAM_GAP)
              pcall(function()
                   ui.box.Active = true
                   ui.box.Selectable = true
                  ui.box:CaptureFocus()
                  ui.box.Text = code
              end)
              pcall(function()
                   if type(ui.submit) == "function" then
                      ui.submit()
                  else
                      local fired = fireButton(ui.btn) or fireFocusLost(ui.box)
                  end
              end)
          end
      end
      submitRouteLock = false
      return result
  end

  fireButton = function(btn)
      if not btn or not btn.Parent then return false end
      local function fireOne(signal)
          if not signal then return false end
          local fired = false
          local ok, list = pcall(getconnections, signal)
          if ok then
               for _, c in ipairs(list or {}) do
                   if c.Enabled ~= false and type(c.Fire) == "function" and pcall(c.Fire, c) then fired = true end
              end
          end
          if fired then return true end
          if typeof(firesignal) == "function" then return pcall(firesignal, signal) end
          return false
      end
      local activated = false
      pcall(function() activated = fireOne(btn.Activated) end)
      if activated then return true end
      local clicked = false
      pcall(function() clicked = fireOne(btn.MouseButton1Click) end)
      if clicked then return true end
      -- Some executors expose neither getconnections nor firesignal. Activate
      -- is the normal Roblox route and is still single-shot here.
      local ok = pcall(function() btn:Activate() end)
      return ok
  end
  end

  local pendingResult
  local notificationCheck
  local hookedNotifier
  local spawnBatchCount = 0
  local spawnBatchNames = {}
  local spawnBatchToken = 0
  local function aggregateSpawn(name)
      name = trim(tostring(name or "Spawn"))
      if name == "" then name = "Spawn" end
      spawnBatchCount += 1
      spawnBatchNames[name] = (spawnBatchNames[name] or 0) + 1
      spawnBatchToken += 1
      local token = spawnBatchToken
      if spawnBatchCount == 1 then toast("Spawned", name, false, "good") end
      task.delay(10, function()
          if token ~= spawnBatchToken or spawnBatchCount <= 0 then return end
          local labels = {}
          for label, count in pairs(spawnBatchNames) do labels[#labels + 1] = count > 1 and (label .. " x" .. count) or label end
          table.sort(labels)
          if spawnBatchCount > 1 then toast("+" .. tostring(spawnBatchCount) .. " brainrot spawn", table.concat(labels, ", "):sub(1, 90), false, "good") end
          spawnBatchCount, spawnBatchNames = 0, {}
      end)
  end
  cleanups[#cleanups + 1] = function()
      spawnBatchToken += 1
      spawnBatchCount, spawnBatchNames = 0, {}
  end
  local function hookNotifier(notifier)
      if not notifier or hookedNotifier == notifier then return end
      local success, failure = notifier.Success, notifier.Error
      notifier.Success = function(self, message, ...)
          if notificationCheck then pcall(notificationCheck, { Text = message, Parent = true }) end
          if type(success) == "function" then return success(self, message, ...) end
      end
      notifier.Error = function(self, message, ...)
          if notificationCheck then pcall(notificationCheck, { Text = message, Parent = true }) end
          if type(failure) == "function" then return failure(self, message, ...) end
      end
      hookedNotifier = notifier
      cleanups[#cleanups + 1] = function()
          pcall(function() notifier.Success, notifier.Error = success, failure end)
          if hookedNotifier == notifier then hookedNotifier = nil end
      end
  end

  do
      local BAD = { "invalid", "not valid", "incorrect", "wrong", "not found", "already", "expired", "sold out", "out of stock", "no longer" }
      local GOOD = { "redeemed", "success", "claimed", "spawned", "you got", "received" }
      local function check(label)
          local request = pendingResult
          if not label then return end
          local real = typeof(label) == "Instance"
          if real and not label.Parent then return end
          local text = tostring(label.Text or ""):gsub("<[^>]->", "")
          local lower = text:lower()
          if lower == "" then return end
          local bad, good = false, false
          for _, w in ipairs(BAD) do if lower:find(w, 1, true) then bad = true break end end
          if not bad then
              for _, w in ipairs(GOOD) do if lower:find(w, 1, true) then good = true break end end
          end
          if not bad and not good then return end
          -- always show the toast so it's visible even when there's no pending redeem
          if good then
              -- check if it's a spawn notification or a redeem confirmation
              local spawnedName = text:match("^[Aa]n? (.+) has been spawned")
                  or text:match("^[Aa]n? (.+) has spawned")
                  or text:match("^(.+) has been spawned")
                  or text:match("^(.+) has spawned")
                  or text:match("^[Ss]pawned[!%s]+(.+)$")
                  or text:match("^(.+) spawned")
              if spawnedName then
                  spawnedName = spawnedName:gsub("[!%.%?]+$", ""):match("^%s*(.-)%s*$")
                  aggregateSpawn(spawnedName)
                  if not lower:find("redeem", 1, true) and not lower:find("claim", 1, true)
                      and not lower:find("code", 1, true) then
                      return
                  end
              elseif lower:find("redeem", 1, true) or lower:find("success", 1, true) or lower:find("claimed", 1, true) or lower:find("you got", 1, true) or lower:find("received", 1, true) then
                  toast("Redeemed", text, true, "good")
              else
                  toast("Spawned", text, false, "good")
              end
          else
              toast("Failed", text, false, "warn")
          end
          if not request or type(request.resolve) ~= "function" then return end
          task.spawn(request.resolve, good, text)
      end
      notificationCheck = check
      local watchedLabels = {}
      local function watchLabel(label)
          if not label or not label:IsA("TextLabel") or watchedLabels[label] then return end
          watchedLabels[label] = true
          on(label:GetPropertyChangedSignal("Text"), function()
              if not destroyed then check(label) end
          end)
          if tostring(label.Text or "") ~= "" then task.defer(check, label) end
      end
      local function attachNotification(root)
          if destroyed or not root then return end
          if root:IsA("TextLabel") then watchLabel(root) end
          for _, d in ipairs(root:GetDescendants()) do
              watchLabel(d)
          end
          on(root.DescendantAdded, function(d)
              if destroyed then return end
              watchLabel(d)
              for _, child in ipairs(d:GetDescendants()) do watchLabel(child) end
          end)
      end
      task.spawn(function()
          if destroyed then return end
          local pg = player:FindFirstChildOfClass("PlayerGui")
          local popup = pg and (pg:FindFirstChild("Notification") or pg:WaitForChild("Notification", 30))
          if destroyed then return end
          attachNotification(popup)
          local top = pg and (pg:FindFirstChild("TopNotification") or pg:WaitForChild("TopNotification", 30))
          if destroyed then return end
          local inner = top and (top:FindFirstChild("TopNotification") or top:WaitForChild("TopNotification", 30))
          local template = inner and (inner:FindFirstChild("Template") or inner:WaitForChild("Template", 30))
          if destroyed then return end
      attachNotification(template or top)
      end)
  end

  local awaitingReward = 0

  local typing = false
  local redeemRemote = nil
  local redeemRemoteIsFunction = false
  local nextRedeemProbe = 0

  local function probeRedeemRemote()
      if redeemRemote and redeemRemote.Parent then return redeemRemote end
      redeemRemote, redeemRemoteIsFunction = nil, false
      local now = os.clock()
      if now < nextRedeemProbe then return nil end
      nextRedeemProbe = now + 0.5
      pcall(function()
          local net = ReplicatedStorage:FindFirstChild("Packages")
          net = net and net:FindFirstChild("Net")
          local candidates = {
              { "MerchShop", "RedeemCode" },
              { "ModdedStockService", "Redeem" },
              { "StockEventService", "Redeem" },
          }
          for _, pair in ipairs(candidates) do
              local service = net and net:FindFirstChild(pair[1])
              local remote = service and service:FindFirstChild(pair[2])
              if remote and (remote:IsA("RemoteEvent") or remote:IsA("RemoteFunction")) then
                  redeemRemote = remote
                  redeemRemoteIsFunction = remote:IsA("RemoteFunction")
                  break
              end
          end
      end)
      return redeemRemote
  end
  task.defer(function()
      pcall(probeRedeemRemote)
  end)

  typeIntoBox = function(code, alreadyClean)
      code = alreadyClean and tostring(code or "") or cleanCode(code)
      local ui = resolveUI()
      if not ui then log("Code box not found", "bad") return nil end
      pcall(function() ui.box.Text = code end)
      return ui.box.Parent and ui or nil
  end

  local collectionSource = "trigger"

  local function copyFinalCode(code)
      task.defer(function()
          local copy = setclipboard or toclipboard or (syn and syn.write_clipboard)
          if type(copy) == "function" then pcall(copy, code) end
      end)
  end

  local function clearCodeBox()
      pcall(function()
          local ui = resolveUI()
          if ui and ui.box then ui.box.Text = "" end
      end)
  end

  local lastRedeemAt = {}
  local inFlightRedeems = {}
  local pendingRequests = {}
  local BUFFER_THROTTLE = 0.08
  local IN_FLIGHT_TTL = 1.5
  local RESULT_TIMEOUT = 2
  local requestId = 0
  local serverCooldownUntil = 0
  local lastCooldownNotice = 0

  local function isServerRateLimited(message)
      local lower = tostring(message or ""):lower()
      return lower:find("rate limit", 1, true) ~= nil
          or lower:find("too fast", 1, true) ~= nil
          or lower:find("slow down", 1, true) ~= nil
          or lower:find("cooldown", 1, true) ~= nil
          or lower:find("brute force", 1, true) ~= nil
          or lower:find("temporary block", 1, true) ~= nil
          or lower:find("please wait", 1, true) ~= nil
  end

  local function registerServerRateLimit(message)
      local now = os.clock()
      local seconds = tonumber(tostring(message or ""):lower():match("(%d+%.?%d*)%s*seconds?"))
      seconds = math.clamp(seconds or 2.5, 1.5, 8)
      serverCooldownUntil = math.max(serverCooldownUntil, now + seconds)
      if now - lastCooldownNotice >= 1 then
          lastCooldownNotice = now
          log("Server cooldown detected; pausing new submits", "warn")
      end
  end

  local function isInvalidResult(message)
      local lower = tostring(message or ""):lower()
      return lower:find("invalid", 1, true) ~= nil
          or lower:find("not valid", 1, true) ~= nil
          or lower:find("incorrect", 1, true) ~= nil
          or lower:find("wrong", 1, true) ~= nil
          or lower:find("not found", 1, true) ~= nil
          or lower:find("doesn't exist", 1, true) ~= nil
          or lower:find("does not exist", 1, true) ~= nil
          or lower:find("not available", 1, true) ~= nil
          or lower:find("no longer valid", 1, true) ~= nil
          or lower:find("expired", 1, true) ~= nil
          or lower:find("sold out", 1, true) ~= nil
          or lower:find("already", 1, true) ~= nil
  end

  local function isSuccessResult(message)
      local lower = tostring(message or ""):lower()
      return lower:find("redeem", 1, true) ~= nil
          or lower:find("success", 1, true) ~= nil
          or lower:find("claimed", 1, true) ~= nil
          or lower:find("received", 1, true) ~= nil
          or lower:find("spawned", 1, true) ~= nil
  end

  local function remoteOutcome(value)
      if value == nil then return nil, nil end
      if type(value) == "boolean" then return value, value and "remote accepted" or "remote rejected" end
      if type(value) == "string" then
          if isServerRateLimited(value) then return false, value end
          if isInvalidResult(value) then return false, value end
          if isSuccessResult(value) then return true, value end
          return nil, nil
      end
      if type(value) == "table" then
          local okValue = value.Success
          if okValue == nil then okValue = value.success end
          if okValue == nil then okValue = value.Ok end
          if okValue == nil then okValue = value.ok end
          local message = value.Message or value.message or value.Status or value.status or value.Result or value.result
          if type(okValue) == "boolean" then return okValue, tostring(message or (okValue and "remote accepted" or "remote rejected")) end
          if message ~= nil then return remoteOutcome(tostring(message)) end
      end
      return nil, nil
  end

  local function nextPendingRequest()
      local best
      for _, request in pairs(pendingRequests) do
          if not request.finished and (not best or request.id > best.id) then best = request end
      end
      return best
  end

  local function clearPendingRequest(request)
      if request then pendingRequests[request.id] = nil end
      if pendingResult == request then pendingResult = nextPendingRequest() end
  end

  redeem = function(raw, preCleaned, onOutcome, _isRetry, meta)
      meta = type(meta) == "table" and meta or {}
      if UI._redeemGuard and not UI._redeemGuard(meta) then
          if onOutcome then task.spawn(onOutcome, false, "backoff") end
          return false
      end
      local cooldownRemaining = serverCooldownUntil - os.clock()
      if cooldownRemaining > 0 then
          local message = "server cooldown (" .. string.format("%.1fs", cooldownRemaining) .. ")"
          if onOutcome then task.spawn(onOutcome, false, message) end
          return false
      end
      -- The original pipeline always normalizes the assembled announcement
      -- parts before submission. Keeping spaces here makes the game reject a
      -- perfectly valid multi-part code and also breaks retry deduplication.
      local code = cleanCode(raw)
      local validPattern = "^[A-Za-z0-9]+$"
      if code == "" or #code > 50 or not code:match(validPattern) then
          if onOutcome then task.spawn(onOutcome, false, "Malformed code") end
          if UI._redeemOutcome then task.spawn(UI._redeemOutcome, code, false, "Malformed code", meta, 0) end
          return false
      end
      local startedAt = os.clock()
      local now = startedAt
      local dedupKey = code:upper()
      if now < (lastRedeemAt[dedupKey] or 0) or inFlightRedeems[dedupKey] then
          if onOutcome then task.spawn(onOutcome, false, "deduplicated") end
          return false
      end
      local throttle = UI._redeemThrottle and UI._redeemThrottle(meta) or BUFFER_THROTTLE
      lastRedeemAt[dedupKey] = now + math.max(BUFFER_THROTTLE, throttle or BUFFER_THROTTLE)
      inFlightRedeems[dedupKey] = true
      requestId += 1
      local request = { id = requestId, code = code, meta = meta, startedAt = startedAt, finished = false, released = false }
      meta.request = request
      pendingRequests[request.id] = request
      pendingResult = request

      local function release()
          if request.released then return end
          request.released = true
          if inFlightRedeems[dedupKey] then inFlightRedeems[dedupKey] = nil end
      end
      task.delay(IN_FLIGHT_TTL, release)

      local function finish(ok, message)
          if request.finished then return end
          request.finished = true
          clearPendingRequest(request)
          release()
          local resultText = tostring(message or (ok and "success" or "failed"))
          local latency = math.floor((os.clock() - startedAt) * 1000 + 0.5)
          if UI._redeemOutcome then task.spawn(UI._redeemOutcome, code, ok, resultText, meta, latency) end
          if onOutcome then task.spawn(onOutcome, ok, resultText) end
      end

      request.resolve = function(ok, message)
          if request.finished then return end
           if isServerRateLimited(message) then registerServerRateLimit(message) end
          local invalid = not ok or isInvalidResult(message)
          finish(not invalid, message)
      end

      task.delay(RESULT_TIMEOUT, function()
          if not request.finished then request.resolve(false, "timeout") end
      end)

      awaitingReward = os.clock() + 4
      local ui = resolveUI()
      if ui and ui.notifier then hookNotifier(ui.notifier) end
      -- Prefer the game's actual redeem endpoint when it is available. This is
      -- the fast path used by the reference implementation; the visible Codes
      -- controller remains a complete fallback, not a competing first attempt.
      local remote = redeemRemote or probeRedeemRemote()
      local remoteRouteStarted = false
      if remote and not settings.dryRun then
          local spamCount = settings.spamSubmit and 3 or 1
          if redeemRemoteIsFunction then
              remoteRouteStarted = true
              task.spawn(function()
                  local invoked = false
                  for attempt = 1, spamCount do
                      local ok, result = pcall(function() return remote:InvokeServer(code) end)
                      invoked = invoked or ok
                      if ok then
                          local remoteOk, remoteMessage = remoteOutcome(result)
                          if remoteOk ~= nil then
                              request.resolve(remoteOk, remoteMessage)
                               if request.finished or isServerRateLimited(remoteMessage) or not settings.spamSubmit then break end
                          end
                      end
                      if attempt < spamCount then task.wait(SPAM_GAP) end
                  end
                  if not invoked and not request.finished then
                      local submitOk, uiSubmitted = pcall(submitFast, code, true)
                      if not submitOk or not uiSubmitted then request.resolve(false, "submit failed") end
                  end
              end)
          else
              local fired = false
              for attempt = 1, spamCount do
                  local ok = pcall(function() remote:FireServer(code) end)
                  fired = fired or ok
                  if attempt < spamCount then task.wait(SPAM_GAP) end
              end
              remoteRouteStarted = fired
              if not fired then log("Direct remote failed; using Codes UI", "sys") end
          end
      end
      if not remoteRouteStarted and not settings.dryRun then
          local submitOk, uiSubmitted = pcall(submitFast, code, true)
          if not submitOk or not uiSubmitted then
              log("Code UI submit failed", "bad")
              request.resolve(false, "Code UI submit failed")
              return false
          end
      end
      log("Submitting " .. code, "code")
      if settings.dryRun then request.resolve(true, "READY TO SUBMIT: " .. code) end
      if settings.autoCopy then copyFinalCode(code) end
      assistant.event("redeem", code)
      return true
  end
  UI._riddleRedeem = function(answer)
      local clean = sanitizeRiddleAnswer(answer)
      if not clean then return false, "Invalid answer" end
      typeIntoBox(clean, true)
      local ok = redeem(clean, true, nil, false, { source = "riddle", riddle = true, final = true, preCleaned = true })
      return ok, ok and "Submitted" or "Submit failed"
  end


  local function findWord(hay, needle)
      local init = 1
      while true do
          local s, e = hay:find(needle, init, true)
          if not s then return nil end
          local before = s == 1 or hay:sub(s - 1, s - 1) == " "
          local nextCh = hay:sub(e + 1, e + 1)
          local after = nextCh == "" or nextCh == " " or nextCh == ":" or needle:sub(-1) == ":"
          if before and after then return s, e end
          init = s + 1
      end
  end

  local function matchTrigger(text)
      local loose, map = looseText(text)
      local best, bestS, bestE
      for _, word in ipairs(sortedTriggers) do
          local s, e = findWord(loose, word)
          if s and (not bestS or s < bestS or (s == bestS and e > bestE)) then
              best, bestS, bestE = word, s, e
          end
      end
      if not best then return nil end
      local rest = text:sub(map[bestE] + 1):gsub("…", "...")
      rest = rest:gsub("^[^%w\"'%(]+", "")
      rest = rest:gsub("[%s%.!%?,]+$", "")
      return best, rest
  end

  parts, seen, lastPartAt = {}, {}, 0
  collecting = false
  local activeProbeRequest
  local pendingCandidates = {}
  UI._partsCount = function() return #parts end
  local partLines = {}
  local PART_TIMEOUT = 20
  local collectionGeneration = 0
  retypeListening = false

  local function cancelPendingRedeems()
      for _, request in pairs(pendingRequests) do
          request.finished = true
          request.released = true
      end
      table.clear(pendingRequests)
      table.clear(inFlightRedeems)
      pendingResult = nil
      activeProbeRequest = nil
      table.clear(pendingCandidates)
      queuedFinalCode = nil
  end

  local function startCollecting(source)
      collectionGeneration += 1
      collecting, parts, partLines, lastPartAt = true, {}, {}, os.clock()
      retypeListening = false
      seen = {}
      activeProbeRequest = nil
      table.clear(pendingCandidates)
      queuedFinalCode = nil
      collectionSource = source or "trigger"
      clearCodeBox()
  end
  stopCollecting = function(clearBox)
      collectionGeneration += 1
      collecting, parts, partLines = false, {}, {}
      retypeListening = false
      seen = {}
      activeProbeRequest = nil
      table.clear(pendingCandidates)
      queuedFinalCode = nil
      collectionSource = "trigger"
      if clearBox then clearCodeBox() end
  end

  function UI.cancelTracking()
      if collecting or retypeListening or pendingResult or manualScanArmed then
          stopCollecting(true)
          cancelPendingRedeems()
          manualScanArmed, scanDeadline = false, 0
          table.clear(inFlightRedeems)
          log("Code tracking cancelled", "sys")
          toast("Cancelled", "Code tracking stopped", false, "sys")
      end
  end

  local function renderParts()
      local total = math.max(1, settings.submitAfter)
      for i, p in ipairs(parts) do
          log('<font face="RobotoMono">' .. esc(p) .. "</font>"
              .. "  <font color=\"#" .. colorHex(C.Faint) .. "\">" .. i .. "/" .. total .. "</font>", "info", true)
      end
  end

  local function codeText()
      return table.concat(parts, " ")
  end

  local submitFinal

  local function armRetypeListening()
      retypeListening = true
      rearmDeadline = os.clock() + PART_TIMEOUT
      local deadline = rearmDeadline
      task.delay(PART_TIMEOUT, function()
          if retypeListening and rearmDeadline == deadline then stopCollecting(true) end
      end)
  end

  local function retypeBuffer(reason)
      local combined = codeText()
      collecting = true
      lastPartAt = os.clock()
      clearCodeBox()
      if combined ~= "" then typeIntoBox(combined) end
      armRetypeListening()
      log((reason or "Retyped") .. ": " .. esc(combined), "sys", true)
  end

  local function submitProbe(combined, generation)
      local token = { generation = generation, code = combined, kind = "probe" }
      activeProbeRequest = token
      typeIntoBox(combined)
      redeem(combined, true, function(ok, message)
          if token.generation ~= collectionGeneration or activeProbeRequest ~= token then return end
          activeProbeRequest = nil
          if ok then
              log("2-word probe accepted: " .. combined, "good")
              toast("Redeemed", combined, true, "good")
              stopCollecting(false)
              return
          end
          clearCodeBox()
          typeIntoBox(codeText())
          log("2-word probe rejected (" .. tostring(message or "unknown") .. "); continuing capture", "bad")
          local queued = table.remove(pendingCandidates, 1)
          if queued then
              if queued.kind == "probe" then
                  submitProbe(queued.code, queued.generation)
              else
                  submitFinal(queued.code, queued.generation, queued.retry)
              end
          end
      end, false, { source = collectionSource, probe = true, final = false })
  end

  submitFinal = function(combined, generation, retry)
      local token = { generation = generation, code = combined, kind = "final", retry = retry }
      queuedFinalCode = token
      collecting = false
      typeIntoBox(combined)
      redeem(combined, true, function(ok, message)
          if token.generation ~= collectionGeneration or queuedFinalCode ~= token then return end
          queuedFinalCode = nil
          if ok then
              log("Redeemed " .. combined, "good")
              toast("Redeemed", combined, true, "good")
              stopCollecting(false)
              return
          end
          if settings.retypeInvalid and isInvalidResult(message) and #parts < 5 then
              retypeBuffer("Redeem failed; waiting for part " .. tostring(#parts + 1) .. "/5")
              return
          end
          log("Redeem failed: " .. tostring(message or "unknown"), "bad")
          stopCollecting(true)
      end, false, { source = collectionSource, final = true, retry = retry == true })
  end

  local function capturePart(part)
      part = cleanCode(part)
      if part == "" or not collecting then return end
      if os.clock() - lastPartAt > PART_TIMEOUT then
          log("Code parts timed out", "sys")
          stopCollecting(true)
          return
      end
      if retypeListening then
          -- A rejected code remains in the buffer. The next announcement is
          -- the replacement/extension word and must be allowed even when it
          -- repeats an earlier part.
          retypeListening = false
          local dedupKey = part:upper()
          seen[dedupKey] = nil
          seen[dedupKey] = true
          lastPartAt = os.clock()
          parts[#parts + 1] = part
          local combined = codeText()
          log("Retype attempt (" .. tostring(#parts) .. "/5): " .. esc(combined), "sys", true)
          typeIntoBox(combined)
          if not settings.autoSubmit then
              log("Auto submit disabled; retyped code is ready in the box", "sys")
              return
          end
          submitFinal(combined, collectionGeneration, true)
          return
      end
      if #parts >= 5 then
          log("Maximum 5 code parts reached", "warn")
          return
      end
      local dedupKey = part:upper()
      if seen[dedupKey] then return end
      seen[dedupKey] = true
      lastPartAt = os.clock()
      parts[#parts + 1] = part
      typeIntoBox(codeText())
      renderParts()
      if not settings.autoSubmit then
          log("Auto submit disabled; code is ready in the box", "sys")
          return
      end

      local generation = collectionGeneration
      if #parts >= settings.submitAfter then
          if activeProbeRequest then
              pendingCandidates[#pendingCandidates + 1] = { generation = generation, code = codeText(), kind = "final", retry = retypeListening }
              retypeListening = false
              log("Final submit queued behind 2-word probe", "sys")
              return
          end
          submitFinal(codeText(), generation, retypeListening)
          retypeListening = false
          return
      end
      if settings.twoWordCheck and #parts >= 2 then
          if activeProbeRequest then
              pendingCandidates[#pendingCandidates + 1] = { generation = generation, code = codeText(), kind = "probe", retry = false }
              log("Candidate queued behind 2-word probe: " .. codeText(), "sys")
          else
              submitProbe(codeText(), generation)
          end
          return
      end
      retypeListening = false
      log("Progress: [" .. codeText() .. "] (Remaining: " .. (settings.submitAfter - #parts) .. ")", "sys")
  end

  local seenTTL = {}
  local function once(key, ttl)
      local now = os.clock()
      local last = seenTTL[key]
      ttl = tonumber(ttl) or 0.08
      if last and now - last < ttl then return false end
      seenTTL[key] = now
      return true
  end

  local function feedWords(text)
      local captured = false
      for word in tostring(text or ""):gmatch("[%w]+") do
          local clean = cleanCode(word)
          if clean ~= "" then
              captured = true
              capturePart(clean)
          end
      end
      return captured
  end

  local function splitRiddlePrefix(text)
      local rawText = stripRich(tostring(text or ""))
      local lower = rawText:lower()
      for _, prefix in ipairs(RIDDLE_PREFIXES) do
          if lower:sub(1, #prefix) == prefix then
              local nextChar = lower:sub(#prefix + 1, #prefix + 1)
              if nextChar == "" or nextChar:match("[%s%p]") then
                  local rest = trim(rawText:sub(#prefix + 1)):gsub("^[:%-]+", "")
                  return prefix, trim(rest)
              end
          end
      end
      return nil, ""
  end

  local function startsWithRiddlePrefix(text)
      local prefix, rest = splitRiddlePrefix(text)
      return prefix ~= nil and rest ~= ""
  end

  local function isRiddleAnnouncement(text)
      if startsWithRiddlePrefix(text) then return true end
      local lower = text:lower()
      local componentMarkers = {
          "my name", "my age", "age of sammy", "sammy age", "my cat name", "my cats name",
          "name of my cat", "name of his cat", "name of sammys cat", "favorite number",
          "favourite number", "fav number", "sab release", "sab released", "what month was sab",
          "what month did sab come out",
      }
      local componentCount = 0
      for _, marker in ipairs(componentMarkers) do
          if lower:find(marker, 1, true) then componentCount += 1 end
      end
      if componentCount >= 2 then
          return true
      end
      if not text:find("?", 1, true) then return false end
      for _, brainrot in ipairs(_G.RIDDLER_BRAINROTS or {}) do
          if lower:find(brainrot, 1, true) then return true end
      end
      local first = lower:match("^%s*(%a+)")
      return first ~= nil and ({
          what = true, who = true, how = true, where = true,
          when = true, why = true, can = true, ["do"] = true,
          does = true, ["is"] = true,
      })[first] == true
  end

  -- Some servers announce a code as a short phrase with no "code is"
  -- prefix. Keep this deliberately conservative: number words/digits provide
  -- strong code evidence, while common sentence words block false positives.
  local STANDALONE_CODE_NUMBER_WORDS = {
      zero = true, one = true, two = true, three = true, four = true,
      five = true, six = true, seven = true, eight = true, nine = true,
      ten = true,
  }
  local STANDALONE_CODE_HINTS = {
      code = true, stuff = true, gift = true,
      reward = true, redeem = true, secret = true, claim = true,
  }
  local STANDALONE_CODE_BLOCKERS = {
      a = true, an = true, the = true, my = true, your = true,
      this = true, that = true, is = true, are = true, was = true,
      were = true, have = true, has = true, with = true, from = true,
      i = true, you = true, we = true, he = true, she = true, they = true,
      give = true, get = true, want = true, need = true, go = true,
      join = true, play = true, just = true, ["not"] = true,
      server = true, event = true, update = true, starting = true,
      started = true, congratulations = true, coming = true, soon = true,
  }
  local function detectStandaloneCode(text)
      local raw = trim(stripRich(text))
      if raw == "" or #raw > 80 or raw:find("[,:;!?]", 1) then return nil end
      local words, compactParts = {}, {}
      for word in raw:gmatch("[%w]+") do
          words[#words + 1] = word
          compactParts[#compactParts + 1] = cleanCode(word)
      end
      if #words == 0 or #words > 5 then return nil end
      local hasDigit, numberWordCount, hasHint = false, 0, false
      for index, word in ipairs(words) do
          local lower = word:lower()
          if STANDALONE_CODE_BLOCKERS[lower] then return nil end
          if STANDALONE_CODE_NUMBER_WORDS[lower] then numberWordCount += 1 end
          if lower:find("%d") then hasDigit = true end
          if STANDALONE_CODE_HINTS[lower] then hasHint = true end
          if compactParts[index] == "" then return nil end
      end
      local allNumberWords = numberWordCount == #words and #words >= 2
      local digitBacked = hasDigit and (#words == 1 or hasHint or numberWordCount >= 1)
      local strongPattern = digitBacked
          or (hasHint and numberWordCount >= 1)
          or allNumberWords
      if not strongPattern then return nil end
      if #words == 1 and not hasDigit then return nil end
      local candidate = table.concat(compactParts)
      if #candidate < 4 or #candidate > 50 then return nil end
      return candidate
  end

  local riddleRequestToken = 0
  local function handleRiddleAnnouncement(text)
      riddleAwaiting = false
      riddleCaptureDeadline = 0
      riddleCaptureId += 1
      riddleQuestionToken += 1
      riddleQuestionParts = {}
      stopCollecting(true)
      if not settings.armed then return true end
      riddleRequestToken += 1
      local requestToken = riddleRequestToken
      local rawAnswer, key, attempts, isComposite = resolveRiddleAnswer(text)
      local function submitAnswer(answer, source)
          if requestToken ~= riddleRequestToken then return end
          if isComposite then
              answer = sanitizeRiddleAnswer(answer)
          else
              answer = type(UI._riddleNormalize) == "function" and UI._riddleNormalize(answer, text) or sanitizeRiddleAnswer(answer)
          end
          if not answer then
              log("unknown riddle: " .. key, "bad")
              return
          end
          typeIntoBox(answer, true)
          redeem(answer, true, function(ok, message)
              if ok then
                  log("Riddle redeemed: " .. tostring(source or key), "good")
              else
                  log("Riddle failed: " .. tostring(message or "unknown"), "bad")
              end
              stopCollecting(true)
          end, false, { source = "riddle", riddle = true, final = true, preCleaned = true })
      end
      -- The local database is authoritative. When it has an answer, submit it
      -- immediately and let Gemini validate in parallel without ever replacing
      -- the ordered DB result. Gemini only submits when the DB has no answer.
      local apiReady = settings.riddleSolver and trim(tostring(settings.riddleApiKey or "")) ~= ""
      if type(rawAnswer) == "string" then
          if apiReady then
              task.spawn(function()
                  local apiAnswer = solveRiddleWithApi(text, true)
                  if requestToken ~= riddleRequestToken or type(apiAnswer) ~= "string" then return end
                  local localClean = isComposite and sanitizeRiddleAnswer(rawAnswer)
                      or normalizeRiddleAnswerForQuestion(rawAnswer, text)
                  if apiAnswer == localClean then
                      log("Gemini validation matched local DB · answer kept", "ai")
                  else
                      log("Gemini validation differed · local DB answer kept", "sys")
                  end
              end)
          end
          submitAnswer(rawAnswer, key .. " · local DB")
      elseif settings.riddleSolver then
          task.spawn(function()
              local apiAnswer, apiMessage = solveRiddleWithApi(text, true)
              if requestToken ~= riddleRequestToken then return end
              if apiAnswer then
                  submitAnswer(apiAnswer, key .. " · Gemini")
              else
                  log("unknown riddle after " .. tostring(attempts) .. " attempts: " .. key .. " · " .. tostring(apiMessage or "API failed"), "bad")
              end
          end)
      else
          log("unknown riddle after " .. tostring(attempts) .. " attempts: " .. key, "bad")
      end
      return true
  end

  local function isRiddleContinuation(text)
      local lower = trim(stripRich(text)):lower()
      if lower == "" then return false end
      for _, marker in ipairs({
          "good luck", "congratulations", "gg", "spawned", "event starting",
          "server luck", "stock remaining", "next code", "redeem now",
      }) do
          if lower:sub(1, #marker) == marker then return false end
      end
      return true
  end

  local function queueRiddleQuestionPart(text)
      if not riddleAwaiting then return false end
      if os.clock() >= riddleCaptureDeadline then
          riddleAwaiting = false
          riddleQuestionParts = {}
          log("Riddle question capture expired", "sys")
          return false
      end
      local part = trim(stripRich(text))
      if part == "" or not isRiddleContinuation(part) then return false end
      if #riddleQuestionParts >= 128 then
          riddleAwaiting = false
          riddleQuestionParts = {}
          log("Riddle question was too long", "bad")
          return true
      end
      local joined = table.concat(riddleQuestionParts, " ")
      if #joined + #part + 1 > 16384 then
          riddleAwaiting = false
          riddleQuestionParts = {}
          log("Riddle question exceeded the capture limit", "bad")
          return true
      end
      riddleQuestionParts[#riddleQuestionParts + 1] = part
      riddleWaitStamp = os.clock()
      riddleQuestionToken += 1
      local token = riddleQuestionToken
      local settleDelay = part:find("%?%s*$") and 0.3 or 1.2
      task.delay(settleDelay, function()
          if destroyed or not riddleAwaiting or token ~= riddleQuestionToken then return end
          local combined = table.concat(riddleQuestionParts, " ")
          riddleAwaiting = false
          riddleCaptureDeadline = 0
          riddleCaptureId += 1
          riddleQuestionParts = {}
          handleRiddleAnnouncement(combined)
      end)
      return true
  end

  local function beginRiddleQuestionCapture(seed)
      riddleAwaiting = true
      riddleWaitStamp = os.clock()
      riddleCaptureDeadline = riddleWaitStamp + 60
      riddleCaptureId += 1
      local captureId = riddleCaptureId
      riddleQuestionToken += 1
      riddleQuestionParts = {}
      if seed and trim(tostring(seed)) ~= "" then
          queueRiddleQuestionPart(seed)
      end
      task.delay(60, function()
          if not destroyed and riddleAwaiting and riddleCaptureId == captureId and os.clock() >= riddleCaptureDeadline then
              riddleAwaiting = false
              riddleCaptureDeadline = 0
              riddleQuestionToken += 1
              riddleQuestionParts = {}
              log("Riddle trigger expired without a complete question", "sys")
          end
      end)
  end

  UI.cmdr = function(command)
      local raw = trim(tostring(command or ""))
      local payload = raw:match("^[Rr][Ii][Dd][Dd][Ll][Ee]:[Aa][Dd][Dd]%s+(.+)$")
      if payload then
          local separator = payload:find("=", 1, true)
          if not separator then return false, "usage: riddle:add <key>=<answer>" end
          local key = normalizeRiddleQuestion(payload:sub(1, separator - 1))
          local answer = sanitizeRiddleAnswer(payload:sub(separator + 1))
          if key == "" or not answer then return false, "riddle key and answer are required" end
          settings.riddleOverrides[key] = answer
          _G.RIDDLER_DB[key] = answer
          addOrUpdateRiddleComponent(key, answer)
          table.clear(RIDDLE_RESOLVE_CACHE)
          table.clear(RIDDLE_RESOLVE_CACHE_ORDER)
          pcall(writeConfig)
          saveSettings()
          log("riddle answer added: " .. key, "good")
          return true, answer
      end
      return false, "unknown CMDR command"
  end

  onAnnouncement = function(message)
      if message == nil then return end
      local raw = type(message) == "table" and (message.Text or message.Message or message.Body or message[1]) or message
      local text = trim(stripRich(raw))
      if text == "" or not once("message:" .. text:lower(), 0.08) then return end

      -- Manual Scan gets first refusal. A scanned announcement is content even
      -- when it happens to contain one of the configured trigger phrases.
      if manualScanArmed then
          manualScanArmed, scanDeadline = false, 0
          startCollecting("manual")
          feedWords(text)
          toast("Scan", "Captured manually", false, "good")
          return
      end

      if riddleScanArmed and settings.armed then
          riddleScanArmed = false
          local riddlePrefix, riddleBody = splitRiddlePrefix(text)
          if riddlePrefix and riddleBody == "" then
              beginRiddleQuestionCapture()
              stopCollecting(true)
              log("Riddle scan captured the trigger; waiting for the question", "sys")
              toast("Scan riddle", "Waiting for the question", false, "good")
          else
              beginRiddleQuestionCapture(riddleBody ~= "" and riddleBody or text)
              log("Riddle scan captured the question; joining nearby parts", "sys")
          end
          return
      end

      local riddlePrefix, riddleBody = splitRiddlePrefix(text)
      if riddlePrefix then
          if riddleBody == "" then
              beginRiddleQuestionCapture()
              stopCollecting(true)
              log("Riddle trigger detected; waiting for the question", "sys")
          else
              beginRiddleQuestionCapture(riddleBody)
              log("Riddle question started; joining nearby parts", "sys")
          end
          return
      end
      if riddleAwaiting then
          -- Keep collecting short fragments so a multi-line riddle is solved
          -- as one ordered question instead of only solving its first line.
          if not matchTrigger(text) then
              queueRiddleQuestionPart(text)
              return
          end
          riddleAwaiting = false
          riddleCaptureDeadline = 0
          riddleCaptureId += 1
          riddleQuestionToken += 1
          riddleQuestionParts = {}
      end

      if retypeListening then
          if os.clock() > rearmDeadline then
              stopCollecting(true)
              return
          end
          -- Keep the already captured parts. capturePart owns the replacement
          -- word so it can bypass deduplication and submit the new candidate.
          local before = #parts
          feedWords(text)
          if #parts == before and not queuedFinalCode then armRetypeListening() end
          return
      end

      if isRiddleAnnouncement(text) then
          beginRiddleQuestionCapture(text)
          return
      end

      if not collecting and settings.armed then
          local standaloneCode = detectStandaloneCode(text)
          if standaloneCode then
              stopCollecting(true)
              startCollecting("standalone")
              parts[1] = standaloneCode
              seen[standaloneCode:upper()] = true
              lastPartAt = os.clock()
              typeIntoBox(standaloneCode, true)
              log("Standalone code detected: " .. standaloneCode, "code")
              if settings.autoSubmit then
                  submitFinal(standaloneCode, collectionGeneration, false)
              else
                  log("Auto submit disabled; standalone code is ready in the box", "sys")
              end
              return
          end
      end

      local trigger, rest = matchTrigger(text)
      if trigger then
          if collecting then
              log("Code segment detected: " .. text, "code")
              local before = #parts
              if rest ~= "" then feedWords(rest) end
              if #parts == before then
                  log("Trigger found, but no code token was captured: " .. trigger, "warn")
              end
              return
          end
          stopCollecting(true)
          startCollecting("trigger")
          log("Trigger detected: " .. text, "code")
          assistant.event("tracking")
          if rest ~= "" then
              local before = #parts
              -- A trigger can carry a complete one-part code directly
              -- ("CODE IS ABC"). Do not make it wait for submitAfter more
              -- announcements; keep the normal collector for multi-word
              -- codes and for manual-submit mode.
              local onePart = trim(rest)
              if settings.autoSubmit and not onePart:find("%s") then
                  local directCode = cleanCode(onePart)
                  if directCode ~= "" then
                      parts[1] = directCode
                      seen[directCode:upper()] = true
                      lastPartAt = os.clock()
                      typeIntoBox(directCode, true)
                      log("Single-part code detected: " .. directCode, "code")
                      submitFinal(directCode, collectionGeneration, false)
                  else
                      feedWords(rest)
                  end
              else
                  feedWords(rest)
              end
              if #parts == before then log("Trigger detected; waiting for the code segment", "sys") end
          else
              log("Waiting for the code segment after " .. trigger, "sys")
          end
          if not settings.armed then UI.setArmed(true, true) end
          return
      end
      if not collecting or not settings.armed then return end
      feedWords(text)
  end
  UI.simulate = onAnnouncement

  local feedActive = false
  local lastFeedAt = os.clock()
  local feedSilenceAlerted = false
  local feedWatchdog = task.spawn(function()
      while gui.Parent and not destroyed do
          task.wait(1)
          if feedActive and os.clock() - lastFeedAt >= settings.feedSilenceTimeout and not feedSilenceAlerted then
              feedSilenceAlerted = true
              log("Announcement feed silent for " .. tostring(settings.feedSilenceTimeout) .. " seconds", "warn")
          end
      end
  end)
  cleanups[#cleanups + 1] = function()
      if feedWatchdog then pcall(task.cancel, feedWatchdog) end
  end

  local hookedNotifyController
  local function hookNotificationController()
      if hookedNotifyController then return true end
      local controllers = ReplicatedStorage:FindFirstChild("Controllers")
      local moduleScript = controllers and controllers:FindFirstChild("NotificationController", true)
      if not moduleScript or not moduleScript:IsA("ModuleScript") then return false end
      local ok, controller = pcall(require, moduleScript)
      if not ok or type(controller) ~= "table" or type(controller.Notify) ~= "function" then return false end
      local original = controller.Notify
      local wrapper
      wrapper = function(...)
          local args = { ... }
          -- The game's Top notification is the announcement channel. Other
          -- Notify calls are rewards/errors and must not become fake riddles.
          -- Both `controller:Notify(text, ..., "Top", ...)` and a dot-call
          -- exist in released builds, so accept both argument layouts.
          local message
          if args[5] == "Top" and type(args[2]) == "string" then
              message = args[2]
          elseif args[4] == "Top" and type(args[1]) == "string" then
              message = args[1]
          end
          if message and trim(message) ~= "" then
              lastFeedAt = os.clock()
              feedActive = true
              feedSilenceAlerted = false
              if notificationCheck then pcall(notificationCheck, { Text = message, Parent = true }) end
              task.defer(function()
                  if not destroyed then pcall(onAnnouncement, message) end
              end)
          end
          return original(table.unpack(args))
      end
      controller.Notify = wrapper
      hookedNotifyController = { module = controller, original = original, wrapper = wrapper }
      cleanups[#cleanups + 1] = function()
          if controller.Notify == wrapper then controller.Notify = original end
          if hookedNotifyController and hookedNotifyController.wrapper == wrapper then hookedNotifyController = nil end
      end
      return true
  end

  local function resolveNotificationRemote()
      local remote
      local function isNotify(value)
          if typeof(value) ~= "Instance" then return false end
          return value:IsA("RemoteEvent") or value:IsA("UnreliableRemoteEvent")
      end
      -- The controller already owns the correct event. Reading Start's
      -- captured RemoteEvent is more reliable than guessing by connection
      -- source, which is often hidden by the executor.
      pcall(function()
          local controllers = ReplicatedStorage:FindFirstChild("Controllers")
          local moduleScript = controllers and controllers:FindFirstChild("NotificationController", true)
          local ok, controller = moduleScript and pcall(require, moduleScript)
          local start = ok and type(controller) == "table" and controller.Start or nil
          local getter = rawget(env, "getupvalues") or rawget(_G, "getupvalues")
          if not getter and debug and type(debug.getupvalues) == "function" then getter = debug.getupvalues end
          if type(getter) == "function" and type(start) == "function" then
              for _, value in pairs(getter(start) or {}) do
                  if isNotify(value) then remote = value break end
              end
          end
      end)
      if remote then return remote end
      pcall(function()
          local packages = ReplicatedStorage:FindFirstChild("Packages")
          local net = packages and packages:FindFirstChild("Net")
          local direct = net and net:FindFirstChild("RE/NotificationService/Notify")
          if isNotify(direct) then remote = direct end
      end)
      if remote then return remote end
      -- Last fallback: preserve the working backup scan for executors that
      -- hide upvalues and do not expose the stable remote name.
      pcall(function()
          local packages = ReplicatedStorage:FindFirstChild("Packages")
          local net = packages and packages:FindFirstChild("Net")
          if not net or type(getconnections) ~= "function" then return end
          for _, d in ipairs(net:GetDescendants()) do
              if isNotify(d) then
                  local ok, list = pcall(getconnections, d.OnClientEvent)
                  for _, c in ipairs(ok and list or {}) do
                      local fn = c.Function
                      if type(fn) == "function" and debugSource(fn):find("NotificationController", 1, true) then
                          remote = d
                          return
                      end
                  end
              end
          end
      end)
      return remote
  end

  task.spawn(function()
      for _ = 1, 20 do
          if destroyed then return end
          local ok, hooked = pcall(hookNotificationController)
          if ok and hooked then return end
          task.wait(0.5)
      end
  end)

  task.spawn(function()
      pcall(hookNotificationController)
      local remote
      for _ = 1, 20 do
          if destroyed then return end
          remote = resolveNotificationRemote()
          if remote then break end
          task.wait(0.5)
      end
      if not gui.Parent then return end
      if not remote and not hookedNotifyController then
          log("Announcement feed not found", "bad")
          return
      end
      UI.feedRemote = remote
      feedActive = true
      log("Announcement feed ready", "good")
      if remote then on(remote.OnClientEvent, function(message, _, _, position)
          if position and position ~= "Top" then return end
          lastFeedAt = os.clock()
          feedSilenceAlerted = false
          local body = type(message) == "table" and (message.Text or message.Message or message.Body or message[1]) or message
          if notificationCheck then notificationCheck({ Text = body, Parent = true }) end
          -- drop echo from FakeAnc (it already called simulate directly)
          if UI._fakeAncEcho and UI._fakeAncEcho == trim(stripRich(body)) then
              UI._fakeAncEcho = nil
              return
          end
          local ok, err = pcall(onAnnouncement, message)
          if not ok then log("Error: " .. tostring(err), "bad") end
      end) end
      -- pre-warm codeUI cache — retry until Codes GUI is present (up to 10s)
      task.spawn(function()
          local deadline = os.clock() + 10
          local preUI
          repeat
              if destroyed then return end
              preUI = resolveUI()
              if not preUI then task.wait(0.1) end
          until preUI or os.clock() > deadline or destroyed
          if destroyed then return end
          if preUI then
              hookNotifier(preUI.notifier)
              log("Code UI cached, notifier hooked", "good")
          else
              log("Code UI not found at startup — will resolve on first redeem", "bad")
          end
      end)

      log("Listening for announcements", "good")
  end)

  end
  UI._installRedeemer()
  UI._installRedeemer = nil

  function UI.destroy()
      if destroyed then return end
      destroyed = true
      settings.armed = false
      manualScanArmed, scanDeadline = false, 0
      riddleScanArmed = false
      riddleAwaiting = false
      riddleCaptureDeadline = 0
      riddleCaptureId += 1
      riddleQuestionToken += 1
      riddleQuestionParts = {}
      snowMotionRunning = false
      if snowLayer then snowLayer.Visible = false end
      pcall(function() UI.cancelTracking() end)
      if savePending then pcall(writeConfig) end
      pcall(stopAutobuy)
      pcall(optimizer.unfreeze)
      if settings.anchor then pcall(anchorCharacter, false) end
      for _, fn in ipairs(cleanups) do pcall(fn) end
      table.clear(cleanups)
      for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
      table.clear(conns)
      if gui then pcall(function() gui.Name = "AZERTOX SNIPER" end); pcall(function() gui:Destroy() end) end
      if env.SkibidiUI == UI then env.SkibidiUI = nil end
  end
  env.SkibidiUI = UI
  local cleanupState = type(env.STATE) == "table" and env.STATE or nil
  if cleanupState and type(cleanupState.onCleanup) == "function" then cleanupState.onCleanup(UI.destroy) end

  holder.Visible = false
  pcall(function() gui.Enabled = true end)
  if UI._setShown then
      UI._setShown(true)
  else
      holder.Visible = true
  end
  print("🛡️ Running AZERTOX Redeemer by Azertox")

  -- ============================================================